import { Router, Request, Response, Application } from 'express';
import { storage } from '../../../storage';
import { insertTargetCustomerProfileSchema, type TargetCustomerProfile, type InsertTargetCustomerProfile } from '@shared/schema';
import { getUserId } from '../../../utils/auth';
import { z } from 'zod';

export function registerCustomerProfilesRoutes(app: Application, requireAuth: any) {
  const router = Router();

  // Get all customer profiles for the authenticated user
  router.get('/', requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const profiles = await storage.listCustomerProfiles(userId);
      res.json(profiles);
    } catch (error) {
      console.error('Error fetching customer profiles:', error);
      res.status(500).json({ 
        message: error instanceof Error ? error.message : 'Failed to fetch customer profiles' 
      });
    }
  });

  // Get specific customer profile
  router.get('/:id', requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const profileId = parseInt(req.params.id);

      if (isNaN(profileId)) {
        return res.status(400).json({ message: 'Invalid profile ID' });
      }

      const profile = await storage.getCustomerProfile(profileId, userId);

      if (!profile) {
        return res.status(404).json({ message: 'Customer profile not found' });
      }

      res.json(profile);
    } catch (error) {
      console.error('Error fetching customer profile:', error);
      res.status(500).json({ 
        message: error instanceof Error ? error.message : 'Failed to fetch customer profile' 
      });
    }
  });

  // Create new customer profile
  router.post('/', requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);

      // Map frontend fields to database fields
      const mappedData = {
        userId,
        label: req.body.title || req.body.exampleCompany || 'Untitled Profile',
        targetDescription: [
          req.body.searchPrompt,
          req.body.additionalContext
        ].filter(Boolean).join(' '),
        industries: req.body.industry ? [req.body.industry] : [],
        roles: req.body.jobTitles || [],
        locations: req.body.geography ? [req.body.geography] : [],
        companySizes: [],
        techStack: req.body.currentSolutions ? [req.body.currentSolutions] : [],
        notes: req.body.additionalContext || ''
      };

      // Validate mapped data
      const parseResult = insertTargetCustomerProfileSchema.safeParse(mappedData);

      if (!parseResult.success) {
        return res.status(400).json({
          message: 'Validation failed',
          errors: parseResult.error.errors
        });
      }

      const profile = await storage.createCustomerProfile(parseResult.data);
      res.status(201).json(profile);

    } catch (error) {
      console.error('Error creating customer profile:', error);
      res.status(500).json({ 
        message: error instanceof Error ? error.message : 'Failed to create customer profile' 
      });
    }
  });

  // Update customer profile
  router.put('/:id', requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const profileId = parseInt(req.params.id);

      if (isNaN(profileId)) {
        return res.status(400).json({ message: 'Invalid profile ID' });
      }

      // Check if profile exists and belongs to user
      const existing = await storage.getCustomerProfile(profileId, userId);
      if (!existing) {
        return res.status(404).json({ message: 'Customer profile not found' });
      }

      // Map frontend fields to database fields for update
      const mappedData: any = {};

      if (req.body.title !== undefined) mappedData.label = req.body.title;
      if (req.body.exampleCompany !== undefined) mappedData.label = req.body.exampleCompany;

      if (req.body.searchPrompt !== undefined || req.body.additionalContext !== undefined) {
        mappedData.targetDescription = [
          req.body.searchPrompt,
          req.body.additionalContext
        ].filter(Boolean).join(' ');
      }

      if (req.body.industry !== undefined) mappedData.industries = req.body.industry ? [req.body.industry] : [];
      if (req.body.jobTitles !== undefined) mappedData.roles = req.body.jobTitles;
      if (req.body.geography !== undefined) mappedData.locations = req.body.geography ? [req.body.geography] : [];
      if (req.body.companySize !== undefined) mappedData.companySizes = req.body.companySize ? [req.body.companySize] : [];
      if (req.body.currentSolutions !== undefined) mappedData.techStack = req.body.currentSolutions ? [req.body.currentSolutions] : [];
      if (req.body.additionalContext !== undefined) mappedData.notes = req.body.additionalContext;

      // Validate update data
      const updateSchema = insertTargetCustomerProfileSchema.partial().omit({ userId: true });
      const parseResult = updateSchema.safeParse(mappedData);

      if (!parseResult.success) {
        return res.status(400).json({
          message: 'Validation failed',
          errors: parseResult.error.errors
        });
      }

      const updated = await storage.updateCustomerProfile(profileId, parseResult.data);
      res.json(updated);

    } catch (error) {
      console.error('Error updating customer profile:', error);
      res.status(500).json({ 
        message: error instanceof Error ? error.message : 'Failed to update customer profile' 
      });
    }
  });

  // Delete customer profile
  router.delete('/:id', requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const profileId = parseInt(req.params.id);

      if (isNaN(profileId)) {
        return res.status(400).json({ message: 'Invalid profile ID' });
      }

      // Check if profile exists and belongs to user
      const existing = await storage.getCustomerProfile(profileId, userId);
      if (!existing) {
        return res.status(404).json({ message: 'Customer profile not found' });
      }

      await storage.deleteCustomerProfile(profileId, userId);
      res.status(204).send();

    } catch (error) {
      console.error('Error deleting customer profile:', error);
      res.status(500).json({ 
        message: error instanceof Error ? error.message : 'Failed to delete customer profile' 
      });
    }
  });

  app.use('/api/customer-profiles', router);
}

server/user-chatbox/html-static/routes.t.content:
/**
 * @deprecated HTML Static Chat Routes
 * These endpoints support the legacy HTML landing page at '/'
 * New development should use the React version in ../react/
 */

import { Express } from "express";
import { storage } from "../../storage";
import { queryPerplexity } from "../../search/perplexity/perplexity-client";
import type { PerplexityMessage } from "../../search/perplexity/perplexity-types";

// Helper function to safely get user ID from request
function getUserId(req: any): number {
  try {
    // First check if user is authenticated through session
    if (req.isAuthenticated && req.isAuthenticated() && req.user && req.user.id) {
      return req.user.id;
    }

    // Then check for Firebase authentication
    if (req.firebaseUser && req.firebaseUser.id) {
      return req.firebaseUser.id;
    }
  } catch (error) {
    console.error('Error accessing user ID:', error);
  }

  // For non-authenticated users, fall back to demo user ID (1)
  return 1;
}

// Helper functions for extracting profile data
function extractAttributes(message: string): string[] {
  // Simple implementation - could be enhanced later
  return message.split(',').map(s => s.trim()).filter(s => s.length > 0);
}

function extractMarketNiche(message: string): string {
  // Simple implementation - could be enhanced later
  return message.toLowerCase().includes('niche') ? 'niche' : 'broad';
}

function generateSearchPrompts(profileData: any, businessType: string): string[] {
  // Simple implementation - could be enhanced later
  return [
    `${businessType} for ${profileData.targetCustomers || 'businesses'}`,
    `${profileData.businessDescription || businessType} solutions`,
    `Find ${profileData.targetCustomers || 'customers'} who need ${businessType}`
  ];
}

export function registerHtmlStaticChatRoutes(app: Express) {

  // Strategic Onboarding Chat Endpoint (DEPRECATED - HTML Landing Page Version)
  app.post("/api/onboarding/chat", async (req, res) => {
    try {
      const { message, businessType, currentStep, profileData, conversationHistory, researchResults } = req.body;

      if (!message || !businessType) {
        res.status(400).json({ message: "Missing required parameters" });
        return;
      }

      // Define the conversation flow steps
      const stepFlow = {
        customer_example: {
          next: "unique_attributes",
          systemPrompt: "You are a strategic sales consultant with real-time market research capabilities. Keep responses very short - 1-2 sentences max. Research the user's industry when mentioned. Ask one specific question.",
          userPrompt: (type: string) => `The user is providing an example of their customer. They said: "${message}". Ask one specific follow-up question about their customer base or market segment.`
        },
        business_description: {
          next: "unique_attributes",
          systemPrompt: "You are a strategic sales consultant with real-time market research capabilities. Keep responses very short - 1-2 sentences max. Research the user's industry when mentioned. Ask one specific question.",
          userPrompt: (type: string) => `The user is selling a ${type}. They said: "${message}". Research this industry briefly and ask one specific question about what makes their ${type} unique or different from competitors.`
        },
        unique_attributes: {
          next: "target_customers", 
          systemPrompt: "Keep responses very short - 1-2 sentences max. Use market research to understand their competitive landscape. Ask one specific question about target customers.",
          userPrompt: () => `Based on their business description, research their market and ask one specific question about who their ideal customers are - what type of businesses or people they sell to.`
        },
        target_customers: {
          next: "market_positioning",
          systemPrompt: "Keep responses very short - 1-2 sentences max. Research market trends for their target customer segment. Ask one specific question about market approach.",
          userPrompt: () => `Research current trends for their target market and ask one question about their market focus - geographic area, company size, or industry niche.`
        },
        market_positioning: {
          next: "strategic_plan",
          systemPrompt: "Keep responses very short - 1-2 sentences max. Research their competitive positioning. Summarize briefly and ask for confirmation.",
          userPrompt: () => `Research their market position and briefly summarize their business strategy in 1-2 sentences. Ask if they want to generate research-backed search prompts.`
        },
        strategic_plan: {
          next: "complete",
          systemPrompt: "Keep responses very short - 1-2 sentences max. Provide market-informed strategic insights.",
          userPrompt: () => `Based on market research, I'll create your strategic profile and generate targeted search prompts that leverage current market opportunities.`
        }
      };

      const currentStepConfig = stepFlow[currentStep as keyof typeof stepFlow];
      if (!currentStepConfig) {
        res.status(400).json({ message: "Invalid step" });
        return;
      }

      // Prepare messages for OpenAI with conversation history
      const openaiMessages = [
        {
          role: "system" as const,
          content: currentStepConfig.systemPrompt
        }
      ];

      // Add conversation history from the current session
      if (conversationHistory && conversationHistory.length > 0) {
        // Skip the initial personalized message to avoid role alternation issues
        // Start from the first user message (customer example)
        const previousMessages = conversationHistory.slice(0, -1);
        const userMessages = previousMessages.filter((msg: any) => msg.sender === 'user');
        const aiMessages = previousMessages.filter((msg: any) => msg.sender === 'ai' && !msg.content.includes("Perfect! So you're selling"));

        // Only include alternating messages starting with user messages
        let lastRole = 'system';
        for (const msg of previousMessages) {
          // Skip the initial personalized message
          if (msg.sender === 'ai' && msg.content.includes("Perfect! So you're selling")) {
            continue;
          }

          if (msg.sender === 'ai' && lastRole !== 'assistant') {
            openaiMessages.push({
              role: "assistant" as const,
              content: msg.content
            });
            lastRole = 'assistant';
          } else if (msg.sender === 'user' && lastRole !== 'user') {
            openaiMessages.push({
              role: "user" as const,
              content: msg.content
            });
            lastRole = 'user';
          }
        }
      }

      // Add the new user message
      openaiMessages.push({
        role: "user" as const,
        content: message
      });

      // If we have background research results, add them to the system context
      if (researchResults && researchResults.research) {
        openaiMessages[0].content += `\n\nBACKGROUND RESEARCH COMPLETED:\n${researchResults.research}\n\nUse this research to provide informed, strategic insights in your response.`;
      }

      // Get AI response from Perplexity for real-time market research
      const perplexityMessages: PerplexityMessage[] = openaiMessages.map(msg => ({
        role: msg.role as "system" | "user" | "assistant",
        content: msg.content
      }));

      const aiResponse = await queryPerplexity(perplexityMessages);

      // Process the response and update profile data
      let profileUpdate: any = {};
      let nextStep = currentStep;
      let completed = false;

      // Extract information based on current step
      switch (currentStep) {
        case "business_description":
          profileUpdate.businessDescription = message;
          nextStep = currentStepConfig.next;
          break;
        case "unique_attributes":
          profileUpdate.uniqueAttributes = extractAttributes(message);
          nextStep = currentStepConfig.next;
          break;
        case "target_customers":
          profileUpdate.targetCustomers = message;
          nextStep = currentStepConfig.next;
          break;
        case "market_positioning":
          profileUpdate.marketNiche = extractMarketNiche(message);
          nextStep = currentStepConfig.next;
          break;
        case "strategic_plan":
          completed = true;
          profileUpdate.status = "completed";
          profileUpdate.searchPrompts = generateSearchPrompts(profileData, businessType);
          break;
      }

      // If user is authenticated, save profile to database
      if (req.user) {
        try {
          const userId = getUserId(req);

          // Create or update strategic profile
          const existingProfiles = await storage.getStrategicProfiles?.(userId) || [];

          if (existingProfiles.length > 0) {
            // Update existing profile
            await storage.updateStrategicProfile?.(existingProfiles[0].id, {
              ...profileData,
              ...profileUpdate,
              businessType,
              updatedAt: new Date()
            });
          } else {
            // Create new profile
            await storage.createStrategicProfile?.({
              userId,
              title: profileUpdate.businessDescription || profileData.businessDescription || "Strategy Plan",
              businessType,
              businessDescription: profileUpdate.businessDescription || profileData.businessDescription || "",
              targetCustomers: profileUpdate.targetCustomers || profileData.targetCustomers || "",
              ...profileUpdate
            });
          }
        } catch (error) {
          console.error("Error saving strategic profile:", error);
          // Continue without failing - user can still use the interface
        }
      }

      res.json({
        aiResponse,
        profileUpdate,
        nextStep,
        completed
      });

    } catch (error) {
      console.error("Onboarding chat error:", error);
      res.status(500).json({
        message: "Failed to process chat message. Please check your AI service configuration."
      });
    }
  });

  // Background Research Endpoint
  app.post("/api/onboarding/research", async (req, res) => {
    try {
      const { businessType, formData } = req.body;

      if (!businessType || !formData) {
        res.status(400).json({ message: "Missing required parameters" });
        return;
      }

      console.log(`Starting background research for ${businessType}:`, formData);

      // Construct enhanced research prompt based on comprehensive product profile
      const researchPrompt = `Conduct comprehensive market research for this ${businessType} business:

**Business Profile:**
Product/Service: ${formData.productService}
Location: ${formData.businessLocation || 'Not specified'}
Target Customers: ${formData.primaryCustomerType || 'Not specified'}
Customer Feedback: ${formData.customerFeedback}
Current Sales Channel: ${formData.primarySalesChannel || 'Not specified'}
Primary Business Goal: ${formData.primaryBusinessGoal || 'Not specified'}
Website/Link: ${formData.website || 'Not provided'}

Please research and provide:
1. **Industry Overview & Market Trends** - Current state and growth opportunities in their industry
2. **Local Market Analysis** - Specific insights for their geographic location and market dynamics
3. **Competitive Landscape** - Key competitors, their positioning, and market gaps
4. **Target Customer Analysis** - Deep dive into their customer segment, needs, and purchasing behavior
5. **Sales Channel Optimization** - Analysis of their current approach and better alternatives
6. **Strategic Opportunities** - Specific recommendations aligned with their business goal
7. **90-Day Action Plan** - Tactical steps they can take immediately

Focus on actionable insights that directly support their stated business goal and customer segment.`;

      const researchMessages: PerplexityMessage[] = [
        {
          role: "system",
          content: "You are a market research analyst with access to current market data. Provide comprehensive, up-to-date market intelligence and strategic insights."
        },
        {
          role: "user", 
          content: researchPrompt
        }
      ];

      // Get research from Perplexity
      const researchResults = await queryPerplexity(researchMessages);

      console.log('Background research completed successfully');

      res.json({
        businessType,
        formData,
        research: researchResults,
        timestamp: new Date().toISOString()
      });

    } catch (error: any) {
      console.error("Background research error:", error);
      res.status(500).json({
        message: "Failed to complete background research",
        error: error.message
      });
    }
  });
}

server/search/contacts/performance-logge.content:
import type { Contact } from "@shared/schema";
import type { EnhancedContactFinderOptions } from "./enhanced-contact-finder";

export interface SearchPhaseMetrics {
  phaseName: string;
  enabled: boolean;
  executed: boolean;
  contactsFound: number;
  highQualityContacts: number;
  executionTime: number;
  skippedReason?: string;
}

export interface FallbackMetrics {
  triggered: boolean;
  reason: string;
  fallbacksExecuted: string[];
  contactsAdded: number;
  totalExecutionTime: number;
}

export interface SearchSessionMetrics {
  companyName: string;
  startTime: number;
  endTime: number;
  totalDuration: number;
  originalConfig: EnhancedContactFinderOptions;
  searchPhases: SearchPhaseMetrics[];
  fallbackMetrics?: FallbackMetrics;
  finalContactCount: number;
  finalHighQualityCount: number;
  apiCallsTotal: number;
  rateLimitingDelay: number;
}

export class SearchPerformanceLogger {
  private static sessions: Map<string, SearchSessionMetrics> = new Map();

  static startSession(companyName: string, config: EnhancedContactFinderOptions): string {
    const sessionId = `${companyName}_${Date.now()}`;
    const session: SearchSessionMetrics = {
      companyName,
      startTime: Date.now(),
      endTime: 0,
      totalDuration: 0,
      originalConfig: { ...config },
      searchPhases: [],
      finalContactCount: 0,
      finalHighQualityCount: 0,
      apiCallsTotal: 0,
      rateLimitingDelay: 0
    };

    this.sessions.set(sessionId, session);
    console.log(`Search session started for ${companyName} [${sessionId}]`);
    return sessionId;
  }

  static logSearchPhase(
    sessionId: string, 
    phaseName: string, 
    enabled: boolean, 
    executed: boolean,
    contacts: Partial<Contact>[] = [],
    executionTime: number = 0,
    skippedReason?: string
  ) {
    const session = this.sessions.get(sessionId);
    if (!session) return;

    const highQualityContacts = contacts.filter(c => (c.probability || 0) >= 70).length;

    const phaseMetrics: SearchPhaseMetrics = {
      phaseName,
      enabled,
      executed,
      contactsFound: contacts.length,
      highQualityContacts,
      executionTime,
      skippedReason
    };

    session.searchPhases.push(phaseMetrics);
    session.apiCallsTotal += executed ? 1 : 0;
    session.rateLimitingDelay += executed ? 200 : 0;

    const status = executed ? 
      `✓ ${contacts.length} contacts (${highQualityContacts} high-quality)` :
      `⏭ ${skippedReason || 'disabled'}`;

    console.log(`[${sessionId}] ${phaseName}: ${status}`);
  }

  static logFallback(
    sessionId: string,
    triggered: boolean,
    reason: string,
    fallbacksExecuted: string[] = [],
    contactsAdded: number = 0,
    executionTime: number = 0
  ) {
    const session = this.sessions.get(sessionId);
    if (!session) return;

    session.fallbackMetrics = {
      triggered,
      reason,
      fallbacksExecuted,
      contactsAdded,
      totalExecutionTime: executionTime
    };

    session.apiCallsTotal += fallbacksExecuted.length;
    session.rateLimitingDelay += fallbacksExecuted.length * 200;

    if (triggered) {
      console.log(`[${sessionId}] Smart fallback: ${reason}`);
      console.log(`[${sessionId}] Executed fallbacks: ${fallbacksExecuted.join(', ')}`);
      console.log(`[${sessionId}] Added ${contactsAdded} contacts`);
    }
  }

  static endSession(sessionId: string, finalContacts: Partial<Contact>[]): SearchSessionMetrics | null {
    const session = this.sessions.get(sessionId);
    if (!session) return null;

    session.endTime = Date.now();
    session.totalDuration = session.endTime - session.startTime;
    session.finalContactCount = finalContacts.length;
    session.finalHighQualityCount = finalContacts.filter(c => (c.probability || 0) >= 70).length;

    // Generate comprehensive summary
    console.log(`\n=== Search Session Complete [${sessionId}] ===`);
    console.log(`Company: ${session.companyName}`);
    console.log(`Duration: ${session.totalDuration}ms`);
    console.log(`API Calls: ${session.apiCallsTotal}`);
    console.log(`Rate Limiting Delay: ${session.rateLimitingDelay}ms`);
    console.log(`Final Results: ${session.finalContactCount} contacts (${session.finalHighQualityCount} high-quality)`);

    console.log(`\nSearch Phases:`);
    session.searchPhases.forEach(phase => {
      const icon = phase.executed ? '✓' : '⏭';
      const details = phase.executed ? 
        `${phase.contactsFound} contacts (${phase.highQualityContacts} HQ)` :
        phase.skippedReason || 'disabled';
      console.log(`  ${icon} ${phase.phaseName}: ${details}`);
    });

    if (session.fallbackMetrics?.triggered) {
      console.log(`\nSmart Fallback:`);
      console.log(`  Reason: ${session.fallbackMetrics.reason}`);
      console.log(`  Executed: ${session.fallbackMetrics.fallbacksExecuted.join(', ')}`);
      console.log(`  Added: ${session.fallbackMetrics.contactsAdded} contacts`);
    }

    console.log(`=====================================\n`);

    // Clean up session
    this.sessions.delete(sessionId);
    return session;
  }

  static getSessionMetrics(sessionId: string): SearchSessionMetrics | null {
    return this.sessions.get(sessionId) || null;
  }

  // Analysis methods
  static analyzeEfficiency(session: SearchSessionMetrics): {
    efficiency: number;
    recommendations: string[];
  } {
    const recommendations: string[] = [];

    // Calculate efficiency based on contacts per API call
    const contactsPerCall = session.apiCallsTotal > 0 ? 
      session.finalContactCount / session.apiCallsTotal : 0;

    const efficiency = Math.min(contactsPerCall * 10, 100); // Scale to 0-100

    // Analyze search phase efficiency
    const executedPhases = session.searchPhases.filter(p => p.executed);
    const unproductivePhases = executedPhases.filter(p => p.contactsFound === 0);

    if (unproductivePhases.length > 0) {
      recommendations.push(`Consider disabling: ${unproductivePhases.map(p => p.phaseName).join(', ')}`);
    }

    // Analyze fallback effectiveness
    if (session.fallbackMetrics?.triggered && session.fallbackMetrics.contactsAdded === 0) {
      recommendations.push('Fallback searches were unproductive - consider adjusting thresholds');
    }

    // Analyze total API usage
    if (session.apiCallsTotal >= 4 && session.finalContactCount < 5) {
      recommendations.push('High API usage with low results - optimize search configuration');
    }

    return { efficiency, recommendations };
  }
}

