  async createEmailSend(data: InsertEmailSend): Promise<EmailSend> {
    const [send] = await db.insert(emailSends)
      .values({
        recipientEmail: data.recipientEmail,
        recipientName: data.recipientName,
        sequenceId: data.sequenceId,
