  async getEmailSendsByRecipient(email: string): Promise<EmailSend[]> {
    return db.select()
      .from(emailSends)
      .where(eq(emailSends.recipientEmail, email.toLowerCase()))
      .orderBy(desc(emailSends.createdAt));
  }

  async getPendingEmailSends(limit: number = 50): Promise<EmailSend[]> {
    const now = new Date();
    return db.select()
      .from(emailSends)
      .where(and(
        eq(emailSends.status, 'scheduled'),
        lt(emailSends.scheduledFor, now)
      ))
      .orderBy(emailSends.scheduledFor)
      .limit(limit);
  }

  async updateEmailSendStatus(id: number, status: string, errorMessage?: string): Promise<EmailSend | undefined> {
    const [updated] = await db.update(emailSends)
      .set({
        status,
        errorMessage: errorMessage || null,
        retryCount: status === 'failed' ? sql`${emailSends.retryCount} + 1` : emailSends.retryCount,
        updatedAt: new Date()
      })
      .where(eq(emailSends.id, id))
      .returning();
    return updated;
  }

  async markEmailSendAsSent(id: number): Promise<EmailSend | undefined> {
    const [updated] = await db.update(emailSends)
      .set({
        status: 'sent',
        sentAt: new Date(),
        updatedAt: new Date()
      })
      .where(eq(emailSends.id, id))
      .returning();
    return updated;
  }

  // Guidance Videos
  async createGuidanceVideo(data: InsertGuidanceVideo): Promise<GuidanceVideo> {
    const [video] = await db.insert(guidanceVideos)
      .values({
        challengeId: data.challengeId,
        questId: data.questId,
        rawPath: data.rawPath,
        timestamps: data.timestamps || [],
        status: data.status || 'pending',
        createdBy: data.createdBy
      })
      .returning();
    return video;
  }

  async getGuidanceVideo(id: number): Promise<GuidanceVideo | undefined> {
    const [video] = await db.select()
      .from(guidanceVideos)
      .where(eq(guidanceVideos.id, id));
    return video;
  }

  async getGuidanceVideoByChallenge(challengeId: string): Promise<GuidanceVideo | undefined> {
    const [video] = await db.select()
      .from(guidanceVideos)
      .where(eq(guidanceVideos.challengeId, challengeId))
      .orderBy(desc(guidanceVideos.createdAt))
      .limit(1);
    return video;
  }

  async updateGuidanceVideo(id: number, data: Partial<GuidanceVideo>): Promise<void> {
    await db.update(guidanceVideos)
      .set({ ...data, updatedAt: new Date() })
      .where(eq(guidanceVideos.id, id));
  }

  // User Onboarding Snapshot Implementation (immutable - append only)
  async createUserOnboardingSnapshot(data: InsertUserOnboardingSnapshot): Promise<UserOnboardingSnapshot> {
    const [snapshot] = await db.insert(userOnboardingSnapshot)
      .values({
        userId: data.userId,
        company: data.company || {},
        userGoals: data.userGoals || {},
        product: data.product || {},
        source: data.source || 'onboarding'
      })
      .returning();
    return snapshot;
  }

  async getUserOnboardingSnapshot(userId: number): Promise<UserOnboardingSnapshot | undefined> {
    const [snapshot] = await db.select()
      .from(userOnboardingSnapshot)
      .where(eq(userOnboardingSnapshot.userId, userId))
      .orderBy(desc(userOnboardingSnapshot.capturedAt))
      .limit(1);
    return snapshot;
  }
}

