/**
 * Custom hook for managing user preferences
 * Provides preferences data fetching and update functionality
 */

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";
import { userAccountApi } from "../services/api";
import type { UserPreferences, UserEmailPreferences } from "../types";

export function usePreferences() {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch user preferences
  const preferencesQuery = useQuery<UserPreferences>({
    queryKey: ["/api/user/preferences"],
    queryFn: userAccountApi.getPreferences,
  });

  // Update preferences mutation
  const updatePreferencesMutation = useMutation({
    mutationFn: (preferences: UserPreferences) => userAccountApi.updatePreferences(preferences),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/user/preferences"] });
    },
    onError: (error: any) => {
      toast({
        title: "Update failed",
        description: error.message || "Failed to update preferences.",
        variant: "destructive",
      });
    },
  });

  return {
    preferences: preferencesQuery.data,
    isLoading: preferencesQuery.isLoading,
    error: preferencesQuery.error,
    updatePreferences: updatePreferencesMutation.mutate,
    isUpdating: updatePreferencesMutation.isPending,
  };
}

export function useEmailPreferences() {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch email preferences
  const emailPreferencesQuery = useQuery<UserEmailPreferences>({
    queryKey: ["/api/email-preferences"],
    queryFn: userAccountApi.getEmailPreferences,
  });

  // Update email preferences mutation
  const updateEmailPreferencesMutation = useMutation({
    mutationFn: (preferences: Partial<UserEmailPreferences>) => 
      userAccountApi.updateEmailPreferences(preferences),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/email-preferences"] });
    },
    onError: (error: any) => {
      toast({
        title: "Update failed",
        description: error.message || "Failed to update email preferences.",
        variant: "destructive",
      });
    },
  });

  return {
    emailPreferences: emailPreferencesQuery.data,
    isLoading: emailPreferencesQuery.isLoading,
    error: emailPreferencesQuery.error,
    updateEmailPreferences: updateEmailPreferencesMutation.mutate,
    isUpdating: updateEmailPreferencesMutation.isPending,
  };
}

/**
 * API service for User Account Settings
 * Consolidates all user account related API calls
 */

import { apiRequest } from "@/lib/queryClient";
import type {
  UserProfile,
  ProfileFormData,
  SubscriptionStatus,
  UserPreferences,
  UserEmailPreferences,
  CreditData
} from "../types";

/**
 * Helper to make authenticated GET requests with both session cookie and Firebase token
 * This ensures requests work even when returning to an idle tab
 */
async function authorizedFetch(url: string): Promise<Response> {
  const headers: HeadersInit = {};
  const authToken = localStorage.getItem('authToken');
  if (authToken) {
    headers['Authorization'] = `Bearer ${authToken}`;
  }

  return fetch(url, {
    credentials: 'include',
    headers
  });
}

export const userAccountApi = {
  // Profile endpoints
  getProfile: async (): Promise<UserProfile> => {
    const response = await authorizedFetch("/api/user/profile");
    if (!response.ok) throw new Error("Failed to fetch profile");
    return response.json();
  },

  updateProfile: async (data: ProfileFormData): Promise<UserProfile> => {
    const response = await apiRequest("PUT", "/api/user/profile", data);
    return response.json();
  },

  // User preferences endpoints
  getPreferences: async (): Promise<UserPreferences> => {
    const response = await authorizedFetch("/api/user/preferences");
    if (!response.ok) throw new Error("Failed to fetch preferences");
    return response.json();
  },

  updatePreferences: async (preferences: UserPreferences): Promise<UserPreferences> => {
    return apiRequest("POST", "/api/user/preferences", preferences);
  },

  // Email preferences endpoints
  getEmailPreferences: async (): Promise<UserEmailPreferences> => {
    const response = await apiRequest("GET", "/api/email-preferences");
    if (!response.ok) throw new Error("Failed to fetch email preferences");
    return response.json();
  },

  updateEmailPreferences: async (preferences: Partial<UserEmailPreferences>): Promise<UserEmailPreferences> => {
    const response = await apiRequest("PUT", "/api/email-preferences", preferences);
    return response.json();
  },

  // Subscription endpoints
  getSubscriptionStatus: async (): Promise<SubscriptionStatus> => {
    const response = await authorizedFetch("/api/user/subscription-status");
    if (!response.ok) throw new Error("Failed to fetch subscription status");
    return response.json();
  },

  // Credits endpoints
  getCredits: async (): Promise<CreditData> => {
    const response = await authorizedFetch("/api/credits");
    if (!response.ok) throw new Error("Failed to fetch credits");
    return response.json();
  }
};

