@tailwind base;
@tailwind components;
@tailwind utilities;

/* Loading screen animations - CSS-only for instant display */
@keyframes loading-appear {
  from {
    opacity: 0;
    transform: scale(0.8);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes loading-text-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

.animate-loading-appear {
  animation: loading-appear 0.3s ease-out forwards;
}

.animate-loading-text {
  opacity: 0;
  animation: loading-text-fade 0.3s ease-out 0.2s forwards;
}

/* Global focus styles - Only show for keyboard navigation, not mouse clicks */
*:focus:not(:focus-visible) {
  outline: none !important;
}

*:focus-visible {
  outline: 2px solid rgba(147, 197, 253, 0.05) !important; /* light-blue-300 at 5% opacity */
  outline-offset: 1px;
}

/* Custom thin dark scrollbar for modals */
.custom-scrollbar::-webkit-scrollbar {
  width: 6px;
}
.custom-scrollbar::-webkit-scrollbar-track {
  background: transparent;
}
.custom-scrollbar::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}
.custom-scrollbar::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.3);
}
/* Firefox support */
.custom-scrollbar {
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}

/* Gmail-style indeterminate checkbox - blue styling */
input[type="checkbox"]:indeterminate {
  background-color: rgb(59, 130, 246) !important; /* blue-500 */
  border-color: rgb(59, 130, 246) !important;
}

/* Ensure the indeterminate indicator (dash) is white/visible */
input[type="checkbox"]:indeterminate::before {
  background-color: white !important;
}

/* iOS Safari auto-zoom prevention - mobile only */
.mobile-input-text-fix {
  font-size: 16px;
}

@media (min-width: 768px) {
  .mobile-input-text-fix {
    font-size: 14px; /* Restore original text-sm size on desktop */
  }
}

/* Email drawer push-aside animations */
.email-drawer-transition {
  transition: width 300ms cubic-bezier(0.4, 0, 0.2, 1),
              transform 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* Search drawer push-aside animations */
.search-drawer-transition {
  transition: width 300ms cubic-bezier(0.4, 0, 0.2, 1),
              transform 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

.main-content-compressed {
  transition: all 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* Hide scrollbar when email drawer is open (but keep scrolling functionality) */
.main-content-compressed.compressed-view {
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* IE and Edge */
}

.main-content-compressed.compressed-view::-webkit-scrollbar {
  display: none; /* Chrome, Safari, Opera */
}

/* Ensure tables and cards compress properly */
@media (min-width: 768px) {
  .compressed-view .md\:table-cell {
    display: none;
  }

  .compressed-view .lg\:table-cell {
    display: table-cell;
  }

  .compressed-view .container {
    max-width: 100%;
    padding-left: 1rem;
    padding-right: 1rem;
  }
}

/* Mobile focus enhancement - simple internal border only */
@media (max-width: 767px) {

  .mobile-input-border {
    transition: box-shadow 0.3s ease;
    box-shadow: inset 0 0 0 0 transparent;
  }

  .mobile-input-border:focus {
    box-shadow: inset 0 0 0 1px rgba(156, 163, 175, 0.3);
  }

  .mobile-input-border:focus-visible {
    outline: none !important;
    border-color: transparent !important;
    box-shadow: inset 0 0 0 1px rgba(156, 163, 175, 0.3) !important;
    ring: 0 !important;
    ring-offset: 0 !important;
    --tw-ring-shadow: 0 0 #0000 !important;
    --tw-ring-offset-shadow: 0 0 #0000 !important;
  }
}


/* Custom fluffy gradient backgrounds */
.fluffy-gradient-bg {
  background-image: 
    radial-gradient(
      circle at 75% 30%,
      rgba(253, 224, 71, 0.15) 0%,
      rgba(253, 224, 71, 0.03) 25%,
      transparent 50%
    ),
    radial-gradient(
      circle at 20% 40%,
      rgba(249, 168, 212, 0.15) 0%,
      rgba(249, 168, 212, 0.03) 30%,
      transparent 60%
    ),
    radial-gradient(
      circle at 65% 65%,
      rgba(219, 234, 254, 0.8) 0%,
      rgba(219, 234, 254, 0.5) 40%,
      rgba(224, 242, 254, 0.3) 70%
    ),
    radial-gradient(
      circle at 20% 80%,
      rgba(167, 243, 208, 0.15) 0%,
      rgba(167, 243, 208, 0.03) 30%,
      transparent 60%
    );
  background-size: 120% 120%;
  background-position: center;
}

.dark .fluffy-gradient-bg {
  background-image: 
    radial-gradient(
      circle at 75% 30%,
      rgba(253, 224, 71, 0.1) 0%,
      rgba(253, 224, 71, 0.02) 25%,
      transparent 50%
    ),
    radial-gradient(
      circle at 20% 40%,
      rgba(249, 168, 212, 0.1) 0%,
      rgba(249, 168, 212, 0.02) 30%,
      transparent 60%
    ),
    radial-gradient(
      circle at 65% 65%,
      rgba(30, 58, 138, 0.25) 0%,
      rgba(37, 99, 235, 0.2) 40%,
      rgba(29, 78, 216, 0.1) 70%
    ),
    radial-gradient(
      circle at 20% 80%,
      rgba(167, 243, 208, 0.1) 0%,
      rgba(167, 243, 208, 0.02) 30%,
      transparent 60%
    );
  background-size: 120% 120%;
  background-position: center;
}

/* Racing light animation for search input */
@keyframes racingLight {
  0% {
    box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.15);
    border-color: rgba(59, 130, 246, 0.25);
  }
  25% {
    box-shadow: 0 0 0 2px rgba(14, 165, 233, 0.35);
    border-color: rgba(14, 165, 233, 0.45);
  }
  50% {
    box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.55);
    border-color: rgba(56, 189, 248, 0.65);
  }
  75% {
    box-shadow: 0 0 0 2px rgba(14, 165, 233, 0.35);
    border-color: rgba(14, 165, 233, 0.45);
  }
  100% {
    box-shadow: 0 0 0 1px rgba(59, 130, 246, 0.15);
    border-color: rgba(59, 130, 246, 0.25);
  }
}

.racing-light-effect {
  animation: racingLight 3.5s ease-in-out;
  animation-delay: 1.2s;
  animation-iteration-count: 1;
}

/* Gradient text effect for highlighting the landing page prompt */
@keyframes gradientFadeIn {
  0% {
    color: inherit;
    font-weight: normal;
  }
  100% {
    color: transparent;
    font-weight: 500;
  }
}

.gradient-text-input {
  color: transparent;
  background-image: linear-gradient(to right, #3b82f6, #0ea5e9, #06b6d4);
  background-clip: text;
  -webkit-background-clip: text;
  font-weight: 400;
  animation: gradientFadeIn 2s ease;
  animation-delay: 1.2s;
  animation-fill-mode: backwards;
}



/* Mobile input field styling - edge-to-edge with borders and subtle background */
@media (max-width: 768px) {
  .mobile-input {
    background-color: rgb(248, 250, 252);
    transition: background-color 0.2s ease;
  }

  .mobile-input:focus,
  .mobile-input:active {
    background-color: rgb(241, 245, 249);
  }
}

@layer base {
  :root {
    --font-sans: 'Outfit', sans-serif;
    --font-heading: 'Outfit', sans-serif;
    --font-serif: 'DM Serif Display', serif;
    --font-code: 'Courier New', monospace;

    /* Light Theme Colors - warm brownish tones */
    --background: 42 22% 90%;
    --background-hover: 42 20% 87%;
    --foreground: 42 15% 12%;

    --primary: 45 93% 47%;
    --primary-foreground: 30 10% 10%;

    --secondary: 35 8% 94%;
    --secondary-hover: 42 12% 88%;
    --secondary-foreground: 30 8% 15%;

    --muted: 42 15% 94%;
    --muted-hover: 42 18% 90%;
    --muted-foreground: 42 12% 55%;

    --accent: 25 55% 35%;
    --accent-light: 25 60% 55%;
    --accent-dark: 25 55% 25%;
    --accent-foreground: 25 55% 95%;
    --accent-hover: 25 55% 35% / 0.1;
    --accent-active: 25 55% 35% / 0.15;
    --accent-border-hover: 25 55% 35% / 0.3;

    --card: 42 18% 96%;
    --card-hover: 40 15% 99%;
    --card-foreground: 30 10% 10%;

    --popover: 40 15% 99%;
    --popover-foreground: 30 10% 10%;

    --panel-background: 42 20% 86%;

    --border: 35 8% 88%;
    --input: 30 30% 96%;
    --ring: 45 93% 47% / 0.05;

    --destructive: 0 84% 60%;
    --destructive-foreground: 0 0% 100%;

    --radius: 0.5rem;
  }

  /* Dark Theme Colors - warm brownish-gray tones */
  .dark {
    --background: 42 18% 7%;
    --background-hover: 42 16% 10%;
    --foreground: 35 10% 98%;

    --primary: 45 93% 52%;
    --primary-foreground: 30 8% 6%;

    --secondary: 30 6% 14%;
    --secondary-hover: 42 8% 18%;
    --secondary-foreground: 35 10% 98%;

    --muted: 42 8% 16%;
    --muted-hover: 42 10% 20%;
    --muted-foreground: 42 8% 60%;

    --accent: 25 45% 55%;
    --accent-light: 25 55% 70%;
    --accent-dark: 25 45% 45%;
    --accent-foreground: 25 20% 10%;
    --accent-hover: 25 45% 55% / 0.1;
    --accent-active: 25 45% 55% / 0.15;
    --accent-border-hover: 25 45% 55% / 0.3;

    --card: 30 8% 6%;
    --card-hover: 42 10% 10%;
    --card-foreground: 35 10% 98%;

    --popover: 30 8% 6%;
    --popover-foreground: 35 10% 98%;

    --panel-background: 42 14% 12%;

    --border: 30 6% 16%;
    --input: 25 15% 12%;
    --ring: 45 93% 47% / 0.05;

    --destructive: 0 63% 31%;
    --destructive-foreground: 0 0% 98%;
  }

  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
  }

  h1, h2, h3, h4, h5, h6 {
    @apply font-heading;
  }
}

/* Button shake animation for validation errors */
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  75% { transform: translateX(4px); }
}

.shake-animation {
  animation: shake 0.4s ease-in-out;
}

/* Dance animations */
@keyframes disco-bounce {
  0%, 100% { transform: translateY(0) rotate(0deg) scale(1); }
  25% { transform: translateY(-20px) rotate(180deg) scale(1.2); }
  50% { transform: translateY(0) rotate(360deg) scale(1); }
  75% { transform: translateY(-10px) rotate(540deg) scale(1.1); }
}

@keyframes salsa-spin {
  0% { transform: translateX(0) rotate(0deg); }
  25% { transform: translateX(15px) rotate(90deg); }
  50% { transform: translateX(0) rotate(180deg); }
  75% { transform: translateX(-15px) rotate(270deg); }
  100% { transform: translateX(0) rotate(360deg); }
}

@keyframes breakdance {
  0% { transform: rotate(0deg) scale(1); }
  25% { transform: rotate(180deg) scale(0.8); }
  50% { transform: rotate(360deg) scale(1.2); }
  75% { transform: rotate(540deg) scale(0.9); }
  100% { transform: rotate(720deg) scale(1); }
}

/* Fade-in animation */
@keyframes fade-in {
  0% { opacity: 0; transform: translate(-50%, 10px); }
  100% { opacity: 1; transform: translate(-50%, 0); }
}

/* Progress bar shimmer animation */
@keyframes progress-shimmer {
  0% {
    background-position: -100% 0;
  }
  100% {
    background-position: 100% 0;
  }
}

.progress-shimmer {
  background: linear-gradient(
    90deg,
    hsl(var(--primary)) 0%,
    hsl(var(--primary)) 40%,
    hsl(var(--primary) / 0.75) 50%,
    hsl(var(--primary)) 60%,
    hsl(var(--primary)) 100%
  );
  background-size: 300% 100%;
  animation: progress-shimmer 3s linear infinite;
}

/* Button gold shimmer animation */
@keyframes shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* Button hover fade in then settle */
@keyframes shimmer-fade {
  0% { opacity: 0; }
  50% { opacity: 1; }
  100% { opacity: 0.2; }
}

/* Button text color sync with shimmer */
@keyframes text-fade {
  0% { color: #9ca3af; }
  50% { color: #000000; }
  100% { color: #d1d5db; }
}

/* Text swap animations */
@keyframes text-swap-out {
  0% { opacity: 1; }
  50% { opacity: 0; }
  100% { opacity: 0; }
}

@keyframes arrow-fade-out {
  0% { opacity: 1; }
  35% { opacity: 0; }
  100% { opacity: 0; }
}

@keyframes text-swap-in {
  0% { opacity: 0; }
  35% { opacity: 0; }
  60% { opacity: 1; }
  100% { opacity: 1; }
}

@keyframes progress-fill {
  from { width: 0; }
  to { width: 100%; }
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-20px); }
}

@keyframes floatCard1 {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}

@keyframes floatCard2 {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(15px); }
}

@keyframes floatCard3 {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

@layer utilities {
  .animate-disco-bounce {
    animation: disco-bounce 5s ease-in-out;
  }

  .animate-salsa-spin {
    animation: salsa-spin 5s ease-in-out;
  }

  .animate-breakdance {
    animation: breakdance 5s ease-in-out;
  }

  .animate-fade-in {
    animation: fade-in 0.5s ease-out forwards;
  }
}

/* Dark scrollbar for dark-themed sections */
.scrollbar-dark::-webkit-scrollbar {
  width: 6px;
}

.scrollbar-dark::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.05);
  border-radius: 3px;
}

.scrollbar-dark::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

.scrollbar-dark::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.3);
}

/* Firefox dark scrollbar */
.scrollbar-dark {
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) rgba(255, 255, 255, 0.05);
}

