import { db } from '../../../db';
import { 
  contacts, 
  companies, 
  dailyOutreachBatches, 
  dailyOutreachItems,
  strategicProfiles,
  userOutreachPreferences,
  senderProfiles,
  targetCustomerProfiles,
  Contact,
  Company,
  DailyOutreachBatch,
  DailyOutreachItem
} from '@shared/schema';
import { eq, and, isNull, not, inArray, sql, desc } from 'drizzle-orm';
import { DailyBatch, DailyOutreachItemWithDetails } from '../types';
import { generateEmailContent } from '../../../email-content-generation/service';

export class DailyBatchGenerator {
  async generateDailyBatch(userId: number): Promise<DailyBatch | null> {
    try {
      console.log(`[Batch Generator] Starting batch generation for user ${userId}`);

      // Get uncontacted contacts with emails
      const uncontactedContacts = await this.getUncontactedContacts(userId);
      console.log(`[Batch Generator] Found ${uncontactedContacts.length} uncontacted contacts`);

      if (uncontactedContacts.length < 5) {
        // Try to get more contacts from new companies
        const newContacts = await this.getContactsFromNewCompanies(userId, 5 - uncontactedContacts.length);
        uncontactedContacts.push(...newContacts);
        console.log(`[Batch Generator] After adding new company contacts: ${uncontactedContacts.length} total`);
      }

      if (uncontactedContacts.length < 5) {
        console.log(`[Batch Generator] Not enough contacts for user ${userId}. Found ${uncontactedContacts.length}/5 required`);
        return null;
      }

      // Select top 5 based on confidence score
      const selectedContacts = this.selectTopContacts(uncontactedContacts, 5);
      console.log(`[Batch Generator] Selected ${selectedContacts.length} contacts based on confidence scores`);

      // Get company details for selected contacts
      const companyIds = Array.from(new Set(selectedContacts.map(c => c.companyId)));
      const companiesData = await db
        .select()
        .from(companies)
        .where(inArray(companies.id, companyIds));

      const companyMap = new Map(companiesData.map(c => [c.id, c]));
      console.log(`[Batch Generator] Fetched data for ${companiesData.length} companies`);

      // Generate personalized emails for each contact
      console.log(`[Batch Generator] Starting AI email generation for ${selectedContacts.length} contacts`);
      const batchItems = await Promise.all(
        selectedContacts.map(contact => 
          this.generateEmailForContact(contact, companyMap.get(contact.companyId)!, userId)
        )
      );
      console.log(`[Batch Generator] Generated ${batchItems.length} AI emails`);

      // Create batch record with secure token
      const batch = await this.createBatch(userId, batchItems, selectedContacts, companiesData);
      console.log(`[Batch Generator] Created batch ${batch.id} with ${batch.items.length} items`);

      return batch;
    } catch (error) {
      console.error('[Batch Generator] Error generating daily batch:', error);
      throw error; // Re-throw to propagate to scheduler
    }
  }

  private async getUncontactedContacts(userId: number): Promise<Contact[]> {
    // Get contacts that haven't been included in any outreach items
    const usedContactIds = await db
      .select({ contactId: dailyOutreachItems.contactId })
      .from(dailyOutreachItems)
      .innerJoin(dailyOutreachBatches, eq(dailyOutreachItems.batchId, dailyOutreachBatches.id))
      .where(eq(dailyOutreachBatches.userId, userId));

    const usedIds = usedContactIds.map(r => r.contactId);

    const query = db
      .select()
      .from(contacts)
      .where(
        and(
          eq(contacts.userId, userId),
          not(isNull(contacts.email)),
          usedIds.length > 0 ? not(inArray(contacts.id, usedIds)) : sql`true`
        )
      )
      .orderBy(desc(contacts.nameConfidenceScore))
      .limit(20);

    return await query;
  }

  private async getContactsFromNewCompanies(userId: number, needed: number): Promise<Contact[]> {
    // Get companies that haven't had any contacts used in outreach
    const usedCompanyIds = await db
      .selectDistinct({ companyId: dailyOutreachItems.companyId })
      .from(dailyOutreachItems)
      .innerJoin(dailyOutreachBatches, eq(dailyOutreachItems.batchId, dailyOutreachBatches.id))
      .where(eq(dailyOutreachBatches.userId, userId));

    const usedIds = usedCompanyIds.map(r => r.companyId);

    // Get contacts from unused companies
    const query = db
      .select()
      .from(contacts)
      .where(
        and(
          eq(contacts.userId, userId),
          not(isNull(contacts.email)),
          usedIds.length > 0 ? not(inArray(contacts.companyId, usedIds)) : sql`true`
        )
      )
      .orderBy(desc(contacts.nameConfidenceScore))
      .limit(needed * 2); // Get extra in case we need them

    return await query;
  }

  private selectTopContacts(contacts: Contact[], count: number): Contact[] {
    // Sort by confidence score and take top N
    return contacts
      .sort((a, b) => {
        // Prioritize by confidence score, then by having a role
        const scoreA = (a.nameConfidenceScore || 0) + (a.role ? 10 : 0);
        const scoreB = (b.nameConfidenceScore || 0) + (b.role ? 10 : 0);
        return scoreB - scoreA;
      })
      .slice(0, count);
  }

  private async generateEmailForContact(
    contact: Contact, 
    company: Company, 
    userId: number
  ): Promise<Omit<DailyOutreachItem, 'id' | 'batchId' | 'createdAt'>> {
    try {
      // Get user's preferences including profile selections
      const [preferences] = await db
        .select()
        .from(userOutreachPreferences)
        .where(eq(userOutreachPreferences.userId, userId));

      let strategy;
      if (preferences?.activeProductId) {
        // Get the specific active product
        const [activeProduct] = await db
          .select()
          .from(strategicProfiles)
          .where(eq(strategicProfiles.id, preferences.activeProductId));
        strategy = activeProduct;
      } else {
        // Fallback to most recent strategy
        const [latestStrategy] = await db
          .select()
          .from(strategicProfiles)
          .where(eq(strategicProfiles.userId, userId))
          .orderBy(desc(strategicProfiles.createdAt))
          .limit(1);
        strategy = latestStrategy;
      }

      // Get selected sender profile for personalization
      let senderProfile;
      if (preferences?.activeSenderProfileId) {
        const [activeSender] = await db
          .select()
          .from(senderProfiles)
          .where(eq(senderProfiles.id, preferences.activeSenderProfileId));
        senderProfile = activeSender;
      }

      // Get selected customer profile for targeting
      let customerProfile;
      if (preferences?.activeCustomerProfileId) {
        const [activeCustomer] = await db
          .select()
          .from(targetCustomerProfiles)
          .where(eq(targetCustomerProfiles.id, preferences.activeCustomerProfileId));
        customerProfile = activeCustomer;
      }

      // Build enhanced email prompt with profile context
      let emailPrompt = strategy?.productService 
        ? `Introduce ${strategy.productService} to this company and how it can help their business`
        : 'Introduce our services and explore potential collaboration';

      if (customerProfile) {
        emailPrompt += `. Target customer profile: ${customerProfile.label}`;
        if (customerProfile.targetDescription) {
          emailPrompt += `. Target description: ${customerProfile.targetDescription}`;
        }
      }

      if (senderProfile) {
        emailPrompt += `. Email from ${senderProfile.displayName} at ${senderProfile.companyName || 'our company'}`;
        if (senderProfile.title) {
          emailPrompt += ` (${senderProfile.title})`;
        }
      }

      // Generate email content using existing system with enhanced context
      const emailContent = await generateEmailContent({
        emailPrompt,
        contact: contact,
        company: company,
        userId: userId,
        tone: strategy?.primaryBusinessGoal?.includes('professional') ? 'professional' : 'friendly',
        offerStrategy: 'value_proposition'
      });

      return {
        contactId: contact.id,
        companyId: company.id,
        communicationId: null,  // Will be set when email is sent
        emailSubject: emailContent.subject,
        emailBody: emailContent.content,
        emailTone: 'professional',
        status: 'pending',
        sentAt: null,
        editedContent: null
      };
    } catch (error) {
      console.error(`[Batch Generator] Error generating email for contact ${contact.id}:`, error);
      // Fallback to simple template
      return {
        contactId: contact.id,
        companyId: company.id,
        communicationId: null,  // Will be set when email is sent
        emailSubject: `Quick question for ${company.name}`,
        emailBody: `Hi ${contact.name},\n\nI noticed ${company.name} and wanted to reach out about how we might be able to help with your business needs.\n\nWould you be open to a brief conversation?\n\nBest regards`,
        emailTone: 'professional',
        status: 'pending',
        sentAt: null,
        editedContent: null
      };
    }
  }

  private async createBatch(
    userId: number, 
    items: Omit<DailyOutreachItem, 'id' | 'batchId' | 'createdAt'>[],
    selectedContacts: Contact[],
    companiesData: Company[]
  ): Promise<DailyBatch> {
    const now = new Date();
    const expiresAt = new Date(now.getTime() + 24 * 60 * 60 * 1000); // 24 hours from now

    // Create batch record
    const [batch] = await db
      .insert(dailyOutreachBatches)
      .values({
        userId,
        batchDate: now,
        status: 'pending',
        expiresAt
      })
      .returning();

    // Create batch items
    const itemsToInsert = items.map(item => ({
      ...item,
      batchId: batch.id
    }));

    const insertedItems = await db
      .insert(dailyOutreachItems)
      .values(itemsToInsert)
      .returning();

    // Build complete batch object with details
    const itemsWithDetails: DailyOutreachItemWithDetails[] = insertedItems.map((item, index) => ({
      ...item,
      contact: selectedContacts[index],
      company: companiesData.find(c => c.id === item.companyId)!
    }));

    return {
      ...batch,
      items: itemsWithDetails,
      hasContacts: true
    };
  }
}

export const batchGenerator = new DailyBatchGenerator();

client/src/components/chat-overlay.tsx.content:
import React, { useState, useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { X, MessageCircle, Send, Minimize2, Maximize2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { apiRequest } from '@/lib/queryClient';

interface Message {
  id: string;
  content: string;
  sender: 'user' | 'ai';
  timestamp: Date;
}

type ChatState = 'hidden' | 'minimized' | 'sidebar' | 'fullscreen';
type BusinessType = 'product' | 'service' | null;

interface ChatOverlayProps {
  initialState?: ChatState;
  onStateChange?: (state: ChatState) => void;
}

interface ChatOverlayRef {
  initializeChat: (type: BusinessType) => void;
}

const ChatOverlay = forwardRef<ChatOverlayRef, ChatOverlayProps>(({ initialState = 'hidden', onStateChange }, ref) => {
  const [chatState, setChatState] = useState<ChatState>(initialState);
  const [businessType, setBusinessType] = useState<BusinessType>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [currentStep, setCurrentStep] = useState('business_description');
  const [profileData, setProfileData] = useState<any>({});
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const isMobile = typeof window !== 'undefined' && window.innerWidth < 768;

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    onStateChange?.(chatState);
  }, [chatState, onStateChange]);

  const initializeChat = (type: BusinessType) => {
    setBusinessType(type);
    const welcomeMessage: Message = {
      id: Date.now().toString(),
      content: `Hi! I love that you're selling a ${type}! Let's create your strategic sales plan together.

To get started, please tell me about your ${type}. What exactly are you offering, and what makes it special?`,
      sender: 'ai',
      timestamp: new Date()
    };
    setMessages([welcomeMessage]);
    setChatState(isMobile ? 'fullscreen' : 'fullscreen');
  };

  useImperativeHandle(ref, () => ({
    initializeChat
  }));

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      content: inputMessage,
      sender: 'user',
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputMessage('');
    setIsLoading(true);

    try {
      const response: any = await apiRequest('POST', '/api/onboarding/chat', {
        message: inputMessage,
        businessType,
        currentStep,
        profileData,
        conversationHistory: messages
      });

      if (response.aiResponse) {
        const aiMessage: Message = {
          id: (Date.now() + 1).toString(),
          content: response.aiResponse,
          sender: 'ai',
          timestamp: new Date()
        };
        setMessages(prev => [...prev, aiMessage]);
      }

      if (response.profileUpdate) {
        setProfileData((prev: any) => ({ ...prev, ...response.profileUpdate }));
      }

      if (response.nextStep) {
        setCurrentStep(response.nextStep);
      }

    } catch (error) {
      console.error('Error sending message:', error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        content: "I apologize, but I'm having trouble processing your message right now. Please try again.",
        sender: 'ai',
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleStateChange = (newState: ChatState) => {
    setChatState(newState);
  };

  const handleClose = () => {
    if (chatState === 'fullscreen') {
      setChatState(isMobile ? 'minimized' : 'sidebar');
    } else if (chatState === 'sidebar') {
      setChatState('minimized');
    } else {
      setChatState('hidden');
    }
  };

  const handleMaximize = () => {
    setChatState('fullscreen');
  };

  const handleReopen = () => {
    setChatState(isMobile ? 'fullscreen' : 'sidebar');
  };

  // Hidden state
  if (chatState === 'hidden') {
    return null;
  }

  // Minimized state - just an icon
  if (chatState === 'minimized') {
    return (
      <div className="fixed bottom-6 right-6 z-50">
        <Button
          onClick={handleReopen}
          className="w-14 h-14 rounded-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white shadow-lg hover:shadow-xl transition-all duration-300"
        >
          <MessageCircle className="w-6 h-6" />
        </Button>
      </div>
    );
  }

  // Chat content component
  const ChatContent = () => (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900">
        <div className="flex items-center space-x-3">
          <div className="w-8 h-8 rounded-full bg-gradient-to-r from-blue-600 to-purple-600 flex items-center justify-center">
            <MessageCircle className="w-4 h-4 text-white" />
          </div>
          <div>
            <h3 className="font-semibold text-slate-900 dark:text-white">Strategic Planning Assistant</h3>
            <p className="text-sm text-slate-500 dark:text-slate-400">
              {businessType ? `Creating your ${businessType} strategy` : 'Ready to help'}
            </p>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          {chatState === 'fullscreen' && !isMobile && (
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setChatState('sidebar')}
              className="text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
            >
              <Minimize2 className="w-4 h-4" />
            </Button>
          )}
          {chatState === 'sidebar' && (
            <Button
              variant="ghost"
              size="icon"
              onClick={handleMaximize}
              className="text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
            >
              <Maximize2 className="w-4 h-4" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="icon"
            onClick={handleClose}
            className="text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
          >
            <X className="w-4 h-4" />
          </Button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 dark:bg-slate-950">
        {messages.map((message) => (
          <div
            key={message.id}
            className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[80%] px-4 py-2 rounded-lg ${
                message.sender === 'user'
                  ? 'bg-blue-600 text-white'
                  : 'bg-white dark:bg-slate-800 text-slate-900 dark:text-white border border-slate-200 dark:border-slate-700'
              }`}
            >
              <p className="text-sm whitespace-pre-wrap">{message.content}</p>
              <span className="text-xs opacity-70 mt-1 block">
                {message.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 px-4 py-2 rounded-lg">
              <div className="flex space-x-1">
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="p-4 border-t border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900">
        <div className="flex space-x-2">
          <Input
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            placeholder="Type your message..."
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                handleSendMessage();
              }
            }}
            disabled={isLoading}
            className="flex-1"
          />
          <Button
            onClick={handleSendMessage}
            disabled={!inputMessage.trim() || isLoading}
            className="bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700"
          >
            <Send className="w-4 h-4" />
          </Button>
        </div>
      </div>
    </div>
  );

  // Fullscreen state
  if (chatState === 'fullscreen') {
    return (
      <div className="fixed inset-0 z-50 bg-white dark:bg-slate-900">
        <ChatContent />
      </div>
    );
  }

  // Sidebar state (desktop only)
  if (chatState === 'sidebar') {
    return (
      <div className="fixed top-0 right-0 w-96 h-full z-50 bg-white dark:bg-slate-900 border-l border-slate-200 dark:border-slate-700 shadow-xl">
        <ChatContent />
      </div>
    );
  }

  return null;
});

export default ChatOverlay;

// Global function to initialize chat from HTML
export const initializeChatOverlay = (type: 'product' | 'service') => {
  const event = new CustomEvent('initializeChat', { detail: { type } });
  window.dispatchEvent(event);
};

