              placeholder="${currentQuestion.placeholder}"
              id="form-input"
            >${this.escapeHtml(currentValue || '')}</textarea>
          ` : `
            <input 
              type="text" 
              class="form-input" 
              placeholder="${currentQuestion.placeholder}"
              id="form-input"
              value="${this.escapeHtml(currentValue || '')}"
            />
