import axios from 'axios';
import { queryClient } from '@/lib/queryClient';

export interface LoginCredentials {
  email: string;
  password: string;
}

export interface RegisterCredentials extends LoginCredentials {
  name?: string;
}

export interface AuthResponse {
  id: number;
  email: string;
  name?: string;
}

/**
 * Local authentication service for handling non-Firebase authentication
 */
export const localAuth = {
  /**
   * Register a new user with the local authentication system
   */
  async register(credentials: RegisterCredentials): Promise<AuthResponse> {
    try {
      const response = await axios.post('/api/register', credentials);

      // Update auth state in React Query to trigger UI updates
      queryClient.setQueryData(["/api/user"], response.data);

      return response.data;
    } catch (error: any) {
      console.error('Registration error:', error);
      throw new Error(error.response?.data?.error || 'Registration failed');
    }
  },

  /**
   * Login with local authentication
   */
  async login(credentials: LoginCredentials): Promise<AuthResponse> {
    try {
      const response = await axios.post('/api/login', credentials);

      // Update auth state in React Query to trigger UI updates
      queryClient.setQueryData(["/api/user"], response.data);

      return response.data;
    } catch (error: any) {
      console.error('Login error:', error);
      throw new Error(error.response?.data?.error || 'Invalid credentials');
    }
  },

  /**
   * Logout from the local authentication system
   */
  async logout(): Promise<void> {
    try {
      await axios.post('/api/logout');

      // Clear auth state in React Query
      queryClient.setQueryData(["/api/user"], null);

    } catch (error) {
      console.error('Logout error:', error);
      throw error;
    }
  },

  /**
   * Check if the user is already authenticated
   */
  async checkAuth(): Promise<AuthResponse | null> {
    try {
      const response = await axios.get('/api/user');

      // If successful, update the auth state
      if (response.data) {
        queryClient.setQueryData(["/api/user"], response.data);
      }

      return response.data;
    } catch (error) {
      return null;
    }
  }
};

client/src/pages/testing.tsx.content:
import { useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { CheckCircle, XCircle, Clock, Play, RefreshCw, AlertTriangle } from "lucide-react";
import { useAuth } from "@/hooks/use-auth";

interface TestResult {
  name: string;
  status: 'pending' | 'running' | 'passed' | 'failed' | 'warning';
  message: string;
  duration?: number;
  error?: string;
  category?: string;
  data?: any;
}

interface TestSummary {
  total: number;
  passed: number;
  failed: number;
  warnings: number;
}

export default function Testing() {
  const { user } = useAuth();
  const [testResults, setTestResults] = useState<TestResult[]>([]);
  const [testSummary, setTestSummary] = useState<TestSummary>({ total: 0, passed: 0, failed: 0, warnings: 0 });
  const [isRunning, setIsRunning] = useState(false);

  // Group tests by category for display
  const groupedTests = testResults.reduce((acc, test) => {
    const category = test.category || 'Uncategorized';
    if (!acc[category]) {
      acc[category] = [];
    }
    acc[category].push(test);
    return acc;
  }, {} as Record<string, TestResult[]>);

  const runAllTests = async () => {
    setIsRunning(true);

    try {
      const response = await fetch('/api/test/run-all', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const testReport = await response.json();

      // Set individual test results and summary
      setTestResults(testReport.tests || []);
      setTestSummary(testReport.summary || { total: 0, passed: 0, failed: 0, warnings: 0 });
    } catch (error) {
      console.error('Error running tests:', error);
      setTestResults([]);
      setTestSummary({ total: 0, passed: 0, failed: 0, warnings: 0 });
    } finally {
      setIsRunning(false);
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'passed':
        return <CheckCircle className="h-4 w-4 text-green-600" />;
      case 'failed':
        return <XCircle className="h-4 w-4 text-red-600" />;
      case 'warning':
        return <AlertTriangle className="h-4 w-4 text-yellow-600" />;
      case 'running':
        return <RefreshCw className="h-4 w-4 text-blue-600 animate-spin" />;
      default:
        return <Clock className="h-4 w-4 text-gray-400" />;
    }
  };

  const getStatusBadge = (status: string) => {
    const variants = {
      passed: "default",
      failed: "destructive", 
      warning: "secondary",
      running: "outline",
      pending: "outline"
    } as const;

    return (
      <Badge variant={variants[status as keyof typeof variants] || "outline"}>
        {status}
      </Badge>
    );
  };

  return (
    <div className="container mx-auto py-8 px-4">
      <div className="max-w-4xl mx-auto space-y-6">
        <div className="text-center space-y-4">
          <h1 className="text-3xl font-bold tracking-tight">System Testing Dashboard</h1>
          <p className="text-muted-foreground">
            Comprehensive testing of all platform components and integrations
          </p>
        </div>

        {/* Summary Card */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center justify-between">
              <span>Test Results Summary</span>
              <Button 
                onClick={runAllTests} 
                disabled={isRunning}
                size="sm"
              >
                {isRunning ? (
                  <>
                    <RefreshCw className="mr-2 h-4 w-4 animate-spin" />
                    Running Tests...
                  </>
                ) : (
                  <>
                    <Play className="mr-2 h-4 w-4" />
                    Run All Tests
                  </>
                )}
              </Button>
            </CardTitle>
            <CardDescription>
              Total: {testSummary.total} tests
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex gap-4 text-sm">
              <div className="flex items-center gap-2">
                <CheckCircle className="h-4 w-4 text-green-600" />
                <span>{testSummary.passed} Passed</span>
              </div>
              <div className="flex items-center gap-2">
                <XCircle className="h-4 w-4 text-red-600" />
                <span>{testSummary.failed} Failed</span>
              </div>
              <div className="flex items-center gap-2">
                <AlertTriangle className="h-4 w-4 text-yellow-600" />
                <span>{testSummary.warnings} Warnings</span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Test Categories */}
        <div className="space-y-4">
          {Object.entries(groupedTests).map(([category, tests]) => (
            <Card key={category}>
              <CardHeader>
                <CardTitle className="text-lg">{category}</CardTitle>
                <CardDescription>
                  {tests.length} individual tests in this category
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {tests.map((test, index) => (
                    <div key={`${category}-${index}`} className="flex items-center justify-between p-3 border rounded-lg">
                      <div className="flex items-center gap-3">
                        {getStatusIcon(test.status)}
                        <div>
                          <div className="font-medium">{test.name}</div>
                          <div className="text-sm text-muted-foreground">{test.message}</div>
                          {test.error && (
                            <div className="text-sm text-red-600 mt-1">Error: {test.error}</div>
                          )}
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        {getStatusBadge(test.status)}
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>

        {testResults.length === 0 && !isRunning && (
          <Card>
            <CardContent className="py-8 text-center">
              <Clock className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
              <h3 className="text-lg font-semibold mb-2">No tests run yet</h3>
              <p className="text-muted-foreground mb-4">
                Click "Run All Tests" to start the comprehensive system test suite
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

server/features/billing/stripe/service.t.content:
import Stripe from "stripe";
import { CreditService } from "../credits/service";
import { StripeCustomerData, CheckoutSessionData, SubscriptionStatus, STRIPE_CONFIG } from "./types";

// Lazy initialization to prevent crashes during module loading in production
let stripe: Stripe | null = null;

export class StripeService {
  /**
   * Get or initialize Stripe instance
   */
  static getStripe(): Stripe {
    if (!stripe) {
      const stripeSecretKey = process.env.STRIPE_SECRET_KEY;

      if (!stripeSecretKey) {
        throw new Error(`Missing required Stripe secret key. Please add STRIPE_SECRET_KEY to your deployment secrets.`);
      }

      stripe = new Stripe(stripeSecretKey, {
        apiVersion: "2025-05-28.basil",
      });
    }

    return stripe;
  }

  /**
   * Check if Stripe is configured
   */
  static isConfigured(): boolean {
    return !!process.env.STRIPE_SECRET_KEY;
  }

  /**
   * Get or create Stripe customer
   */
  static async getOrCreateCustomer(userId: number, userEmail: string): Promise<StripeCustomerData> {
    const credits = await CreditService.getUserCredits(userId);

    if (credits.stripeCustomerId) {
      const customer = await this.getStripe().customers.retrieve(credits.stripeCustomerId);
      if ('deleted' in customer && customer.deleted) {
        // Customer was deleted, create a new one
      } else {
        return {
          customerId: customer.id,
          email: (customer as any).email || userEmail,
          userId
        };
      }
    }

    // Create new customer
    const customer = await this.getStripe().customers.create({
      email: userEmail,
      metadata: {
        userId: userId.toString()
      }
    });

    // Update user credits with customer ID
    await CreditService.updateStripeCustomerId(userId, customer.id);

    return {
      customerId: customer.id,
      email: customer.email || userEmail,
      userId
    };
  }

  /**
   * Create checkout session for subscription
   */
  static async createCheckoutSession(
    userId: number,
    userEmail: string,
    planId: string,
    origin: string
  ): Promise<CheckoutSessionData> {
    if (planId !== 'ugly-duckling') {
      throw new Error("Invalid plan ID");
    }

    // Get or create customer
    const customer = await this.getOrCreateCustomer(userId, userEmail);

    // Use the same price ID for both test and production
    const priceId = STRIPE_CONFIG.UGLY_DUCKLING_PRICE_ID;

    const successUrl = `${origin}/subscription-success?session_id={CHECKOUT_SESSION_ID}`;
    const cancelUrl = origin;

    // Create checkout session
    const session = await this.getStripe().checkout.sessions.create({
      customer: customer.customerId,
      payment_method_types: ['card'],
      line_items: [
        {
          price: priceId,
          quantity: 1,
        },
      ],
      mode: 'subscription',
      success_url: successUrl,
      cancel_url: cancelUrl,
      metadata: {
        userId: userId.toString(),
        planId: planId
      },
      subscription_data: {
        metadata: {
          userId: userId.toString(),
          planId: planId
        }
      }
    });

    console.log(`Created checkout session for user ${userId}, plan ${planId}: ${session.id}`);

    return {
      checkoutUrl: session.url,
      sessionId: session.id
    };
  }

  /**
   * Get subscription status for a user
   */
  static async getSubscriptionStatus(userId: number): Promise<SubscriptionStatus> {
    const credits = await CreditService.getUserCredits(userId);

    if (!credits.stripeSubscriptionId) {
      return {
        hasSubscription: false,
        status: null,
        currentPlan: null
      };
    }

    try {
      const subscription = await this.getStripe().subscriptions.retrieve(credits.stripeSubscriptionId);

      return {
        hasSubscription: true,
        status: subscription.status,
        currentPlan: credits.currentPlan || null,
        subscriptionId: subscription.id,
        currentPeriodEnd: (subscription as any).current_period_end * 1000, // Convert to milliseconds
        cancelAtPeriodEnd: (subscription as any).cancel_at_period_end
      };
    } catch (error) {
      console.error('Error retrieving subscription:', error);
      return {
        hasSubscription: false,
        status: null,
        currentPlan: null
      };
    }
  }

  /**
   * Process subscription created or updated webhook
   */
  static async processSubscriptionUpdate(subscription: any): Promise<void> {
    const userId = parseInt(subscription.metadata.userId);
    const planId = subscription.metadata.planId;

    if (!userId || !planId) {
      console.warn('Subscription webhook missing metadata:', subscription.id);
      return;
    }

    console.log(`Processing subscription update for user ${userId}, plan ${planId}`);

    await CreditService.updateSubscription(userId, {
      stripeSubscriptionId: subscription.id,
      subscriptionStatus: subscription.status,
      currentPlan: planId,
      subscriptionStartDate: subscription.created * 1000,
      subscriptionEndDate: subscription.current_period_end * 1000
    });

    // Award subscription credits if active
    if (subscription.status === 'active' && planId === 'ugly-duckling') {
      await CreditService.awardSubscriptionCredits(userId, planId as 'ugly-duckling');
      console.log(`Awarded subscription credits to user ${userId} for plan ${planId}`);
    }
  }

  /**
   * Process subscription cancellation webhook
   */
  static async processSubscriptionCancellation(subscription: any): Promise<void> {
    const userId = parseInt(subscription.metadata.userId);

    if (!userId) {
      console.warn('Subscription cancellation webhook missing userId:', subscription.id);
      return;
    }

    console.log(`Processing subscription cancellation for user ${userId}`);

    await CreditService.updateSubscription(userId, {
      subscriptionStatus: 'canceled',
      currentPlan: undefined,
      subscriptionEndDate: Date.now()
    });
  }

  /**
   * Process payment failure webhook
   */
  static async processPaymentFailure(invoice: any): Promise<void> {
    if (!invoice.subscription) {
      return;
    }

    try {
      const subscription = await this.getStripe().subscriptions.retrieve(invoice.subscription);
      const userId = parseInt(subscription.metadata.userId);

      if (userId) {
        console.log(`Payment failed for user ${userId}`);

        await CreditService.updateSubscription(userId, {
          subscriptionStatus: 'past_due'
        });
      }
    } catch (error) {
      console.error('Error processing payment failure:', error);
    }
  }

  /**
   * Construct and verify webhook event
   */
  static constructWebhookEvent(
    payload: string | Buffer,
    signature: string | undefined,
    webhookSecret: string | undefined
  ): any {
    if (webhookSecret && signature && webhookSecret.length > 50) {
      // Production: Verify webhook signature (only if secret looks valid)
      const event = this.getStripe().webhooks.constructEvent(payload, signature, webhookSecret);
      console.log(`✅ Verified Stripe webhook: ${event.type}`);
      return event;
    } else {
      // Development or invalid secret: Parse without verification but warn
      const body = Buffer.isBuffer(payload) ? payload.toString() : JSON.stringify(payload);
      const event = JSON.parse(body);

      if (webhookSecret && webhookSecret.length <= 50) {
        console.log(`⚠️ Webhook secret appears truncated (${webhookSecret.length} chars) - processing unverified`);
      } else {
        console.log(`⚠️ Unverified Stripe webhook: ${event.type} - Add webhook secret for production`);
      }

      return event;
    }
  }

  /**
   * Get customer debug information
   */
  static async getCustomerDebugInfo(customerId: string): Promise<any> {
    const customer = await this.getStripe().customers.retrieve(customerId);

    const subscriptions = await this.getStripe().subscriptions.list({
      customer: customerId,
      limit: 10
    });

    return {
      customer: {
        id: customer.id,
        email: (customer as any).email || null,
        created: (customer as any).created || null
      },
      subscriptions: subscriptions.data.map(sub => ({
        id: sub.id,
        status: sub.status,
        created: sub.created,
        current_period_end: (sub as any).current_period_end,
        metadata: sub.metadata
      }))
    };
  }
}

