        .header { color: #333; margin-bottom: 20px; }
        .button { 
          display: inline-block; 
          background: #0066FF; 
          color: white !important; 
          padding: 14px 28px; 
          text-decoration: none; 
          border-radius: 6px; 
          margin: 24px 0;
          font-weight: 500;
