import { Router, Request, Response, Application } from 'express';
import { storage } from '../storage';
import { GmailOAuthService } from './oauth/service';
import { TokenService } from '../features/billing/tokens/service';
import type { 
  GmailAuthRequest, 
  GmailCallbackQuery, 
  SendGmailRequest,
  GmailStatusResponse,
  GmailDisconnectResponse,
  SendGmailResponse 
} from './oauth/types';

export function registerGmailRoutes(app: Application, requireAuth: any) {
  const router = Router();

  // OAuth flow routes
  router.get('/auth', async (req: Request, res: Response) => {
    try {
      const userId = req.query.userId as string;

      if (!userId || !userId.match(/^\d+$/)) {
        return res.status(400).json({ error: 'Invalid user ID parameter' });
      }

      const user = await storage.getUserById(parseInt(userId));
      if (!user) {
        return res.status(400).json({ error: 'User not found' });
      }

      // Force HTTPS for OAuth callbacks - Replit always serves via HTTPS externally
      // even though internally the app sees HTTP
      const protocol = process.env.OAUTH_PROTOCOL || 
        (process.env.NODE_ENV === 'production' ? 'https' : 
          req.get('host')?.includes('replit.dev') ? 'https' : req.protocol);

      // Debug logging
      console.log('[Gmail OAuth] Generating auth URL with:', {
        host: req.get('host'),
        protocol,
        userId,
        NODE_ENV: process.env.NODE_ENV,
        OAUTH_PROTOCOL: process.env.OAUTH_PROTOCOL,
        reqProtocol: req.protocol,
        includesReplitDev: req.get('host')?.includes('replit.dev'),
        constructedRedirectUri: `${protocol}://${req.get('host')}/api/gmail/callback`
      });

      const authUrl = GmailOAuthService.generateAuthUrl(
        userId, 
        req.get('host')!, 
        protocol
      );

      console.log('[Gmail OAuth] Generated auth URL:', authUrl);

      res.redirect(authUrl);
    } catch (error) {
      console.error('Gmail OAuth error:', error);
      res.status(500).json({ error: 'Failed to start Gmail authorization' });
    }
  });

  router.get('/callback', async (req: Request, res: Response) => {
    try {
      const { code, state } = req.query as unknown as GmailCallbackQuery;

      if (!code) {
        return res.status(400).json({ error: 'Authorization code missing' });
      }

      const userId = parseInt(state, 10);

      if (isNaN(userId)) {
        return res.status(400).json({ error: 'Invalid state parameter' });
      }

      // Force HTTPS for OAuth callbacks - Replit always serves via HTTPS externally
      // even though internally the app sees HTTP
      const protocol = process.env.OAUTH_PROTOCOL || 
        (process.env.NODE_ENV === 'production' ? 'https' : 
          req.get('host')?.includes('replit.dev') ? 'https' : req.protocol);

      const { tokens } = await GmailOAuthService.exchangeCodeForTokens(
        code, 
        req.get('host')!, 
        protocol
      );

      const userInfo = await GmailOAuthService.fetchUserInfo(tokens.access_token);

      console.log(`[Gmail OAuth] Fetched userinfo for user ${userId}:`, {
        email: userInfo.email,
        name: userInfo.name,
        email_verified: userInfo.email_verified
      });

      await GmailOAuthService.storeTokens(userId, tokens, userInfo);

      // Create or update sender profile for this Gmail account
      try {
        const { storage } = await import('../storage');

        // Get existing profiles for this user
        const existingProfiles = await storage.listSenderProfiles(userId);

        // Check if a profile already exists with this Gmail email
        const existingGmailProfile = existingProfiles.find(p => p.email === userInfo.email);

        if (!existingGmailProfile) {
          // Parse the name from Gmail userInfo
          const nameParts = userInfo.name?.split(' ') || [];
          const firstName = nameParts[0] || '';
          const lastName = nameParts.slice(1).join(' ') || '';

          // Compose the display name using smart logic
          let displayName: string;
          if (lastName) {
            // Has last name: use full name
            displayName = userInfo.name || userInfo.email.split('@')[0];
          } else {
            // No last name: for now just use first name (company can be added later)
            displayName = firstName || userInfo.email.split('@')[0];
          }

          // Create new sender profile with Gmail info
          const newProfile = await storage.createSenderProfile({
            userId,
            displayName,
            email: userInfo.email,
            firstName, // Store first name separately
            lastName, // Store last name separately
            isDefault: existingProfiles.length === 0, // Make default if it's the first profile
            companyName: undefined, // Can be updated later, which would update displayName
            companyWebsite: undefined,
            title: undefined, // For honorifics
            companyPosition: undefined // For job role
          });

          console.log(`[Gmail OAuth] Created sender profile for Gmail account:`, {
            userId,
            email: userInfo.email,
            displayName,
            isDefault: existingProfiles.length === 0
          });
        } else {
          // Optionally update the existing profile with latest name from Gmail
          if (userInfo.name && existingGmailProfile.displayName !== userInfo.name) {
            await storage.updateSenderProfile(existingGmailProfile.id, {
              displayName: userInfo.name
            });
            console.log(`[Gmail OAuth] Updated sender profile display name for ${userInfo.email}`);
          }
        }
      } catch (error) {
        // Log but don't fail the OAuth flow if profile creation fails
        console.error('[Gmail OAuth] Failed to create/update sender profile:', error);
      }

      res.send(`
        <html>
          <body>
            <script>
              if (window.opener) {
                window.opener.postMessage({ type: 'GMAIL_AUTH_SUCCESS' }, '*');
                window.close();
              } else {
                window.location.href = '/outreach';
              }
            </script>
            <p>Authentication successful. This window should close automatically.</p>
          </body>
        </html>
      `);
    } catch (error) {
      console.error('Error handling Gmail callback:', error);
      res.status(500).json({ error: 'Failed to complete Gmail authorization' });
    }
  });

  // Status and management routes
  router.get('/status', requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user.id;

      const hasValidAuth = await GmailOAuthService.checkAuthStatus(userId);

      const response: GmailStatusResponse = {
        connected: hasValidAuth,
        authUrl: hasValidAuth ? null : `/api/gmail/auth?userId=${userId}`
      };

      res.json(response);
    } catch (error) {
      console.error('Error checking Gmail status:', error);
      res.status(500).json({ error: 'Failed to check Gmail connection status' });
    }
  });

  // Duplicate of /status - merge functionality
  router.get('/auth-status', requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user.id;
      const hasValidAuth = await TokenService.hasValidGmailAuth(userId);

      console.log('Checking Gmail auth status:', {
        userId,
        hasValidAuth,
        timestamp: new Date().toISOString()
      });

      res.json({ 
        authorized: hasValidAuth,
        hasValidToken: hasValidAuth,
        connected: hasValidAuth
      });
    } catch (error) {
      console.error('Error checking Gmail auth status:', error);
      res.json({ 
        authorized: false,
        hasValidToken: false,
        connected: false
      });
    }
  });

  router.get('/disconnect', requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user.id;

      await GmailOAuthService.disconnectGmail(userId);
      delete (req.session as any).gmailRefreshToken;

      req.session.save(err => {
        if (err) {
          console.error('Error saving session:', err);
          return res.status(500).json({ error: 'Failed to disconnect Gmail' });
        }

        const response: GmailDisconnectResponse = {
          success: true,
          message: 'Gmail disconnected successfully'
        };

        res.json(response);
      });
    } catch (error) {
      console.error('Error disconnecting Gmail:', error);
      res.status(500).json({ error: 'Failed to disconnect Gmail' });
    }
  });

  // Get Gmail user info
  router.get('/user', requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user.id;
      const userInfo = await TokenService.getGmailUserInfo(userId);

      console.log('Retrieved Gmail user info:', {
        userId,
        hasEmail: !!userInfo?.email,
        hasName: !!userInfo?.name,
        timestamp: new Date().toISOString()
      });

      res.json(userInfo);
    } catch (error) {
      console.error('Error retrieving Gmail user info:', error);
      res.status(500).json({ error: "Failed to retrieve Gmail user info" });
    }
  });

  app.use('/api/gmail', router);

  // Send email endpoint (outside of /api/gmail prefix for backward compatibility)
  app.post('/api/send-gmail', requireAuth, async (req: Request, res: Response) => {
    try {
      const { to, subject, content, contactId, companyId, tone, offerStrategy } = req.body as SendGmailRequest & {
        contactId?: number;
        companyId?: number;
        tone?: string;
        offerStrategy?: string;
      };

      if (!to || !subject || !content) {
        res.status(400).json({ message: "Missing required email fields" });
        return;
      }

      const userId = (req as any).user.id;
      const userEmail = (req as any).user.email;

      try {
        // Send email via Gmail API and get threadId/messageId
        const gmailResult = await GmailOAuthService.sendEmail(userId, userEmail, to, subject, content);

        // If contactId and companyId are provided, save to CRM communications history
        if (contactId && companyId) {
          const { db } = await import('../db');
          const { communicationHistory, contacts } = await import('@shared/schema');
          const { eq, sql } = await import('drizzle-orm');

          // Save to communication history
          await db.insert(communicationHistory).values({
            userId,
            contactId,
            companyId,
            channel: 'email',
            direction: 'outbound',
            subject,
            content,
            contentPreview: content.substring(0, 200),
            status: 'sent',
            sentAt: new Date(),
            threadId: gmailResult.threadId,
            metadata: {
              from: userEmail,
              to,
              messageId: gmailResult.messageId,
              gmailThreadId: gmailResult.threadId,
              tone: tone || 'professional',
              offerStrategy: offerStrategy || 'standard',
              sourceTable: 'manual_outreach'
            }
          });

          // Update contact status
          await db.update(contacts)
            .set({
              contactStatus: 'contacted',
              lastContactedAt: new Date(),
              lastContactChannel: 'email',
              lastThreadId: gmailResult.threadId,
              totalCommunications: sql`COALESCE(${contacts.totalCommunications}, 0) + 1`
            })
            .where(eq(contacts.id, contactId));

          console.log(`Email saved to CRM for contact ${contactId}, thread: ${gmailResult.threadId}`);
        }

        const response: SendGmailResponse = { 
          success: true,
          threadId: gmailResult.threadId,
          messageId: gmailResult.messageId
        };
        res.json(response);
      } catch (error: any) {
        if (error.status === 401) {
          console.log(`No valid Gmail token found for user ${userId}`);
          res.status(401).json(error);
          return;
        }
        throw error;
      }
    } catch (error) {
      console.error('Gmail send error:', error);
      res.status(500).json({
        message: error instanceof Error ? error.message : "Failed to send email"
      });
    }
  });
}

client/src/pages/admin/ApiTesting.tsx.content:
import { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  CheckCircle, 
  XCircle, 
  AlertTriangle,
  RefreshCw,
  ArrowLeft,
  Play,
  Clock,
  Database,
  Search,
  Shield,
  Globe
} from 'lucide-react';
import { useAuth } from '@/hooks/use-auth';
import { useLocation } from 'wouter';
import { useToast } from '@/hooks/use-toast';
import { apiRequest } from '@/lib/queryClient';

interface TestResult {
  name: string;
  status: 'pending' | 'running' | 'passed' | 'failed' | 'warning';
  message: string;
  duration?: number;
  error?: string;
  subTests?: any[];
}

interface TestReport {
  message: string;
  status: string;
  timestamp: string;
  duration: number;
  overallStatus: string;
  summary: {
    passed: number;
    total: number;
    failed: number;
    warnings: number;
  };
  tests: TestResult[];
}

export default function AdminApiTesting() {
  const { user } = useAuth();
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [testReport, setTestReport] = useState<TestReport | null>(null);

  // Run all tests mutation
  const runAllTestsMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest('POST', '/api/admin/test/run-all');
      return response.json();
    },
    onSuccess: (data: TestReport) => {
      setTestReport(data);
      toast({
        title: 'Tests completed',
        description: data.message,
        variant: data.overallStatus === 'passed' ? 'default' : 
                 data.overallStatus === 'warning' ? 'default' : 'destructive',
      });
    },
    onError: (error: any) => {
      toast({
        title: 'Failed to run tests',
        description: error.message || 'Test execution failed',
        variant: 'destructive',
      });
    },
  });

  // Run search extension test mutation
  const runExtensionTestMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest('POST', '/api/admin/test/extension');
      return response.json();
    },
    onSuccess: (data: TestReport) => {
      setTestReport(data);
      toast({
        title: 'Extension test completed',
        description: data.message,
        variant: data.overallStatus === 'passed' ? 'default' : 
                 data.overallStatus === 'warning' ? 'default' : 'destructive',
      });
    },
    onError: (error: any) => {
      toast({
        title: 'Failed to run extension test',
        description: error.message || 'Extension test execution failed',
        variant: 'destructive',
      });
    },
  });

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'passed':
        return <CheckCircle className="h-4 w-4 text-green-600" />;
      case 'failed':
        return <XCircle className="h-4 w-4 text-red-600" />;
      case 'warning':
        return <AlertTriangle className="h-4 w-4 text-yellow-600" />;
      case 'running':
        return <RefreshCw className="h-4 w-4 text-blue-600 animate-spin" />;
      default:
        return <Clock className="h-4 w-4 text-gray-400" />;
    }
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, any> = {
      passed: 'default',
      failed: 'destructive',
      warning: 'secondary',
      running: 'outline',
      pending: 'outline'
    };

    return (
      <Badge variant={variants[status] || 'outline'}>
        {status}
      </Badge>
    );
  };

  const getCategoryIcon = (category: string) => {
    switch (category.toLowerCase()) {
      case 'database connectivity':
        return <Database className="h-4 w-4 text-muted-foreground" />;
      case 'search functionality':
        return <Search className="h-4 w-4 text-muted-foreground" />;
      case 'api health':
        return <Globe className="h-4 w-4 text-muted-foreground" />;
      case 'authentication':
        return <Shield className="h-4 w-4 text-muted-foreground" />;
      default:
        return <AlertTriangle className="h-4 w-4 text-muted-foreground" />;
    }
  };

  return (
    <div className="container mx-auto py-8 px-4">
      <div className="space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Button
              onClick={() => setLocation('/admin')}
              variant="ghost"
              size="sm"
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Dashboard
            </Button>
            <div>
              <h1 className="text-3xl font-bold tracking-tight">API Testing & Workflows</h1>
              <p className="text-muted-foreground mt-1">
                Test system APIs and monitor workflow health
              </p>
            </div>
          </div>
          <Button
            onClick={() => runAllTestsMutation.mutate()}
            disabled={runAllTestsMutation.isPending}
            size="sm"
          >
            {runAllTestsMutation.isPending ? (
              <>
                <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                Running Tests...
              </>
            ) : (
              <>
                <Play className="h-4 w-4 mr-2" />
                Run All Tests
              </>
            )}
          </Button>
        </div>

        {/* Test Summary */}
        {testReport && (
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center justify-between">
                <span>Test Results Summary</span>
                {getStatusBadge(testReport.overallStatus)}
              </CardTitle>
              <CardDescription>
                Executed in {testReport.duration}ms on {new Date(testReport.timestamp).toLocaleString()}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid gap-4 md:grid-cols-4">
                <div className="flex items-center gap-2">
                  <CheckCircle className="h-4 w-4 text-green-600" />
                  <div>
                    <div className="text-2xl font-bold">{testReport.summary.passed}</div>
                    <p className="text-xs text-muted-foreground">Passed</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <XCircle className="h-4 w-4 text-red-600" />
                  <div>
                    <div className="text-2xl font-bold">{testReport.summary.failed}</div>
                    <p className="text-xs text-muted-foreground">Failed</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <AlertTriangle className="h-4 w-4 text-yellow-600" />
                  <div>
                    <div className="text-2xl font-bold">{testReport.summary.warnings}</div>
                    <p className="text-xs text-muted-foreground">Warnings</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Clock className="h-4 w-4 text-blue-600" />
                  <div>
                    <div className="text-2xl font-bold">{testReport.summary.total}</div>
                    <p className="text-xs text-muted-foreground">Total Tests</p>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Individual Test Results */}
        {testReport?.tests && testReport.tests.length > 0 && (
          <div className="space-y-4">
            {testReport.tests.map((test, index) => (
              <Card key={index}>
                <CardHeader>
                  <CardTitle className="text-lg flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      {getCategoryIcon(test.name)}
                      <span>{test.name}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      {test.duration && (
                        <Badge variant="outline" className="text-xs">
                          {test.duration}ms
                        </Badge>
                      )}
                      {getStatusBadge(test.status)}
                    </div>
                  </CardTitle>
                  <CardDescription>{test.message}</CardDescription>
                </CardHeader>
                {test.subTests && test.subTests.length > 0 && (
                  <CardContent>
                    <div className="space-y-2">
                      {test.subTests.map((subTest: any, subIndex: number) => (
                        <div
                          key={subIndex}
                          className="flex items-center justify-between p-3 border rounded-lg"
                        >
                          <div className="flex items-center gap-3">
                            {getStatusIcon(subTest.status)}
                            <div>
                              <div className="font-medium text-sm">{subTest.name}</div>
                              <div className="text-xs text-muted-foreground">
                                {subTest.message}
                              </div>
                              {subTest.error && (
                                <div className="text-xs text-red-600 mt-1">
                                  Error: {subTest.error}
                                </div>
                              )}
                            </div>
                          </div>
                          {subTest.data && (
                            <code className="text-xs bg-muted px-2 py-1 rounded">
                              {JSON.stringify(subTest.data)}
                            </code>
                          )}
                        </div>
                      ))}
                    </div>
                  </CardContent>
                )}
                {test.error && (
                  <CardContent>
                    <div className="p-3 border border-red-200 bg-red-50 rounded-lg">
                      <div className="text-sm text-red-800">
                        <strong>Error:</strong> {test.error}
                      </div>
                    </div>
                  </CardContent>
                )}
              </Card>
            ))}
          </div>
        )}

        {/* No Tests Run Yet */}
        {!testReport && !runAllTestsMutation.isPending && (
          <Card>
            <CardContent className="py-12 text-center">
              <Clock className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
              <h3 className="text-lg font-semibold mb-2">No tests run yet</h3>
              <p className="text-muted-foreground mb-4">
                Click "Run All Tests" to execute the comprehensive system test suite
              </p>
              <Button onClick={() => runAllTestsMutation.mutate()}>
                <Play className="h-4 w-4 mr-2" />
                Run All Tests Now
              </Button>
            </CardContent>
          </Card>
        )}

        {/* Search Extension Test Card */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Search className="h-5 w-5" />
              "+5 More" Extension Test
            </CardTitle>
            <CardDescription>
              Test the search extension feature that adds 5 additional companies to existing searches
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div className="p-4 bg-muted rounded-lg">
                <h4 className="font-medium mb-2">What this test does:</h4>
                <ul className="text-sm text-muted-foreground space-y-1">
                  <li>• Creates an initial search job</li>
                  <li>• Tests the extension endpoint with exclude lists</li>
                  <li>• Verifies exactly 5 unique companies are added</li>
                  <li>• Checks for duplicates and data integrity</li>
                  <li>• Validates contact and email discovery for extensions</li>
                </ul>
              </div>
              <Button
                onClick={() => runExtensionTestMutation.mutate()}
                disabled={runExtensionTestMutation.isPending || runAllTestsMutation.isPending}
                className="w-full"
                variant="default"
              >
                {runExtensionTestMutation.isPending ? (
                  <>
                    <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
                    Running Extension Test...
                  </>
                ) : (
                  <>
                    <Play className="h-4 w-4 mr-2" />
                    Run "+5 More" Extension Test
                  </>
                )}
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Quick Links */}
        <Card>
          <CardHeader>
            <CardTitle>Additional Testing Tools</CardTitle>
            <CardDescription>
              Access other testing and monitoring features
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex flex-wrap gap-2">
              <Button
                onClick={() => setLocation('/testing')}
                variant="outline"
                size="sm"
              >
                <AlertTriangle className="h-4 w-4 mr-2" />
                System Health Dashboard
              </Button>
              <Button
                onClick={() => setLocation('/admin/email')}
                variant="outline"
                size="sm"
              >
                <Globe className="h-4 w-4 mr-2" />
                Email Testing
              </Button>
              <Button
                onClick={() => window.open('/api/test/health', '_blank')}
                variant="outline"
                size="sm"
              >
                <Shield className="h-4 w-4 mr-2" />
                API Health Check
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

