import type { Express } from "express";
import { generateEmailContent } from "./service";
import type { EmailGenerationRequest } from "./types";

export function registerEmailGenerationRoutes(app: Express, requireAuth: any) {
  app.post("/api/generate-email", requireAuth, async (req, res) => {
    const { emailPrompt, contact, company, tone, offerStrategy, generateTemplate, productContext, senderProfile } = req.body;

    if (!emailPrompt || !company) {
      res.status(400).json({ message: "Missing required parameters" });
      return;
    }

    try {
      const userId = (req.user as any).id;

      const request: EmailGenerationRequest = {
        emailPrompt,
        contact: contact || null,
        company,
        userId,
        toEmail: req.body.toEmail,
        emailSubject: req.body.emailSubject,
        tone: tone || 'default',
        offerStrategy: offerStrategy || 'none',
        generateTemplate: generateTemplate || false,
        productContext: productContext || undefined,
        senderProfile: senderProfile || undefined
      };

      const result = await generateEmailContent(request);

      res.json(result);
    } catch (error) {
      console.error('Email generation error:', error);
      res.status(500).json({
        message: error instanceof Error ? error.message : "An unexpected error occurred during email generation"
      });
    }
  });
}

server/features/daily-outreach/routes.ts.content:
import { Router } from 'express';
import { db } from '../../db';
import { 
  dailyOutreachBatches, 
  dailyOutreachItems, 
  userOutreachPreferences,
  dailyOutreachJobs,
  users,
  contacts,
  companies,
  communicationHistory
} from '@shared/schema';
import { eq, and, lte, gte, lt, sql, not, desc } from 'drizzle-orm';
import { startOfDay, endOfDay } from 'date-fns';
import { persistentScheduler as outreachScheduler } from './services/persistent-scheduler';
import { batchGenerator } from './services/batch-generator';
import { dripEmailEngine } from '../../email/drip-engine';
import { buildContactsReadyEmail } from './email-templates/contacts-ready';
import { mockContactsForTesting } from './email-templates/mock-contacts-for-testing';
import type { Request, Response } from 'express';
import streakRoutes from './routes-streak';
import { requireAuth } from '../../utils/auth';

const router = Router();

// Mount streak routes
router.use('/', streakRoutes);

// Get user's outreach preferences
router.get('/preferences', requireAuth, async (req: Request, res: Response) => {
  try {
    const userId = (req as any).user?.id;
    if (!userId) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    const [preferences] = await db
      .select()
      .from(userOutreachPreferences)
      .where(eq(userOutreachPreferences.userId, userId));

    if (!preferences) {
      // Return default preferences if none exist
      return res.json({
        enabled: false,
        scheduleDays: ['mon', 'tue', 'wed'],
        scheduleTime: '09:00',
        timezone: 'America/New_York',
        minContactsRequired: 5
      });
    }

    res.json(preferences);
  } catch (error) {
    console.error('Error fetching outreach preferences:', error);
    res.status(500).json({ error: 'Failed to fetch preferences' });
  }
});

// Update user's outreach preferences
router.put('/preferences', requireAuth, async (req: Request, res: Response) => {
  try {
    const userId = (req as any).user?.id;
    if (!userId) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    const { enabled, scheduleDays, scheduleTime, timezone, minContactsRequired, activeProductId, activeSenderProfileId, activeCustomerProfileId } = req.body;

    // Check if preferences exist
    const [existing] = await db
      .select()
      .from(userOutreachPreferences)
      .where(eq(userOutreachPreferences.userId, userId));

    let preferences;
    if (existing) {
      // Update existing preferences - only update fields that were provided
      const updateData = Object.fromEntries(
        Object.entries({
          enabled,
          scheduleDays,
          scheduleTime,
          timezone,
          minContactsRequired,
          activeProductId,
          activeSenderProfileId,
          activeCustomerProfileId,
          updatedAt: new Date()
        }).filter(([_, v]) => v !== undefined)
      );

      [preferences] = await db
        .update(userOutreachPreferences)
        .set(updateData)
        .where(eq(userOutreachPreferences.userId, userId))
        .returning();
    } else {
      // Create new preferences - only include fields that were provided
      const insertData: any = {
        userId, // userId is always required
        ...Object.fromEntries(
          Object.entries({
            enabled,
            scheduleDays,
            scheduleTime,
            timezone,
            minContactsRequired,
            activeProductId,
            activeSenderProfileId,
            activeCustomerProfileId
          }).filter(([_, v]) => v !== undefined)
        )
      };

      [preferences] = await db
        .insert(userOutreachPreferences)
        .values(insertData)
        .returning();
    }

    // Update scheduler only if enabled field was explicitly provided
    if (enabled !== undefined) {
      if (enabled) {
        await outreachScheduler.updateUserPreferences(userId, preferences);
      } else {
        await outreachScheduler.disableUserOutreach(userId);
      }
    }

    res.json(preferences);
  } catch (error) {
    console.error('Error updating outreach preferences:', error);
    res.status(500).json({ error: 'Failed to update preferences' });
  }
});

// Preview email template
router.get('/preview', requireAuth, async (req: Request, res: Response) => {
  try {
    const userId = (req as any).user?.id;
    if (!userId) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    // Get user details
    const [user] = await db
      .select()
      .from(users)
      .where(eq(users.id, userId));

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Try to get the most recent batch for this user
    const [recentBatch] = await db
      .select()
      .from(dailyOutreachBatches)
      .where(eq(dailyOutreachBatches.userId, userId))
      .orderBy(dailyOutreachBatches.createdAt)
      .limit(1);

    let batch;
    if (recentBatch) {
      // Get batch items with contact and company details
      const items = await db
        .select({
          item: dailyOutreachItems,
          contact: contacts,
          company: companies
        })
        .from(dailyOutreachItems)
        .innerJoin(contacts, eq(dailyOutreachItems.contactId, contacts.id))
        .innerJoin(companies, eq(dailyOutreachItems.companyId, companies.id))
        .where(eq(dailyOutreachItems.batchId, recentBatch.id))
        .limit(5);

      batch = {
        ...recentBatch,
        items: items.map(({ item, contact, company }) => ({
          ...item,
          contact,
          company
        })),
        hasContacts: items.length > 0
      };
    } else {
      // Generate a sample batch for preview
      batch = await batchGenerator.generateDailyBatch(userId);
    }

    // If still no batch, create a minimal sample
    if (!batch) {
      batch = {
        id: 0,
        userId,
        batchDate: new Date(),
        secureToken: 'preview-token',
        status: 'preview',
        expiresAt: new Date(Date.now() + 100 * 365 * 24 * 60 * 60 * 1000), // Set to 100 years (effectively no expiration)
        createdAt: new Date(),
        items: [],
        hasContacts: true
      };
    }

    // Generate the email HTML using the imported template
    const appUrl = process.env.APP_URL || 'https://5ducks.ai';
    const emailContent = buildContactsReadyEmail(batch, appUrl);

    // Return HTML directly with proper content type
    res.setHeader('Content-Type', 'text/html');
    res.send(emailContent.html);
  } catch (error) {
    console.error('Error generating email preview:', error);
    res.status(500).json({ error: 'Failed to generate preview' });
  }
});

// Manual trigger for testing (only in development)
router.post('/trigger', requireAuth, async (req: Request, res: Response) => {
  try {
    const userId = (req as any).user?.id;
    if (!userId) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (process.env.NODE_ENV === 'production') {
      return res.status(403).json({ error: 'Manual trigger not allowed in production' });
    }

    // Get user details
    const [user] = await db
      .select()
      .from(users)
      .where(eq(users.id, userId));

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Generate batch
    const batch = await batchGenerator.generateDailyBatch(userId);

    if (!batch) {
      return res.json({ 
        success: false, 
        message: 'Not enough contacts with emails available. Please add more emails first.' 
      });
    }

    // Send email via drip engine
    const appUrl = process.env.APP_URL || 'https://5ducks.ai';
    const emailContent = buildContactsReadyEmail(batch, appUrl);
    const sent = await dripEmailEngine.sendImmediate(user.email, emailContent, '5Ducks Daily');

    if (sent) {
      // Update last nudge sent
      await db
        .update(userOutreachPreferences)
        .set({ lastNudgeSent: new Date() })
        .where(eq(userOutreachPreferences.userId, userId));
    }

    res.json({ 
      success: sent, 
      batchId: batch.id,
      secureToken: batch.secureToken,
      itemCount: batch.items.length,
      message: sent 
        ? 'Daily nudge email sent successfully' 
        : 'Failed to send email. Check SendGrid configuration.'
    });
  } catch (error) {
    console.error('Error triggering manual outreach:', error);
    res.status(500).json({ error: 'Failed to trigger outreach' });
  }
});

// Send test email endpoint
router.post('/send-test-email', requireAuth, async (req: Request, res: Response) => {
  try {
    const userId = (req as any).user?.id;
    const { email: targetEmail } = req.body; // Accept email from request body

    if (!userId) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    // Get user details
    const [user] = await db
      .select()
      .from(users)
      .where(eq(users.id, userId));

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Check if SendGrid is configured
    if (!process.env.SENDGRID_API_KEY) {
      return res.json({ 
        success: false, 
        message: 'SendGrid is not configured. Please add SENDGRID_API_KEY to environment variables.' 
      });
    }

    // Always use mock contacts for test emails
    const testBatch: any = {
      id: 0,
      userId,
      batchDate: new Date(),
      secureToken: 'test-email-token',
      status: 'test',
      expiresAt: new Date(Date.now() + 100 * 365 * 24 * 60 * 60 * 1000), // Set to 100 years (effectively no expiration)
      createdAt: new Date(),
      items: mockContactsForTesting, // Use the static mock contacts
      hasContacts: true,
      isSampleData: true // Flag to indicate this is sample data
    };

    // Create a modified user object with the target email if provided
    const testUser = targetEmail ? { ...user, email: targetEmail } : user;

