      const pollJobStatus = async () => {
        if (!isPollingRef.current) return;

        try {
          const response = await apiRequest("GET", `/api/search-jobs/${data.jobId}`);
          if (response.ok) {
            const jobData = await response.json();

            if ((jobData.status === 'processing' || jobData.status === 'completed') && jobData.results) {
              const companies = jobData.results?.companies || [];
              const totalContacts = companies.reduce((sum: number, company: any) => 
                sum + (company.contacts?.length || 0), 0);

              if (companies.length > 0) {
                if (currentSessionId) {
                  SearchSessionManager.updateWithFullResults(currentSessionId, companies);
                  onSearchResults(value, companies);
                }
                console.log(`Individual search update: ${companies.length} companies, ${totalContacts} contacts`);
              }
            }

            if (jobData.status === 'completed') {
              console.log(`Individual search job ${data.jobId} completed`);
              isPollingRef.current = false;
              setIsPolling(false);
              setIsIndividualSearching(false);
              setCurrentSessionId(null); // Clear session ID

              const companies = jobData.results?.companies || [];
              const totalContacts = companies.reduce((sum: number, company: any) => 
                sum + (company.contacts?.length || 0), 0);

              onComplete();
              onSearchSuccess?.();

              queryClient.invalidateQueries({ queryKey: ['/api/credits'] });

              toast({
                title: "Individual Search Complete",
                description: `Found ${totalContacts} candidate(s)`,
              });
            } else if (jobData.status === 'failed') {
              isPollingRef.current = false;
              setIsPolling(false);
              setIsIndividualSearching(false);
              setCurrentSessionId(null); // Clear session ID

              // Clear the progress display
              setSearchProgress(prev => ({ ...prev, phase: "", completed: 0, total: 5 }));

              // Determine error type for better messaging
              const errorMessage = jobData.error || "Individual search failed";
              const isInsufficientCredits = errorMessage.toLowerCase().includes('insufficient credits');

              // Show toast notification
              try {
                toast({
                  title: isInsufficientCredits ? "Insufficient Credits" : "Search Failed",
                  description: errorMessage,
                  variant: "destructive",
                });
              } catch (toastError) {
                console.error("Failed to show toast:", toastError);
              }

              // Refresh credits display
              queryClient.invalidateQueries({ queryKey: ['/api/credits'] });

              onComplete();
            } else {
              // Job still processing - but check for error phases that indicate failure
              const currentPhase = jobData.progress?.phase || "";
              const isErrorPhase = currentPhase.toLowerCase().includes('error') || 
                                   currentPhase.toLowerCase().includes('insufficient');
              const errorMessage = jobData.progress?.message || jobData.error || "";

              if (isErrorPhase) {
                // Stop polling - this is a failure state
                console.error(`Individual search job ${data.jobId} has error phase:`, currentPhase, errorMessage);
                isPollingRef.current = false;
                setIsPolling(false);
                setIsIndividualSearching(false);
                setCurrentSessionId(null); // Clear session ID

                // Clear progress display
                setSearchProgress(prev => ({ ...prev, phase: "", completed: 0, total: 5 }));

                // Show toast with appropriate message
                const isInsufficientCredits = currentPhase.toLowerCase().includes('insufficient') ||
                                              errorMessage.toLowerCase().includes('insufficient credits');
                toast({
                  title: isInsufficientCredits ? "Insufficient Credits" : "Search Failed",
                  description: isInsufficientCredits 
                    ? "You don't have enough credits for this search. Please add more credits to continue."
                    : (errorMessage || "An error occurred during search"),
                  variant: "destructive",
                });

                queryClient.invalidateQueries({ queryKey: ['/api/credits'] });
                onComplete();
              } else {
                setTimeout(pollJobStatus, 500);
              }
            }
          }
        } catch (error) {
          console.error("Individual search polling error:", error);
          if (isPollingRef.current) {
            setTimeout(pollJobStatus, 1000);
          }
        }
      };

      // Start polling immediately - backend will drive progress updates
      isPollingRef.current = true;
      setIsPolling(true);
      pollJobStatus();
    },
    onError: (error: Error) => {
      setIsIndividualSearching(false);

      // Clear any progress display
      setSearchProgress(prev => ({ ...prev, phase: "", completed: 0, total: 5 }));

      const errorMessage = error.message || "Search failed";
      const isInsufficientCredits = errorMessage.includes("402:") || 
                                     errorMessage.toLowerCase().includes("insufficient credits");

      if (isInsufficientCredits) {
        triggerInsufficientCreditsGlobally();
      } else {
        try {
          toast({
            title: "Search Failed",
            description: errorMessage,
            variant: "destructive",
          });
        } catch (toastError) {
          console.error("Failed to show toast:", toastError);
        }
      }

      // Refresh credits display
      queryClient.invalidateQueries({ queryKey: ['/api/credits'] });

      onComplete();
    },
  });

  // Report progress changes to parent for rendering outside collapsible section
  useEffect(() => {
    if (onProgressUpdate) {
      const isVisible = quickSearchMutation.isPending || isPolling || individualSearchMutation.isPending;
      onProgressUpdate({
        phase: searchProgress.phase,
        completed: searchProgress.completed,
        total: searchProgress.total,
        isVisible
      });
    }
  }, [searchProgress.phase, searchProgress.completed, searchProgress.total, quickSearchMutation.isPending, isPolling, individualSearchMutation.isPending, onProgressUpdate]);

  // Handle structured individual search from modal
  const handleIndividualSearch = (formData: IndividualSearchFormData) => {
    setIsIndividualSearching(true);
    onAnalyze();

    // Update the textarea value for display
    const displayQuery = [
      formData.fullName,
      formData.role,
      formData.company ? `at ${formData.company}` : null,
      formData.location ? `in ${formData.location}` : null,
    ].filter(Boolean).join(' ');
    onChange(displayQuery);

    setSearchProgress({ phase: "Starting search", completed: 0, total: 5 });
    setSearchMetrics({
      query: displayQuery,
      totalCompanies: 0,
      totalContacts: 0,
      totalEmails: 0,
      searchDuration: 0,
      startTime: Date.now(),
      companies: []
    });

    individualSearchMutation.mutate(formData);
  };

  const handleSearch = async () => {
    if (!value.trim()) {
      toast({
        title: "Empty Query",
        description: "Please enter a search query.",
        variant: "destructive",
      });
      return;
    }

    // Easter egg check - intercept before normal search
    const trimmedQuery = value.trim().toLowerCase();
    if (trimmedQuery === "5ducks" || trimmedQuery === "free palestine" || trimmedQuery === "he is risen") {
      try {
        const response = await apiRequest("POST", "/api/credits/easter-egg", { query: value.trim() });
        const result = await response.json();

        toast({
          title: `${result.easterEgg.emoji} Easter Egg Found!`,
          description: `${result.easterEgg.description} - +${result.easterEgg.reward} credits added!`,
        });

        // Refresh credits display
        queryClient.invalidateQueries({ queryKey: ['/api/credits'] });
        onComplete();
        return; // Skip normal search
      } catch (error: any) {
        const errorData = await error.response?.json();
        toast({
          title: "Easter Egg",
          description: errorData?.message || "Already claimed!",
          variant: "destructive",
        });
        onComplete();
        return; // Skip normal search
      }
    }

    // Dismiss the landing page hint if active
    if (isFromLandingPage && onDismissLandingHint) {
      onDismissLandingHint();
    }

    // Don't reset inputHasChanged here - wait until search completes

    // Reset progress - backend will drive updates via polling
    setSearchProgress({ phase: "Starting search", completed: 0, total: 5 });

    // Initialize search metrics
    setSearchMetrics({
      query: value,
      totalCompanies: 0,
      totalContacts: 0,
      totalEmails: 0,
      searchDuration: 0,
      startTime: Date.now(),
      companies: []
    });

    // Push event to dataLayer for GTM to handle conversion tracking
    window.dataLayer?.push({ event: 'search_performed' });
    // Log attribution event
    logConversionEvent('search_performed').catch(() => {});

    console.log("Analyzing search query...");
    const isSuperSearch = searchType === 'super_search_fast' || searchType === 'super_search_deep' || searchType === 'super_search_query_first';
    console.log(`Preparing to search for ${searchType === 'companies' ? 'companies only' : searchType === 'contacts' ? 'companies and contacts' : searchType === 'individual_search' ? 'specific individual' : isSuperSearch ? 'AI-powered super search' : 'companies, contacts, and emails'}...`);
    onAnalyze();

    // Choose search strategy based on selected search type
    if (isSuperSearch) {
      // Super Search - uses SSE streaming
      const variantId = searchType === 'super_search_fast' 
        ? 'v1_perplexity_one-shot' 
        : searchType === 'super_search_deep'
        ? 'v2_anthropic_multi-step'
        : 'v3_anthropic_query-first';
      if (superSearch && onSuperSearchActive) {
        onSuperSearchActive(true);
        superSearch.startSearch(value, undefined, variantId);
      }
      return; // Super search handles its own flow
    } else if (searchType === 'companies') {
      // Companies-only search - use quick search without contact enrichment
      quickSearchMutation.mutate(value);
    } else {
      // Full search with contacts (and potentially emails)
      quickSearchMutation.mutate(value);
    }

    // Semi-protected logic: Show registration modal after 35 seconds if not authenticated
    if (!user) {
      setTimeout(() => {
        openForProtectedRoute();
      }, 35000);
    }

    // Parallel cache check - runs alongside the search (unless bypass flag is set)
    cacheHitRef.current = false;
    const shouldBypassCache = sessionStorage.getItem('forceBypassCache') === 'true';

    // Clear the bypass flag immediately after reading it
    if (shouldBypassCache) {
      sessionStorage.removeItem('forceBypassCache');
      console.log('🔄 Bypass cache flag detected - skipping cache check for fresh results');
    }

    const cacheCheck = async () => {
      // Skip cache check if bypass flag was set
      if (shouldBypassCache) {
        console.log('🔄 Cache bypass active - fetching fresh results');
        return;
      }

      try {
        const response = await fetch(`/api/lists/by-prompt?prompt=${encodeURIComponent(value)}`);
        const cachedResult = await response.json();

        if (cachedResult && cachedResult.listId && !cacheHitRef.current) {
          console.log(`🎯 Cache hit! Found cached search (listId: ${cachedResult.listId})`);
          cacheHitRef.current = true;

          // Terminate the running job if we have one
          if (currentJobIdRef.current) {
            try {
              await apiRequest("POST", `/api/search-jobs/${currentJobIdRef.current}/terminate`);
              console.log(`Terminated job ${currentJobIdRef.current} due to cache hit`);
            } catch (e) {
              console.log('Job termination skipped (may have already completed)');
            }
          }

          // Stop polling
          isPollingRef.current = false;
          setIsPolling(false);
          setCurrentSessionId(null); // Clear session ID on cache hit

          // Notify parent of cache hit
          if (onCacheHit) {
            onCacheHit(cachedResult);
          }

          toast({
            title: "Loaded cached results",
            description: `Found ${cachedResult.resultCount} companies from a previous search.`,
          });
        }
      } catch (error) {
        console.log('Cache check failed, continuing with fresh search');
      }
    };

    // Start cache check in parallel (non-blocking)
    cacheCheck();
  };

  // Ref to hold the latest handleSearch function for event listener
  const handleSearchRef = useRef<() => void>(() => {});
  useEffect(() => {
    handleSearchRef.current = handleSearch;
  });

  // Listen for triggerFreshSearch event from parent (cache refresh button)
  useEffect(() => {
    const handleTriggerFreshSearch = () => {
      console.log('🔄 Fresh search triggered via event');
      // Trigger the search using the ref to get the latest function
      handleSearchRef.current();
    };

    window.addEventListener('triggerFreshSearch', handleTriggerFreshSearch);

    return () => {
      window.removeEventListener('triggerFreshSearch', handleTriggerFreshSearch);
    };
  }, []);

  // Stop button handler - allows user to manually stop a search
  const handleStopSearch = async () => {
    console.log('User requested search stop');

    // Stop polling first
    isPollingRef.current = false;
    setIsPolling(false);

    // Terminate the job if we have one
    if (currentJobIdRef.current) {
      try {
        await apiRequest("POST", `/api/search-jobs/${currentJobIdRef.current}/terminate`);
        console.log(`Terminated job ${currentJobIdRef.current}`);
        toast({
          title: "Search stopped",
          description: "The search has been cancelled.",
        });
      } catch (e) {
        console.log('Job termination failed');
      }
    }

    // Reset state
    currentJobIdRef.current = null;
    setCurrentSessionId(null); // Clear session ID to prevent polling restart
    onComplete();
  };

  return (
    <div className="pl-0 pr-1 pt-1 pb-1 shadow-none"> {/* Container with no padding */}
      <div className="flex flex-col gap-0 md:gap-2">
        <div className="relative">
          <Textarea
            value={value}
            onChange={(e) => {
              onChange(e.target.value);
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey && !(isAnalyzing || quickSearchMutation.isPending)) {
                e.preventDefault();
                handleSearch();
              }
            }}
            placeholder="Recently exited startups in Miami "
            rows={2}
            className={`md:rounded-md rounded-md resize-none pb-12 text-base md:text-lg text-foreground placeholder:text-muted-foreground/50 hover:border-border md:focus-visible:border-border ${isFromLandingPage ? 'racing-light-effect' : ''} ${showGradientText ? 'gradient-text-input' : ''}`}
            data-testid="search-input"
          />

          {/* Bottom controls container - positioned inside textarea */}
          <div className="absolute bottom-2 left-2 right-2 flex items-end justify-between pointer-events-none">
            {/* Left side: Search type selector and role indicator */}
            <div className="pointer-events-auto flex items-center gap-2">
              <SearchTypeSelector
                selectedType={searchType}
                onTypeChange={handleSearchTypeChange}
                disabled={isAnalyzing || quickSearchMutation.isPending || individualSearchMutation.isPending}
              />

              {/* Active role indicator button - always grayed out */}
              {(() => {
                // Determine which role is active and display it
                if (contactSearchConfig.enableCoreLeadership) {
                  return (
                    <button
                      onClick={toggleRoleSelector}
                      className="flex items-center gap-1 px-2 py-1 rounded text-muted-foreground text-sm hover:bg-muted-hover transition-colors cursor-pointer"
                    >
                      <Crown className="h-3 w-3 md:h-[14px] md:w-[14px] lg:h-[18px] lg:w-[18px]" />
                      <span className="font-medium">Leadership</span>
                    </button>
                  );
                } else if (contactSearchConfig.enableDepartmentHeads) {
                  return (
                    <button
                      onClick={toggleRoleSelector}
                      className="flex items-center gap-1 px-2 py-1 rounded text-muted-foreground text-sm hover:bg-muted-hover transition-colors cursor-pointer"
                    >
                      <Building className="h-3 w-3 md:h-[14px] md:w-[14px] lg:h-[18px] lg:w-[18px]" />
                      <span className="font-medium">Marketing</span>
                    </button>
                  );
                } else if (contactSearchConfig.enableMiddleManagement) {
                  return (
                    <button
                      onClick={toggleRoleSelector}
                      className="flex items-center gap-1 px-2 py-1 rounded text-muted-foreground text-sm hover:bg-muted-hover transition-colors cursor-pointer"
                    >
                      <Users className="h-3 w-3 md:h-[14px] md:w-[14px] lg:h-[18px] lg:w-[18px]" />
                      <span className="font-medium">CTO</span>
                    </button>
                  );
                } else if (contactSearchConfig.enableCustomSearch && contactSearchConfig.customSearchTarget) {
                  return (
                    <button
                      onClick={toggleRoleSelector}
                      className="flex items-center gap-1 px-2 py-1 rounded text-muted-foreground text-sm hover:bg-muted-hover transition-colors cursor-pointer"
                    >
                      <Target className="h-3 w-3 md:h-[14px] md:w-[14px] lg:h-[18px] lg:w-[18px]" />
                      <span className="font-medium">{contactSearchConfig.customSearchTarget}</span>
                    </button>
                  );
                } else if (contactSearchConfig.enableCustomSearch2 && contactSearchConfig.customSearchTarget2) {
                  return (
                    <button
                      onClick={toggleRoleSelector}
                      className="flex items-center gap-1 px-2 py-1 rounded text-muted-foreground text-sm hover:bg-muted-hover transition-colors cursor-pointer"
                    >
                      <Target className="h-3 w-3 md:h-[14px] md:w-[14px] lg:h-[18px] lg:w-[18px]" />
                      <span className="font-medium">{contactSearchConfig.customSearchTarget2}</span>
                    </button>
                  );
                }
                return null;
              })()}

              {/* Search Management Gear Icon - Admin only */}
              {user?.isAdmin && (
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <button
                        onClick={onOpenSearchDrawer}
                        className="flex items-center justify-center p-2 rounded-full text-muted-foreground hover:bg-muted-hover hover:text-foreground transition-colors cursor-pointer"
                        aria-label="Search Management"
                        data-testid="button-search-management"
                      >
                        <Settings className="h-4 w-4" />
                      </button>
                    </TooltipTrigger>
                    <TooltipContent>
                      <p>Manage Search Queue</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              )}
            </div>

            {/* Right side: Search/Stop button */}
            <div className="pointer-events-auto">
              {(() => {
                const isSearchActive = isAnalyzing || quickSearchMutation.isPending || isPolling;
                console.log('[STATE] isSearchActive:', { isAnalyzing, isPending: quickSearchMutation.isPending, isPolling, result: isSearchActive });
                return (
                  <Button 
                    type={isSearchActive ? "button" : "submit"}
                    onClick={isSearchActive ? handleStopSearch : handleSearch}
                    disabled={!isSearchActive && (isAnalyzing || quickSearchMutation.isPending)}
                    className={`
                      rounded-md group
                      transition-all duration-300 flex items-center gap-2
                      ${!value?.trim() || (lastExecutedQuery && !inputHasChanged && !isSearchActive)
                        ? 'bg-secondary hover:bg-secondary-hover shadow-md hover:shadow-lg text-muted-foreground' 
                        : 'bg-gradient-to-r from-accent-light to-accent hover:from-accent hover:to-accent-dark text-white shadow-md hover:shadow-lg'
                      }
                    `}
                    aria-label={isSearchActive ? "Stop Search" : "Search"}
                    data-testid={isSearchActive ? "stop-search-button" : "search-button"}
                  >
                    {isSearchActive ? (
                      <>
                        {/* Desktop: Searching by default, Stop on hover */}
                        <Loader2 className="h-4 w-4 animate-spin hidden md:block md:group-hover:hidden" />
                        <span className="hidden md:block md:group-hover:hidden">Searching</span>
                        {/* Desktop hover + Mobile default: Stop */}
                        <Square className="h-4 w-4 block md:hidden md:group-hover:block" />
                        <span className="block md:hidden md:group-hover:block">Stop</span>
                      </>
                    ) : (
                      <>
                        <Search className="h-4 w-4" />
                        <span>Search</span>
                      </>
                    )}
                  </Button>
                );
              })()}
            </div>
          </div>
        </div>

        {/* Mobile layout: Contact chips - only shown when showRoleSelector is true */}
        {!hideRoleButtons && showRoleSelector && (
          <div className="md:hidden">
            <ContactSearchChips
              config={contactSearchConfig}
              onConfigChange={handleContactSearchConfigChange}
              disabled={isAnalyzing || quickSearchMutation.isPending}
              isSearching={quickSearchMutation.isPending}
              hasSearchResults={hasSearchResults}
              inputHasChanged={hasSearchResults && value !== lastExecutedQuery}
            />
          </div>
        )}

        {/* Desktop Contact Search Chips - positioned below search input, only shown when showRoleSelector is true */}
        {!hideRoleButtons && showRoleSelector && (
          <div className="hidden md:block">
            <ContactSearchChips
              config={contactSearchConfig}
              onConfigChange={handleContactSearchConfigChange}
              disabled={isAnalyzing || quickSearchMutation.isPending}
              isSearching={quickSearchMutation.isPending}
              hasSearchResults={hasSearchResults}
              inputHasChanged={hasSearchResults && value !== lastExecutedQuery}
            />
          </div>
        )}

        {/* Progress Bar is now rendered in Home.tsx via onProgressUpdate callback */}

      </div>


      {/* Individual Search Modal */}
      <IndividualSearchModal
        isOpen={isIndividualSearchModalOpen}
        onClose={() => setIsIndividualSearchModalOpen(false)}
        onSearch={handleIndividualSearch}
        isSearching={isIndividualSearching}
      />
    </div>
  );
}

