import { createContext, useState, useContext, useEffect, ReactNode } from "react";
import { useAuth } from "./use-auth";

export type RegistrationPage = "main" | "login" | "forgotPassword";

type RegistrationModalContextType = {
  isOpen: boolean;
  initialPage: RegistrationPage;
  openModal: () => void;
  openModalForLogin: () => void;
  closeModal: () => void;
  openForProtectedRoute: () => void;
  isOpenedFromProtectedRoute: boolean;
  setRegistrationSuccessCallback: (callback: (isNewUser?: boolean) => void) => void;
  setIsNewUser: (isNewUser: boolean) => void;
};

const RegistrationModalContext = createContext<RegistrationModalContextType>({
  isOpen: false,
  initialPage: "main",
  openModal: () => {},
  openModalForLogin: () => {},
  closeModal: () => {},
  openForProtectedRoute: () => {},
  isOpenedFromProtectedRoute: false,
  setRegistrationSuccessCallback: () => {},
  setIsNewUser: () => {},
});

export const useRegistrationModal = () => useContext(RegistrationModalContext);

interface RegistrationModalProviderProps {
  children: ReactNode;
}

export const RegistrationModalProvider = ({ children }: RegistrationModalProviderProps) => {
  // Modal should be closed by default
  const [isOpen, setIsOpen] = useState(false);
  const [initialPage, setInitialPage] = useState<RegistrationPage>("main");
  const [isOpenedFromProtectedRoute, setIsOpenedFromProtectedRoute] = useState(false);
  const [onSuccessCallback, setOnSuccessCallback] = useState<((isNewUser?: boolean) => void) | null>(null);
  const [pendingIsNewUser, setPendingIsNewUser] = useState<boolean | null>(null);
  const { user } = useAuth();

  // Clean up obsolete localStorage key from previous first-time visitor logic
  useEffect(() => {
    localStorage.removeItem("hasVisitedBefore");
  }, []);

  const openModal = () => {
    setIsOpenedFromProtectedRoute(false);
    setInitialPage("main");
    setIsOpen(true);
  };

  const openModalForLogin = () => {
    setIsOpenedFromProtectedRoute(false);
    setInitialPage("login");
    setIsOpen(true);
  };

  const openForProtectedRoute = () => {
    setIsOpenedFromProtectedRoute(true);
    setInitialPage("main");
    setIsOpen(true);
  };

  const closeModal = () => {
    setIsOpen(false);
    setIsOpenedFromProtectedRoute(false);
    setInitialPage("main");
  };

  const setRegistrationSuccessCallback = (callback: (isNewUser?: boolean) => void) => {
    setOnSuccessCallback(() => callback);
  };

  const setIsNewUser = (isNewUser: boolean) => {
    setPendingIsNewUser(isNewUser);
  };

  // Trigger callback when user becomes authenticated after registration
  // Wait for pendingIsNewUser to be explicitly set to avoid race condition with Google auth
  useEffect(() => {
    if (user && onSuccessCallback && pendingIsNewUser !== null) {
      onSuccessCallback(pendingIsNewUser);
      setOnSuccessCallback(null);
      setPendingIsNewUser(null);
    }
  }, [user, onSuccessCallback, pendingIsNewUser]);



  return (
    <RegistrationModalContext.Provider 
      value={{ 
        isOpen,
        initialPage,
        openModal,
        openModalForLogin,
        closeModal,
        openForProtectedRoute,
        isOpenedFromProtectedRoute,
        setRegistrationSuccessCallback,
        setIsNewUser
      }}
    >
      {children}
    </RegistrationModalContext.Provider>
  );
};

server/features/daily-outreach/routes-st.content:
import { Request, Response, Router } from 'express';
import { db } from '../../db';
import { 
  dailyOutreachBatches, 
  dailyOutreachItems,
  userOutreachPreferences,
  companies,
  contacts,
  communicationHistory
} from '@shared/schema';
import { eq, and, gte, sql, desc, isNotNull, count } from 'drizzle-orm';
import { startOfWeek, endOfWeek, startOfMonth, endOfMonth, startOfDay, endOfDay, differenceInDays, format } from 'date-fns';
import { requireAuth } from '../../utils/auth';

const router = Router();

// Get streak statistics
router.get('/streak-stats', requireAuth, async (req: Request, res: Response) => {
  try {
    const userId = (req as any).user?.id;
    if (!userId) {
      return res.status(401).json({ error: 'Not authenticated' });
    }
    const today = new Date();
    const weekStart = startOfWeek(today, { weekStartsOn: 1 }); // Monday
    const weekEnd = endOfWeek(today, { weekStartsOn: 1 });
    const monthStart = startOfMonth(today);
    const monthEnd = endOfMonth(today);
    const todayStart = startOfDay(today);
    const todayEnd = endOfDay(today);

    // Get user preferences for weekly goal
    const [preferences] = await db
      .select()
      .from(userOutreachPreferences)
      .where(eq(userOutreachPreferences.userId, userId));

    const weeklyGoal = preferences?.scheduleDays?.length || 3;

    // Get all days with emails sent for streak calculation from CRM history
    const allEmailDays = await db
      .select({
        date: sql<string>`DATE(${communicationHistory.sentAt})`,
        itemsSent: sql<number>`count(*)`.as('itemsSent')
      })
      .from(communicationHistory)
      .where(
        and(
          eq(communicationHistory.userId, userId),
          eq(communicationHistory.channel, 'email'),
          eq(communicationHistory.direction, 'outbound'),
          isNotNull(communicationHistory.sentAt)
        )
      )
      .groupBy(sql`DATE(${communicationHistory.sentAt})`)
      .orderBy(sql`DATE(${communicationHistory.sentAt}) DESC`);

    // Calculate current streak based on email days
    let currentStreak = 0;
    let longestStreak = 0;
    let tempStreak = 0;
    let lastDate: Date | null = null;

    for (const emailDay of allEmailDays) {
      if (emailDay.itemsSent > 0 && emailDay.date) {
        const emailDate = new Date(emailDay.date);

        if (!lastDate) {
          tempStreak = 1;
          if (differenceInDays(today, emailDate) <= 1) {
            currentStreak = 1;
          }
        } else {
          const daysDiff = differenceInDays(lastDate, emailDate);

          if (daysDiff === 1) {
            tempStreak++;
            if (differenceInDays(today, emailDate) <= tempStreak) {
              currentStreak = tempStreak;
            }
          } else {
            longestStreak = Math.max(longestStreak, tempStreak);
            tempStreak = 1;
          }
        }

        lastDate = emailDate;
      }
    }
    longestStreak = Math.max(longestStreak, tempStreak);

    // Get today's batch if exists
    const [todaysBatch] = await db
      .select({
        id: dailyOutreachBatches.id,
        token: dailyOutreachBatches.secureToken,
        createdAt: dailyOutreachBatches.createdAt
      })
      .from(dailyOutreachBatches)
      .where(
        and(
          eq(dailyOutreachBatches.userId, userId),
          gte(dailyOutreachBatches.createdAt, todayStart)
        )
      )
      .orderBy(desc(dailyOutreachBatches.createdAt))
      .limit(1);

    // Get the actual item count separately if batch exists
    let itemCount = 0;
    if (todaysBatch) {
      const [countResult] = await db
        .select({ count: count() })
        .from(dailyOutreachItems)
        .where(eq(dailyOutreachItems.batchId, todaysBatch.id));

      itemCount = Number(countResult?.count || 0);

      // Add itemCount to the batch object
      (todaysBatch as any).itemCount = itemCount;

      // Fetch the actual items with contact/company details for display
      const batchItems = await db
        .select({
          contact: {
            id: contacts.id,
            name: contacts.name,
            role: contacts.role,
            email: contacts.email
          },
          company: {
            id: companies.id,
            name: companies.name
          }
        })
        .from(dailyOutreachItems)
        .innerJoin(contacts, eq(dailyOutreachItems.contactId, contacts.id))
        .innerJoin(companies, eq(dailyOutreachItems.companyId, companies.id))
        .where(eq(dailyOutreachItems.batchId, todaysBatch.id));

      // Add prospects to the batch object
      (todaysBatch as any).prospects = batchItems;
    }

    // Removed debug logging for production

    // Get available companies and contacts count
    const availableCompaniesResult = await db
      .select({ count: sql<number>`count(distinct ${companies.id})` })
      .from(companies)
      .innerJoin(contacts, eq(contacts.companyId, companies.id))
      .where(
        and(
          eq(companies.userId, userId),
          isNotNull(contacts.email)
        )
      );

    const availableContactsResult = await db
      .select({ count: sql<number>`count(*)` })
      .from(contacts)
      .innerJoin(companies, eq(companies.id, contacts.companyId))
      .where(
        and(
          eq(companies.userId, userId),
          isNotNull(contacts.email)
        )
      );

    // Get emails sent statistics from CRM history
    const emailsSentToday = await db
      .select({ count: sql<number>`count(*)` })
      .from(communicationHistory)
      .where(
        and(
          eq(communicationHistory.userId, userId),
          eq(communicationHistory.channel, 'email'),
          eq(communicationHistory.direction, 'outbound'),
          gte(communicationHistory.sentAt, todayStart),
          isNotNull(communicationHistory.sentAt)
        )
      );

    const emailsSentThisWeek = await db
      .select({ count: sql<number>`count(*)` })
      .from(communicationHistory)
      .where(
        and(
          eq(communicationHistory.userId, userId),
          eq(communicationHistory.channel, 'email'),
          eq(communicationHistory.direction, 'outbound'),
          gte(communicationHistory.sentAt, weekStart),
          isNotNull(communicationHistory.sentAt)
        )
      );

    const emailsSentThisMonth = await db
