        setMessages(prev => [...prev, errorMessage]);
        return;
      }

      const loadingMessage: Message = {
        id: Date.now().toString(),
        content: `<div class="flex items-center space-x-2"><div class="loading-spinner"></div><span>Analyzing your market scope...</span></div>`,
