import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { FileText, Edit, Save } from "lucide-react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import type { EmailTemplate } from "@shared/schema";
import MergeFieldDialog from "./merge-field-dialog";
import { MergeFieldControls } from "./merge-field-controls";

interface QuickTemplatesProps {
  templates: EmailTemplate[];
  templatesLoading: boolean;
  onSelectTemplate: (template: EmailTemplate) => void;
  onSaveTemplate?: (templateName: string) => void;
  onUpdateTemplate?: () => void;
  onMergeFieldInsert?: (mergeField: string) => void;
  onEditTemplate?: (template: EmailTemplate) => void;
  isEditMode?: boolean;
  editingTemplateId?: number | null;
  onExitEditMode?: () => void;
  isMergeViewMode?: boolean;
  onToggleMergeView?: () => void;
  isSavingTemplate?: boolean;
}

export default function QuickTemplates({ templates, templatesLoading, onSelectTemplate, onSaveTemplate, onUpdateTemplate, onMergeFieldInsert, onEditTemplate, isEditMode, editingTemplateId, onExitEditMode, isMergeViewMode, onToggleMergeView, isSavingTemplate = false }: QuickTemplatesProps) {
  const [selectedTemplateId, setSelectedTemplateId] = useState<string>();
  const [mergeFieldDialogOpen, setMergeFieldDialogOpen] = useState(false);
  const [editConfirmDialogOpen, setEditConfirmDialogOpen] = useState(false);
  const [insertConfirmDialogOpen, setInsertConfirmDialogOpen] = useState(false);
  const [saveTemplateDialogOpen, setSaveTemplateDialogOpen] = useState(false);
  const [templateName, setTemplateName] = useState("");
  const queryClient = useQueryClient();

  // Now templates and loading state come from props
  const typedTemplates = templates;

  const handleInsertTemplate = () => {
    if (!selectedTemplateId) {
      return;
    }
    setInsertConfirmDialogOpen(true);
  };

  const handleConfirmInsert = () => {
    const template = typedTemplates.find(t => t.id.toString() === selectedTemplateId);
    if (template) {
      console.log('QuickTemplates - Selected template:', { id: template.id, name: template.name });
      onSelectTemplate(template);
    }
    setInsertConfirmDialogOpen(false);
  };

  const handleEditTemplate = () => {
    if (!selectedTemplateId) {
      return;
    }
    setEditConfirmDialogOpen(true);
  };

  const handleConfirmEdit = () => {
    const template = typedTemplates.find(t => t.id.toString() === selectedTemplateId);
    if (template && onEditTemplate) {
      console.log('QuickTemplates - Loading template for editing:', { id: template.id, name: template.name });
      onEditTemplate(template);
    }
    setEditConfirmDialogOpen(false);
  };

  const handleSaveTemplate = () => {
    if (!onSaveTemplate) return;
    setTemplateName("");
    setSaveTemplateDialogOpen(true);
  };

  const handleConfirmSave = () => {
    if (!templateName.trim() || !onSaveTemplate) return;
    onSaveTemplate(templateName.trim());
    setSaveTemplateDialogOpen(false);
    setTemplateName("");
  };



  return (
    <div className="space-y-4 pt-6">
      {/* Edit Mode Notification Banner */}
      {isEditMode && (
        <div className="bg-red-50 border border-red-200 text-red-800 px-3 py-2 rounded-md text-sm mb-4">
          Edit Template Mode
        </div>
      )}

      {/* Merge View Mode Notification Banner */}
      {isMergeViewMode && !isEditMode && (
        <div className="bg-blue-50 border border-blue-200 text-blue-800 px-3 py-2 rounded-md text-sm mb-4">
          Merge View Mode - Showing technical merge fields
        </div>
      )}

      <div className="flex items-center justify-end gap-1.5 mb-4">
        <MergeFieldControls 
          isMergeViewMode={isMergeViewMode}
          onToggleMergeView={onToggleMergeView}
          onMergeFieldClick={() => setMergeFieldDialogOpen(true)}
          onSaveTemplateClick={onSaveTemplate ? handleSaveTemplate : undefined}
        />
      </div>

      <div className="space-y-2">
        <Select value={selectedTemplateId} onValueChange={setSelectedTemplateId}>
          <SelectTrigger className="h-7 text-xs text-muted-foreground">
            <SelectValue placeholder={templatesLoading ? "Loading templates..." : "Select a Template"} />
          </SelectTrigger>
          <SelectContent>
            {typedTemplates.map((template) => (
              <SelectItem 
                key={template.id} 
                value={template.id.toString()}
                className="pl-3 text-xs"
              >
                {template.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <div className="flex justify-end gap-1.5">
          <Button 
            variant="secondary"
            onClick={handleInsertTemplate} 
            disabled={!selectedTemplateId}
            className="h-7 px-2.5 text-xs text-muted-foreground hover:text-foreground mr-1 hover:scale-105 transition-all duration-300 ease-out"
          >
            <FileText className="w-3 h-3 mr-0.5" />
            Insert Template
          </Button>
          <Button 
            variant="secondary"
            onClick={isEditMode ? () => onUpdateTemplate?.() : handleEditTemplate} 
            disabled={!selectedTemplateId || isSavingTemplate}
            className="h-7 px-2.5 text-xs text-muted-foreground hover:text-foreground mr-1 hover:scale-105 transition-all duration-300 ease-out"
          >
            {isEditMode ? (
              isSavingTemplate ? (
                <>
                  <Save className="w-3 h-3 mr-0.5 animate-pulse" />
                  Saving...
                </>
              ) : (
                <>
                  <Save className="w-3 h-3 mr-0.5" />
                  Save Template
                </>
              )
            ) : (
              <>
                <Edit className="w-3 h-3 mr-0.5" />
                Edit Template
              </>
            )}
          </Button>
        </div>
      </div>

      <MergeFieldDialog 
        open={mergeFieldDialogOpen} 
        onOpenChange={setMergeFieldDialogOpen}
        onMergeFieldInsert={onMergeFieldInsert}
      />

      <AlertDialog open={editConfirmDialogOpen} onOpenChange={setEditConfirmDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Edit Template</AlertDialogTitle>
            <AlertDialogDescription>
              Editing this template, will replace all content currently in fields on this page.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setEditConfirmDialogOpen(false)}>
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmEdit}>
              Load the Template
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={insertConfirmDialogOpen} onOpenChange={setInsertConfirmDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Load Template</AlertDialogTitle>
            <AlertDialogDescription>
              Loading this template, will replace all content currently in fields on this page.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setInsertConfirmDialogOpen(false)}>
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmInsert}>
              Load the Template
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <Dialog open={saveTemplateDialogOpen} onOpenChange={setSaveTemplateDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Save as Template</DialogTitle>
            <DialogDescription>
              Enter name of new template:
            </DialogDescription>
          </DialogHeader>
          <div className="py-4">
            <Input
              placeholder="Sales Genius 2027"
              value={templateName}
              onChange={(e) => setTemplateName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && templateName.trim()) {
                  handleConfirmSave();
                }
              }}
              className="w-full"
            />
          </div>
          <DialogFooter>
            <Button 
              variant="outline" 
              onClick={() => setSaveTemplateDialogOpen(false)}
            >
              Cancel
            </Button>
            <Button 
              onClick={handleConfirmSave}
              disabled={!templateName.trim()}
            >
              Save Template
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

server/search/services/contact-search-se.content:
/**
 * ContactSearchService - Centralized, stateless contact search service
 * 
 * This service provides a single source of truth for all contact searches,
 * ensuring consistent behavior whether triggered from browser, API, or cron jobs.
 * All contact searches go through the job queue for resilience.
 */

import { findKeyDecisionMakers } from "../contacts/finder";
import { storage } from "../../storage";
import type { Contact, Company } from "@shared/schema";
import type { ContactSearchConfig } from "../types";
import { processBatch } from "../utils/batch-processing";

export interface ContactSearchParams {
  companies: Company[];
  userId: number;
  searchConfig: ContactSearchConfig;
  jobId?: string;
  onProgress?: (message: string, phase: string) => Promise<void>;
}

export interface ContactSearchResult {
  companyId: number;
  companyName: string;
  contacts: Contact[];
  searchedAt: Date;
  config: ContactSearchConfig;
}

export class ContactSearchService {
  /**
   * Save contacts for a company with deduplication
   * Extracted method to simplify the main search logic
   */
  private static async saveContactsForCompany(
    company: Company,
    contacts: any[],
    userId: number,
    jobId?: string
  ): Promise<Contact[]> {
    const savedContacts: Contact[] = [];

    // Fetch all existing contacts for the company once (batch optimization)
    const existingContacts = await storage.listContactsByCompany(company.id, userId);

    // Create lookup maps for faster deduplication
    const existingByEmail = new Map(
      existingContacts
        .filter(c => c.email)
        .map(c => [c.email!.toLowerCase(), c])
    );
    const existingByName = new Map(
      existingContacts
        .filter(c => c.name)
        .map(c => [c.name.toLowerCase(), c])
    );

    for (const contactData of contacts) {
      try {
        let existingContact = null;

        // First check by email if available (now using Map lookup - O(1) instead of O(n))
        if (contactData.email) {
          existingContact = existingByEmail.get(contactData.email.toLowerCase());
        }

        // If no email match, check by name (case-insensitive)
        if (!existingContact && contactData.name) {
          existingContact = existingByName.get(contactData.name.toLowerCase());
        }

        if (existingContact) {
          // Update existing contact instead of creating duplicate
          console.log(`[ContactSearchService] Updating existing contact: ${existingContact.name}`);

          // Merge new data with existing (prefer new data if available)
          const updateData: any = {
            ...contactData,
            // Preserve existing data if new data is null/undefined
            email: contactData.email || existingContact.email,
            role: contactData.role || existingContact.role,
            linkedinUrl: contactData.linkedinUrl || existingContact.linkedinUrl,
            phoneNumber: contactData.phoneNumber || existingContact.phoneNumber,
            lastValidated: new Date()
          };

          // Add jobId to completedSearches if not already present
          if (jobId) {
            const completedSearches = existingContact.completedSearches || [];
            if (!completedSearches.includes(jobId)) {
              completedSearches.push(jobId);
              updateData.completedSearches = completedSearches;
            }
          }

          const updatedContact = await storage.updateContact(existingContact.id, updateData);
          savedContacts.push(updatedContact);

        } else {
          // Create new contact
          console.log(`[ContactSearchService] Creating new contact: ${contactData.name}`);

          const contact = await storage.createContact({
            ...contactData,
            companyId: company.id,
            userId: userId,
            // Add job tracking metadata
            completedSearches: jobId ? [jobId] : [],
            lastValidated: new Date()
          } as any);

          savedContacts.push(contact);
        }
      } catch (error) {
        console.error(`[ContactSearchService] Error saving/updating contact:`, error);
      }
    }

    return savedContacts;
  }

  /**
   * Process a single company for contact search
   * Extracted method for batch processing
   */
  private static async processCompanyForContacts(
    company: Company,
    params: {
      userId: number;
      searchConfig: ContactSearchConfig;
      jobId?: string;
      onProgress?: (message: string, phase: string) => Promise<void>;
    }
  ): Promise<ContactSearchResult> {
    const { userId, searchConfig, jobId } = params;

    try {
      // Search for contacts using the centralized finder
      const searchQuery = `${company.name} ${company.website || ''}`.trim();
      const contacts = await findKeyDecisionMakers(searchQuery, searchConfig);

      console.log(`[ContactSearchService] Found ${contacts.length} contacts for ${company.name}`);

      // Save contacts with deduplication
      const savedContacts = await this.saveContactsForCompany(
        company, 
        contacts, 
        userId, 
        jobId
      );

      return {
        companyId: company.id,
        companyName: company.name,
        contacts: savedContacts,
        searchedAt: new Date(),
        config: searchConfig
      };

    } catch (error) {
      console.error(`[ContactSearchService] Error searching contacts for ${company.name}:`, error);

      // Return empty result on error
      return {
        companyId: company.id,
        companyName: company.name,
        contacts: [],
        searchedAt: new Date(),
        config: searchConfig
      };
    }
  }

  /**
   * Search for contacts across multiple companies
   * This is the single entry point for all contact searches
   * Now using batch parallelization for better performance
   */
  static async searchContacts(params: ContactSearchParams): Promise<ContactSearchResult[]> {
    const { companies, userId, searchConfig, jobId, onProgress } = params;

    console.log(`[ContactSearchService] Starting batch contact search for ${companies.length} companies`);
    console.log(`[ContactSearchService] Config:`, searchConfig);
    console.log(`[ContactSearchService] Processing in batches of up to 7 companies concurrently`);

    // Report initial progress
    if (onProgress) {
      await onProgress(
        `Starting batch search for ${companies.length} companies`,
        'contacts'
      );
    }

    // Process companies in parallel batches of 3 (optimal for Perplexity API performance)
    const results = await processBatch(
      companies,
      async (company) => {
        const result = await this.processCompanyForContacts(company, {
          userId,
          searchConfig,
          jobId,
          onProgress
        });

        // Report progress for each company
        if (onProgress) {
          await onProgress(
            `Processed ${company.name} - Found ${result.contacts.length} contacts`,
            'contacts'
          );
        }

        return result;
      },
      7 // Process up to 7 companies concurrently for optimal performance
    );

    console.log(`[ContactSearchService] Completed batch search: ${results.length} companies processed`);
    return results;
  }

  /**
   * Search contacts for a single company
   * Convenience method that wraps searchContacts
   */
  static async searchCompanyContacts(
    company: Company,
    userId: number,
    searchConfig: ContactSearchConfig,
    jobId?: string
  ): Promise<ContactSearchResult> {
    const results = await this.searchContacts({
      companies: [company],
      userId,
      searchConfig,
      jobId
    });

    return results[0];
  }

  /**
   * Validate contact search configuration
   * Ensures config has valid settings before processing
   */
  static validateSearchConfig(config: ContactSearchConfig): boolean {
    // At least one search type must be enabled
    const hasEnabledSearch = 
      config.enableCoreLeadership ||
      config.enableDepartmentHeads ||
      config.enableMiddleManagement ||
      config.enableCustomSearch ||
      config.enableCustomSearch2;

    if (!hasEnabledSearch) {
      console.warn('[ContactSearchService] No search types enabled in config');
      return false;
    }

    // If custom search is enabled, must have target
    if (config.enableCustomSearch && !config.customSearchTarget) {
      console.warn('[ContactSearchService] Custom search enabled but no target specified');
      return false;
    }

    if (config.enableCustomSearch2 && !config.customSearchTarget2) {
      console.warn('[ContactSearchService] Custom search 2 enabled but no target specified');
      return false;
    }

    return true;
  }

  /**
   * Get default contact search configuration
   * Used when no specific config is provided
   */
  static getDefaultConfig(): ContactSearchConfig {
    return {
      enableCoreLeadership: true,
      enableDepartmentHeads: false,
      enableMiddleManagement: false,
      enableCustomSearch: false,
      customSearchTarget: undefined,
      enableCustomSearch2: false,
      customSearchTarget2: undefined
    };
  }

  /**
   * Merge user config with defaults
   * Ensures all required fields are present
   */
  static mergeWithDefaults(userConfig?: Partial<ContactSearchConfig>): ContactSearchConfig {
    return {
      ...this.getDefaultConfig(),
      ...userConfig
    };
  }

  /**
   * Check if contacts already exist for companies
   * Helps avoid duplicate searches
   */
  static async hasExistingContacts(
    companyIds: number[],
    userId: number
  ): Promise<Map<number, boolean>> {
    const result = new Map<number, boolean>();

    for (const companyId of companyIds) {
      const contacts = await storage.listContactsByCompany(companyId, userId);
      result.set(companyId, contacts.length > 0);
    }

    return result;
  }

  /**
   * Get contact search statistics for a user
   * Useful for analytics and rate limiting
   */
  static async getUserSearchStats(userId: number): Promise<{
    totalSearches: number;
    contactsFound: number;
    companiesSearched: number;
    lastSearchDate: Date | null;
  }> {
    const contacts = await storage.listContacts(userId);
    const companies = await storage.listCompanies(userId);

    // Find unique companies that have contacts
    const companiesWithContacts = new Set(
      contacts.map(c => c.companyId).filter(id => id)
    );

    // Find most recent contact
    const lastContact = contacts.sort(
      (a, b) => (b.createdAt?.getTime() || 0) - (a.createdAt?.getTime() || 0)
    )[0];

    return {
      totalSearches: contacts.filter(c => c.completedSearches && c.completedSearches.length > 0).length,
      contactsFound: contacts.length,
      companiesSearched: companiesWithContacts.size,
      lastSearchDate: lastContact?.createdAt || null
    };
  }
}

