            <LandingSimple />
          </Suspense>
        } />
        <Route path="/simple" component={() => 
          <Suspense fallback={null}>
            <LandingSimple />
          </Suspense>
        } />

        {/* Simple Landing Page Variant 2 (A/B testing) */}
        <Route path="/landing-simple2" component={() => 
