                }
                ${config.enableMiddleManagement 
                  ? 'bg-secondary text-secondary-foreground hover:bg-secondary-hover'
                  : 'bg-muted text-muted-foreground hover:bg-muted-hover'
                }
                ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
