                            </TableCell>
                            <TableCell className="font-medium py-3">
                              <div className="flex flex-col">
                                <div className="font-semibold flex items-center gap-1.5">
                                  {list.isDefault && <Target className="h-4 w-4 text-primary" />}
                                  {list.name}
                                </div>
                                {list.description && (
                                  <div className="text-xs text-muted-foreground mt-1">
                                    {list.description}
                                  </div>
                                )}
                              </div>
                            </TableCell>
                            <TableCell className="hidden md:table-cell py-3">
                              <Badge variant="secondary" className="font-normal">
                                <Users className="h-3 w-3 mr-1" />
                                {list.contactCount || 0}
                              </Badge>
                            </TableCell>
                            <TableCell className="hidden md:table-cell py-3">
                              <TooltipProvider>
                                <Tooltip>
                                  <TooltipTrigger>
                                    <Badge variant="outline" className="font-normal">
                                      <Target className="h-3 w-3 mr-1" />
                                      0 active
                                    </Badge>
                                  </TooltipTrigger>
                                  <TooltipContent>
                                    <p>No active campaigns for this list</p>
                                  </TooltipContent>
                                </Tooltip>
                              </TooltipProvider>
                            </TableCell>
                            <TableCell className="py-3">
                              <div className="text-sm text-muted-foreground">
                                {list.createdAt
                                  ? format(new Date(list.createdAt), "MMM d, yyyy 'at' h:mm a")
                                  : "—"}
                              </div>
                            </TableCell>
                            <TableCell className="text-right py-3">
                              <DropdownMenu>
                                <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                                  <Button
                                    variant="ghost"
                                    size="sm"
                                    className="h-8 w-8 p-0"
                                  >
                                    <MoreHorizontal className="h-4 w-4" />
                                  </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end" onClick={(e) => e.stopPropagation()}>
                                  <DropdownMenuItem
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      handleEditList(list);
                                    }}
                                  >
                                    <Edit className="h-4 w-4 mr-2" />
                                    Edit
                                  </DropdownMenuItem>
                                  <DropdownMenuItem
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      toast({
                                        title: "Coming Soon",
                                        description: "Campaign creation will be available soon",
                                      });
                                    }}
                                  >
                                    <Mail className="h-4 w-4 mr-2" />
                                    Create Campaign
                                  </DropdownMenuItem>
                                  <DropdownMenuItem
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      toast({
                                        title: "Coming Soon",
                                        description: "List duplication will be available soon",
                                      });
                                    }}
                                  >
                                    <Copy className="h-4 w-4 mr-2" />
                                    Duplicate
                                  </DropdownMenuItem>
                                  <DropdownMenuItem
                                    onClick={(e) => handleDownloadCSV(e, list.id, list.name)}
                                  >
                                    <Download className="h-4 w-4 mr-2" />
                                    Download CSV
                                  </DropdownMenuItem>
                                  <DropdownMenuItem
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      toast({
                                        title: "Coming Soon",
                                        description: "List archiving will be available soon",
                                      });
                                    }}
                                  >
                                    <Archive className="h-4 w-4 mr-2" />
                                    Archive
                                  </DropdownMenuItem>
                                  {!list.isDefault && (
                                    <>
                                      <DropdownMenuSeparator />
                                      <DropdownMenuItem
                                        className="text-red-600"
                                        onClick={(e) => handleDeleteList(e, list.id, list.name)}
                                        data-testid={`button-delete-list-${list.id}`}
                                      >
                                        <Trash2 className="h-4 w-4 mr-2" />
                                        Delete
                                      </DropdownMenuItem>
                                    </>
                                  )}
                                </DropdownMenuContent>
                              </DropdownMenu>
                            </TableCell>
                          </TableRow>
                        ))
                      ) : (
                        <TableRow>
                          <TableCell colSpan={6} className="h-24 text-center">
                            <div className="text-muted-foreground">
                              <p>No lists yet</p>
                              <p className="text-sm mt-1">
                                Click "New list" to create your first contact list
                              </p>
                            </div>
                          </TableCell>
                        </TableRow>
                      )}
                    </TableBody>
                  </Table>
                </div>
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex items-center justify-between px-6 py-4 border-t">
                  <div className="text-sm text-muted-foreground">
                    Viewing {startIndex + 1}—
                    {Math.min(endIndex, contactLists.length)} over{" "}
                    {contactLists.length} results
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={handlePreviousPage}
                      disabled={currentPage === 1}
                      data-testid="button-previous-page"
                    >
                      <ChevronLeft className="w-4 h-4 mr-1" />
                      Previous
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={handleNextPage}
                      disabled={currentPage === totalPages}
                      data-testid="button-next-page"
                    >
                      Next
                      <ChevronRight className="w-4 h-4 ml-1" />
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}
        </Card>
      </div>

      {/* Contact List Modal - Create/Edit */}
      <ContactListModal 
        open={listModalOpen} 
        onOpenChange={handleCloseListModal}
        list={editingList}
      />
    </>
  );
}

