  // Query all contacts for "Add Manually" method
  const { data: allContactsData } = useQuery<{ total: number; contacts: (Contact & { companyName?: string })[] }>({
    queryKey: ["/api/contacts"],
    enabled: !!user && addMethod === 'manual',
