import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { 
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Card, CardContent } from "@/components/ui/card";
import { 
  Users, 
  Search, 
  ListPlus,
  FolderOpen,
  CheckCircle2
} from "lucide-react";
import { useQuery } from "@tanstack/react-query";
import type { ContactList, SearchList } from "@shared/schema";

interface CampaignRecipientsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  currentListId?: number | null;
  currentSearchQuery?: string | null;
  onConfirm: (selection: RecipientSelection) => void;
}

export type RecipientSelection = 
  | { type: 'current'; listId: number | null; query: string | null }
  | { type: 'multiple'; searchListIds: number[] }
  | { type: 'existing'; contactListId: number };

export function CampaignRecipientsDialog({
  open,
  onOpenChange,
  currentListId,
  currentSearchQuery,
  onConfirm
}: CampaignRecipientsDialogProps) {
  const [selectionMode, setSelectionMode] = useState<'current' | 'multiple' | 'existing'>('current');
  const [selectedSearchLists, setSelectedSearchLists] = useState<Set<number>>(new Set());
  const [selectedContactList, setSelectedContactList] = useState<number | null>(null);

  // Fetch search lists
  const { data: searchLists = [] } = useQuery<SearchList[]>({
    queryKey: ['/api/lists'],
    enabled: open && selectionMode === 'multiple'
  });

  // Fetch contact lists
  const { data: contactLists = [] } = useQuery<ContactList[]>({
    queryKey: ['/api/contact-lists'],
    enabled: open && selectionMode === 'existing'
  });

  const handleSearchListToggle = (listId: number) => {
    setSelectedSearchLists(prev => {
      const newSet = new Set(prev);
      if (newSet.has(listId)) {
        newSet.delete(listId);
      } else {
        newSet.add(listId);
      }
      return newSet;
    });
  };

  const handleConfirm = () => {
    let selection: RecipientSelection | null = null;

    switch (selectionMode) {
      case 'current':
        selection = {
          type: 'current',
          listId: currentListId || null,
          query: currentSearchQuery || null
        };
        break;
      case 'multiple':
        if (selectedSearchLists.size > 0) {
          selection = {
            type: 'multiple',
            searchListIds: Array.from(selectedSearchLists)
          };
        }
        break;
      case 'existing':
        if (selectedContactList) {
          selection = {
            type: 'existing',
            contactListId: selectedContactList
          };
        }
        break;
    }

    if (selection) {
      onConfirm(selection);
      onOpenChange(false);
    }
  };

  const isConfirmDisabled = () => {
    switch (selectionMode) {
      case 'current':
        return !currentListId && !currentSearchQuery;
      case 'multiple':
        return selectedSearchLists.size === 0;
      case 'existing':
        return !selectedContactList;
      default:
        return true;
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px]">
        <DialogHeader>
          <DialogTitle>Select Campaign Recipients</DialogTitle>
          <DialogDescription>
            Choose how you want to target recipients for this campaign
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <RadioGroup value={selectionMode} onValueChange={(value: any) => setSelectionMode(value)}>
            {/* Current Search Results Option */}
            <Card className={selectionMode === 'current' ? 'border-primary' : ''}>
              <CardContent className="p-4">
                <div className="flex items-start space-x-3">
                  <RadioGroupItem value="current" id="current" className="mt-1" />
                  <div className="flex-1">
                    <Label htmlFor="current" className="cursor-pointer">
                      <div className="flex items-center gap-2 font-medium">
                        <Search className="h-4 w-4" />
                        Current Search Results
                      </div>
                      <p className="text-sm text-muted-foreground mt-1">
                        {currentSearchQuery 
                          ? `Use contacts from: "${currentSearchQuery}"`
                          : "No active search (will create empty campaign)"
                        }
                      </p>
                      {currentListId && (
                        <p className="text-xs text-muted-foreground mt-1">
                          List ID: {currentListId}
                        </p>
                      )}
                    </Label>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Multiple Search Lists Option */}
            <Card className={selectionMode === 'multiple' ? 'border-primary' : ''}>
              <CardContent className="p-4">
                <div className="flex items-start space-x-3">
                  <RadioGroupItem value="multiple" id="multiple" className="mt-1" />
                  <div className="flex-1">
                    <Label htmlFor="multiple" className="cursor-pointer">
                      <div className="flex items-center gap-2 font-medium">
                        <ListPlus className="h-4 w-4" />
                        Include Multiple Search Lists
                      </div>
                      <p className="text-sm text-muted-foreground mt-1">
                        Combine contacts from multiple search results
                      </p>
                    </Label>

                    {selectionMode === 'multiple' && searchLists.length > 0 && (
                      <ScrollArea className="h-[200px] mt-3 border rounded-md p-3">
                        <div className="space-y-2">
                          {searchLists.map((list) => (
                            <div key={list.id} className="flex items-center space-x-2">
                              <Checkbox
                                id={`list-${list.id}`}
                                checked={selectedSearchLists.has(list.id)}
                                onCheckedChange={() => handleSearchListToggle(list.id)}
                              />
                              <Label 
                                htmlFor={`list-${list.id}`}
                                className="text-sm cursor-pointer flex-1"
                              >
                                <div>{list.prompt}</div>
                                <div className="text-xs text-muted-foreground">
                                  {list.resultCount} companies • Created {new Date(list.createdAt!).toLocaleDateString()}
                                </div>
                              </Label>
                            </div>
                          ))}
                        </div>
                      </ScrollArea>
                    )}

                    {selectionMode === 'multiple' && searchLists.length === 0 && (
                      <p className="text-sm text-muted-foreground mt-3 italic">
                        No search lists available
                      </p>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Existing Contact List Option */}
            <Card className={selectionMode === 'existing' ? 'border-primary' : ''}>
              <CardContent className="p-4">
                <div className="flex items-start space-x-3">
                  <RadioGroupItem value="existing" id="existing" className="mt-1" />
                  <div className="flex-1">
                    <Label htmlFor="existing" className="cursor-pointer">
                      <div className="flex items-center gap-2 font-medium">
                        <FolderOpen className="h-4 w-4" />
                        Use Existing Contact List
                      </div>
                      <p className="text-sm text-muted-foreground mt-1">
                        Select from your saved contact lists
                      </p>
                    </Label>

                    {selectionMode === 'existing' && contactLists.length > 0 && (
                      <Select
                        value={selectedContactList?.toString()}
                        onValueChange={(value) => setSelectedContactList(parseInt(value))}
                      >
                        <SelectTrigger className="mt-3">
                          <SelectValue placeholder="Select a contact list" />
                        </SelectTrigger>
                        <SelectContent>
                          {contactLists.map((list) => (
                            <SelectItem key={list.id} value={list.id.toString()}>
                              <div>
                                <div>{list.name}</div>
                                <div className="text-xs text-muted-foreground">
                                  {list.contactCount} contacts
                                </div>
                              </div>
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}

                    {selectionMode === 'existing' && contactLists.length === 0 && (
                      <p className="text-sm text-muted-foreground mt-3 italic">
                        No contact lists available
                      </p>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          </RadioGroup>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button 
            onClick={handleConfirm}
            disabled={isConfirmDisabled()}
            className="bg-pink-500 hover:bg-pink-600 text-white"
          >
            <CheckCircle2 className="mr-2 h-4 w-4" />
            Confirm Selection
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/recipient-selectio.content:
import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Users, Search, FolderOpen, Plus } from "lucide-react";
import { useQuery } from "@tanstack/react-query";
import type { SearchList, ContactList } from "@shared/schema";
import { cn } from "@/lib/utils";

interface RecipientSelectionModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  currentListId: number | null;
  currentQuery: string | null;
  onSelect: (selection: RecipientSelection) => void;
}

export type RecipientSelection = 
  | { type: 'current'; listId: number; query: string }
  | { type: 'multiple'; searchListIds: number[]; targetAudienceQuery?: string }
  | { type: 'existing'; contactListId: number; contactListName: string };

export function RecipientSelectionModal({
  open,
  onOpenChange,
  currentListId,
  currentQuery,
  onSelect,
}: RecipientSelectionModalProps) {
  const [selectionType, setSelectionType] = useState<'current' | 'multiple' | 'existing'>('current');
  const [selectedSearchLists, setSelectedSearchLists] = useState<Set<number>>(new Set());
  const [selectedContactList, setSelectedContactList] = useState<string>("");

  // Fetch search lists
  const { data: searchLists = [] } = useQuery<SearchList[]>({
    queryKey: ['/api/lists'],
    enabled: open && selectionType === 'multiple',
  });

  // Fetch contact lists
  const { data: contactLists = [] } = useQuery<ContactList[]>({
    queryKey: ['/api/contact-lists'],
    enabled: open && selectionType === 'existing',
  });

  const handleSelectSearchList = (listId: number) => {
    const newSet = new Set(selectedSearchLists);
    if (newSet.has(listId)) {
      newSet.delete(listId);
    } else {
      newSet.add(listId);
    }
    setSelectedSearchLists(newSet);
  };

  const handleConfirm = () => {
    if (selectionType === 'current' && currentListId && currentQuery) {
      onSelect({ type: 'current', listId: currentListId, query: currentQuery });
    } else if (selectionType === 'multiple' && selectedSearchLists.size > 0) {
      const selectedIds = Array.from(selectedSearchLists);
      const firstList = searchLists.find(l => l.listId === selectedIds[0]);
      onSelect({ 
        type: 'multiple', 
        searchListIds: selectedIds,
        targetAudienceQuery: firstList?.prompt
      });
    } else if (selectionType === 'existing' && selectedContactList) {
      const selected = contactLists.find(cl => cl.id.toString() === selectedContactList);
      if (selected) {
        onSelect({ 
          type: 'existing', 
          contactListId: selected.id, 
          contactListName: selected.name 
        });
      }
    }
    onOpenChange(false);
  };

  const isConfirmDisabled = 
    (selectionType === 'current' && (!currentListId || !currentQuery)) ||
    (selectionType === 'multiple' && selectedSearchLists.size === 0) ||
    (selectionType === 'existing' && !selectedContactList);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Select Campaign Recipients</DialogTitle>
          <DialogDescription>
            Choose how you want to select recipients for this campaign
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* Option 1: Current Search Results */}
          <button
            onClick={() => setSelectionType('current')}
            className={cn(
              "w-full text-left p-4 rounded-lg border-2 transition-all",
              selectionType === 'current'
                ? "border-primary bg-primary/5"
                : "border-border hover:border-muted-foreground/50"
            )}
            disabled={!currentListId || !currentQuery}
          >
            <div className="flex items-start gap-3">
              <Search className="h-5 w-5 mt-0.5 text-muted-foreground" />
              <div className="flex-1">
                <div className="font-medium">Current Search Results</div>
                {currentQuery ? (
                  <div className="text-sm text-muted-foreground mt-1">
                    "{currentQuery}"
                  </div>
                ) : (
                  <div className="text-sm text-muted-foreground mt-1">
                    No active search available
                  </div>
                )}
                <div className="text-xs text-muted-foreground mt-2">
                  This will create a new contact list from your current search
                </div>
              </div>
            </div>
          </button>

          {/* Option 2: Multiple Search Lists */}
          <button
            onClick={() => setSelectionType('multiple')}
            className={cn(
              "w-full text-left p-4 rounded-lg border-2 transition-all",
              selectionType === 'multiple'
                ? "border-primary bg-primary/5"
                : "border-border hover:border-muted-foreground/50"
            )}
          >
            <div className="flex items-start gap-3">
              <FolderOpen className="h-5 w-5 mt-0.5 text-muted-foreground" />
              <div className="flex-1">
                <div className="font-medium">Include Multiple Search Lists</div>
                <div className="text-xs text-muted-foreground mt-2">
                  Combine contacts from multiple saved searches
                </div>
              </div>
            </div>

            {selectionType === 'multiple' && searchLists.length > 0 && (
              <div onClick={(e) => e.stopPropagation()}>
                <ScrollArea className="h-48 mt-3 border rounded-md p-2">
                  {searchLists.map((list) => (
                    <div
                      key={list.id}
                      className="flex items-center space-x-2 p-2 hover:bg-muted rounded"
                    >
                      <Checkbox
                        id={`list-${list.id}`}
                        checked={selectedSearchLists.has(list.listId)}
                        onCheckedChange={() => handleSelectSearchList(list.listId)}
                      />
                      <label
                        htmlFor={`list-${list.id}`}
                        className="flex-1 text-sm cursor-pointer"
                      >
                        <div className="font-medium">{list.prompt}</div>
                        <div className="text-xs text-muted-foreground">
                          {list.resultCount} companies • ID: {list.listId}
                        </div>
                      </label>
                    </div>
                  ))}
                </ScrollArea>
              </div>
            )}
          </button>

          {/* Option 3: Existing Contact List */}
          <button
            onClick={() => setSelectionType('existing')}
            className={cn(
              "w-full text-left p-4 rounded-lg border-2 transition-all",
              selectionType === 'existing'
                ? "border-primary bg-primary/5"
                : "border-border hover:border-muted-foreground/50"
            )}
          >
            <div className="flex items-start gap-3">
              <Users className="h-5 w-5 mt-0.5 text-muted-foreground" />
              <div className="flex-1">
                <div className="font-medium">Use Existing Contact List</div>
                <div className="text-xs text-muted-foreground mt-2">
                  Select from your saved contact lists
                </div>
              </div>
            </div>

            {selectionType === 'existing' && (
              <div className="mt-3" onClick={(e) => e.stopPropagation()}>
                <Select
                  value={selectedContactList}
                  onValueChange={setSelectedContactList}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Choose a contact list" />
                  </SelectTrigger>
                  <SelectContent>
                    {contactLists.map((list) => (
                      <SelectItem key={list.id} value={list.id.toString()}>
                        <div className="flex items-center justify-between w-full">
                          <span>{list.name}</span>
                          <span className="text-xs text-muted-foreground ml-2">
                            {list.contactCount} contacts
                          </span>
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
          </button>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleConfirm} disabled={isConfirmDisabled}>
            <Plus className="h-4 w-4 mr-2" />
            Create Campaign
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/onboarding/ICPGene.content:
import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Users, Sparkles, Building2, Target, Briefcase, MapPin, Edit, Check } from "lucide-react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import type { Company, StrategicProfile } from "@shared/schema";

interface ICPGenerationModalProps {
  open: boolean;
  productId: number | null;
  searchQuery: string;
  searchResults: Company[];
  onComplete: (icpId: number) => void;
  onBack: () => void;
  onClose: () => void;
}

interface ICPData {
  label: string;
  targetDescription: string;
  industries: string[];
  roles: string[];
  locations: string[];
  companySizes: string[];
  painPoints: string[];
  searchPrompts: string[];
}

export function ICPGenerationModal({
  open,
  productId,
  searchQuery,
  searchResults,
  onComplete,
  onBack,
  onClose
}: ICPGenerationModalProps) {
  const { toast } = useToast();
  const [isEditing, setIsEditing] = useState(false);
  const [icpData, setICPData] = useState<ICPData | null>(null);
  const [editedData, setEditedData] = useState<ICPData | null>(null);

  // Fetch the product details
  const { data: product } = useQuery<StrategicProfile>({
    queryKey: [`/api/strategic-profiles/${productId}`],
    enabled: !!productId && open
  });

  // Generate ICP from search context
  const generateICP = useMutation({
    mutationFn: async () => {
      const res = await apiRequest('POST', '/api/onboarding/generate-icp', {
        productId,
        searchQuery,
        searchResults: searchResults.slice(0, 10).map(c => ({
          name: c.name,
          description: c.description,
          size: c.size,
          website: c.website
        }))
      });
      return res.json();
    },
    onSuccess: (data) => {
      setICPData(data.icp);
      setEditedData(data.icp);
      toast({
        title: "ICP Generated!",
        description: "Review and customize your ideal customer profile."
      });
    },
    onError: (error) => {
      toast({
        title: "Generation failed",
        description: error instanceof Error ? error.message : 'Please try again',
        variant: "destructive"
      });
    }
  });

  // Save ICP as customer profile
  const saveICP = useMutation({
    mutationFn: async (data: ICPData) => {
      const res = await apiRequest('POST', '/api/customer-profiles', data);
      return res.json();
    },
    onSuccess: (data) => {
      toast({
        title: "Customer profile saved!",
        description: "Your ideal customer profile is ready."
      });
      queryClient.invalidateQueries({ queryKey: ['/api/customer-profiles'] });
      onComplete(data.id);
    },
    onError: (error) => {
      toast({
        title: "Failed to save",
        description: error instanceof Error ? error.message : 'Please try again',
        variant: "destructive"
      });
    }
  });

  useEffect(() => {
    if (open && productId && !icpData) {
      generateICP.mutate();
    }
  }, [open, productId]);

  const handleEdit = () => {
    setIsEditing(true);
  };

  const handleSaveEdit = () => {
    setICPData(editedData);
    setIsEditing(false);
  };

  const handleCancelEdit = () => {
    setEditedData(icpData);
    setIsEditing(false);
  };

  const handleConfirm = () => {
    if (icpData) {
      saveICP.mutate(icpData);
    }
  };

  const updateField = (field: keyof ICPData, value: any) => {
    if (editedData) {
      setEditedData({ ...editedData, [field]: value });
    }
  };

  const renderICPPreview = () => {
    if (!icpData) return null;

    return (
      <div className="space-y-4">
        <Card className="p-4">
          <div className="flex items-start justify-between mb-3">
            <div>
              <h4 className="font-medium">{icpData.label}</h4>
              <p className="text-sm text-muted-foreground mt-1">
                {icpData.targetDescription}
              </p>
            </div>
            {!isEditing && (
              <Button
                variant="ghost"
                size="sm"
                onClick={handleEdit}
                data-testid="button-edit-icp"
              >
                <Edit className="h-4 w-4" />
              </Button>
            )}
          </div>

          <div className="space-y-3">
            {/* Industries */}
            <div className="flex items-start gap-2">
              <Building2 className="h-4 w-4 text-muted-foreground mt-0.5" />
              <div className="flex-1">
                <p className="text-xs font-medium text-muted-foreground mb-1">Industries</p>
                <div className="flex flex-wrap gap-1">
                  {icpData.industries.map((industry, i) => (
                    <Badge key={i} variant="secondary" className="text-xs">
                      {industry}
                    </Badge>
                  ))}
                </div>
              </div>
            </div>

            {/* Roles */}
            <div className="flex items-start gap-2">
              <Briefcase className="h-4 w-4 text-muted-foreground mt-0.5" />
              <div className="flex-1">
                <p className="text-xs font-medium text-muted-foreground mb-1">Decision Makers</p>
                <div className="flex flex-wrap gap-1">
                  {icpData.roles.map((role, i) => (
                    <Badge key={i} variant="secondary" className="text-xs">
                      {role}
                    </Badge>
                  ))}
                </div>
              </div>
            </div>

            {/* Company Size */}
            <div className="flex items-start gap-2">
              <Users className="h-4 w-4 text-muted-foreground mt-0.5" />
              <div className="flex-1">
                <p className="text-xs font-medium text-muted-foreground mb-1">Company Size</p>
                <div className="flex flex-wrap gap-1">
                  {icpData.companySizes.map((size, i) => (
                    <Badge key={i} variant="secondary" className="text-xs">
                      {size}
                    </Badge>
                  ))}
                </div>
              </div>
            </div>

            {/* Locations */}
            {icpData.locations.length > 0 && (
              <div className="flex items-start gap-2">
                <MapPin className="h-4 w-4 text-muted-foreground mt-0.5" />
                <div className="flex-1">
                  <p className="text-xs font-medium text-muted-foreground mb-1">Locations</p>
                  <div className="flex flex-wrap gap-1">
                    {icpData.locations.map((location, i) => (
                      <Badge key={i} variant="secondary" className="text-xs">
                        {location}
                      </Badge>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Pain Points */}
            <div className="flex items-start gap-2">
              <Target className="h-4 w-4 text-muted-foreground mt-0.5" />
              <div className="flex-1">
                <p className="text-xs font-medium text-muted-foreground mb-1">Key Pain Points</p>
                <ul className="text-sm space-y-1">
                  {icpData.painPoints.map((point, i) => (
                    <li key={i} className="flex items-start">
                      <span className="text-muted-foreground mr-2">•</span>
                      <span className="text-sm">{point}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        </Card>
      </div>
    );
  };

  const renderEditForm = () => {
    if (!editedData) return null;

    return (
      <ScrollArea className="h-[400px] pr-4">
        <div className="space-y-4">
          <div>
            <Label htmlFor="label">Profile Name</Label>
            <Input
              id="label"
              value={editedData.label}
              onChange={(e) => updateField('label', e.target.value)}
              data-testid="input-icp-label"
            />
          </div>

          <div>
            <Label htmlFor="targetDescription">Description</Label>
            <Textarea
              id="targetDescription"
              value={editedData.targetDescription}
              onChange={(e) => updateField('targetDescription', e.target.value)}
              className="min-h-[80px]"
              data-testid="textarea-icp-description"
            />
          </div>

          <div>
            <Label htmlFor="industries">Industries (comma-separated)</Label>
            <Input
              id="industries"
              value={editedData.industries.join(', ')}
              onChange={(e) => updateField('industries', e.target.value.split(',').map(s => s.trim()).filter(Boolean))}
              placeholder="SaaS, Technology, Healthcare"
              data-testid="input-icp-industries"
            />
          </div>

          <div>
            <Label htmlFor="roles">Target Roles (comma-separated)</Label>
            <Input
              id="roles"
              value={editedData.roles.join(', ')}
              onChange={(e) => updateField('roles', e.target.value.split(',').map(s => s.trim()).filter(Boolean))}
              placeholder="CEO, VP Sales, Head of Marketing"
              data-testid="input-icp-roles"
            />
          </div>

          <div>
            <Label htmlFor="companySizes">Company Sizes (comma-separated)</Label>
            <Input
              id="companySizes"
              value={editedData.companySizes.join(', ')}
              onChange={(e) => updateField('companySizes', e.target.value.split(',').map(s => s.trim()).filter(Boolean))}
              placeholder="10-50, 50-200, 200-500"
              data-testid="input-icp-sizes"
            />
          </div>

          <div>
            <Label htmlFor="locations">Locations (comma-separated, optional)</Label>
            <Input
              id="locations"
              value={editedData.locations.join(', ')}
              onChange={(e) => updateField('locations', e.target.value.split(',').map(s => s.trim()).filter(Boolean))}
              placeholder="United States, Canada, UK"
              data-testid="input-icp-locations"
            />
          </div>

          <div>
            <Label htmlFor="painPoints">Pain Points (one per line)</Label>
            <Textarea
              id="painPoints"
              value={editedData.painPoints.join('\n')}
              onChange={(e) => updateField('painPoints', e.target.value.split('\n').filter(Boolean))}
              className="min-h-[100px]"
              placeholder="Struggling with customer retention&#10;Need better analytics&#10;Manual processes slowing growth"
              data-testid="textarea-icp-pain-points"
            />
          </div>
        </div>
      </ScrollArea>
    );
  };

  return (
    <Dialog open={open} onOpenChange={() => {}}>
      <DialogContent className="sm:max-w-[600px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Users className="h-5 w-5 text-primary" />
            Your Ideal Customer Profile
          </DialogTitle>
          <DialogDescription>
            {generateICP.isPending 
              ? "We're analyzing your product and search results to create the perfect customer profile..."
              : isEditing
              ? "Customize the profile to match your exact needs"
              : "We've created a customer profile based on your product and search. You can edit this anytime."
            }
          </DialogDescription>
        </DialogHeader>

        <div className="min-h-[300px]">
          {generateICP.isPending ? (
            <div className="flex flex-col items-center justify-center h-[300px] space-y-4">
              <div className="relative">
                <Sparkles className="h-12 w-12 text-primary animate-pulse" />
                <div className="absolute inset-0 animate-spin rounded-full border-2 border-primary border-t-transparent" />
              </div>
              <p className="text-sm text-muted-foreground">Generating your ideal customer profile...</p>
            </div>
          ) : isEditing ? (
            renderEditForm()
          ) : (
            renderICPPreview()
          )}
        </div>

        <DialogFooter>
          {isEditing ? (
            <>
              <Button
                variant="outline"
                onClick={handleCancelEdit}
                data-testid="button-cancel-edit"
              >
                Cancel
              </Button>
              <Button
                onClick={handleSaveEdit}
                data-testid="button-save-edit"
              >
                <Check className="h-4 w-4 mr-2" />
                Save Changes
              </Button>
            </>
          ) : (
            <>
              <Button
                variant="outline"
                onClick={onBack}
                disabled={generateICP.isPending || saveICP.isPending}
                data-testid="button-back"
              >
                Back
              </Button>
              <Button
                onClick={handleConfirm}
                disabled={!icpData || saveICP.isPending}
                data-testid="button-confirm-icp"
              >
                {saveICP.isPending ? 'Saving...' : 'Looks Good!'}
              </Button>
            </>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/onboarding/Onboard.content:
import { useState, useEffect } from "react";
import { SearchConfirmationModal } from "./SearchConfirmationModal";
import { ProductSetupModal } from "./ProductSetupModal";
import { ICPGenerationModal } from "./ICPGenerationModal";
import { SenderProfileEnhancedModal } from "./SenderProfileEnhancedModal";
import { useToast } from "@/hooks/use-toast";
import { useMutation, useQuery } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import type { Company, Contact } from "@shared/schema";

export interface OnboardingFlowProps {
  open: boolean;
  onClose: () => void;
  searchQuery: string;
  searchResults: Company[];
  onComplete?: () => void;
}

export type OnboardingStep = 
  | 'search_confirmation'
  | 'product_setup'
  | 'icp_generation'
  | 'sender_profile'
  | 'complete';

interface OnboardingState {
  currentStep: OnboardingStep;
  searchConfirmed: boolean;
  productId: number | null;
  icpId: number | null;
  senderProfileId: number | null;
  skipSenderProfile: boolean;
}

export function OnboardingFlow({
  open,
  onClose,
  searchQuery,
  searchResults,
  onComplete
}: OnboardingFlowProps) {
  const { toast } = useToast();

  const [state, setState] = useState<OnboardingState>({
    currentStep: 'search_confirmation',
    searchConfirmed: false,
    productId: null,
    icpId: null,
    senderProfileId: null,
    skipSenderProfile: false
  });

  // Track onboarding progress in the backend
  const saveOnboardingProgress = useMutation({
    mutationFn: async (data: Partial<OnboardingState>) => {
      const res = await apiRequest('POST', '/api/onboarding/progress', {
        ...state,
        ...data,
        searchQuery,
        completedAt: data.currentStep === 'complete' ? new Date().toISOString() : null
      });
      return res.json();
    },
    onError: (error) => {
      console.error('Failed to save onboarding progress:', error);
    }
  });

  // Handle search confirmation
  const handleSearchConfirmation = (confirmed: boolean, refinedQuery?: string) => {
    if (confirmed) {
      setState(prev => ({
        ...prev,
        searchConfirmed: true,
        currentStep: 'product_setup'
      }));
      saveOnboardingProgress.mutate({ searchConfirmed: true, currentStep: 'product_setup' });
    } else if (refinedQuery) {
      // User wants to refine search - close onboarding and trigger new search
      toast({
        title: "Let's refine your search",
        description: "We'll help you find better matches."
      });
      onClose();
      // Trigger search refinement in parent component
      window.location.href = `/?q=${encodeURIComponent(refinedQuery)}`;
    } else {
      onClose();
    }
  };

  // Handle product creation
  const handleProductComplete = (productId: number) => {
    setState(prev => ({
      ...prev,
      productId,
      currentStep: 'icp_generation'
    }));
    saveOnboardingProgress.mutate({ productId, currentStep: 'icp_generation' });
  };

  // Handle ICP generation/confirmation
  const handleICPComplete = (icpId: number) => {
    setState(prev => ({
      ...prev,
      icpId,
      currentStep: 'sender_profile'
    }));
    saveOnboardingProgress.mutate({ icpId, currentStep: 'sender_profile' });
  };

  // Handle sender profile completion or skip
  const handleSenderProfileComplete = (profileId: number | null, skipped: boolean = false) => {
    setState(prev => ({
      ...prev,
      senderProfileId: profileId,
      skipSenderProfile: skipped,
      currentStep: 'complete'
    }));

    saveOnboardingProgress.mutate({ 
      senderProfileId: profileId, 
      skipSenderProfile: skipped,
      currentStep: 'complete' 
    });

    // Show completion message
    toast({
      title: "🎉 Setup Complete!",
      description: "You're ready to start your outreach campaigns.",
      className: "bg-green-50 border-green-200"
    });

    // Call onComplete callback
    if (onComplete) {
      onComplete();
    }

    // Close the flow
    setTimeout(() => {
      onClose();
    }, 2000);
  };

  // Reset state when modal closes
  useEffect(() => {
    if (!open) {
      setState({
        currentStep: 'search_confirmation',
        searchConfirmed: false,
        productId: null,
        icpId: null,
        senderProfileId: null,
        skipSenderProfile: false
      });
    }
  }, [open]);

  if (!open) return null;

  return (
    <>
      {/* Step 1: Confirm Search Results */}
      <SearchConfirmationModal
        open={state.currentStep === 'search_confirmation'}
        searchQuery={searchQuery}
        searchResults={searchResults}
        onConfirm={handleSearchConfirmation}
        onClose={onClose}
      />

      {/* Step 2: Product Setup */}
      <ProductSetupModal
        open={state.currentStep === 'product_setup'}
        onComplete={handleProductComplete}
        onBack={() => setState(prev => ({ ...prev, currentStep: 'search_confirmation' }))}
        onClose={onClose}
      />

      {/* Step 3: ICP Generation */}
      <ICPGenerationModal
        open={state.currentStep === 'icp_generation'}
        productId={state.productId}
        searchQuery={searchQuery}
        searchResults={searchResults}
        onComplete={handleICPComplete}
        onBack={() => setState(prev => ({ ...prev, currentStep: 'product_setup' }))}
        onClose={onClose}
      />

      {/* Step 4: Sender Profile (Optional) */}
      <SenderProfileEnhancedModal
        open={state.currentStep === 'sender_profile'}
        onComplete={handleSenderProfileComplete}
        onSkip={() => handleSenderProfileComplete(null, true)}
        onBack={() => setState(prev => ({ ...prev, currentStep: 'icp_generation' }))}
        onClose={onClose}
      />
    </>
  );
}

