import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Card } from "@/components/ui/card";
import { User, Building2, MapPin, Heart, BookOpen, SkipForward, AlertCircle } from "lucide-react";
import { useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/use-auth";

interface SenderProfileEnhancedModalProps {
  open: boolean;
  onComplete: (profileId: number | null, skipped: boolean) => void;
  onSkip: () => void;
  onBack: () => void;
  onClose: () => void;
}

interface EnhancedProfileData {
  // Basic Info (Step 1)
  displayName: string;
  email: string;
  firstName: string;
  lastName: string;
  title: string;
  // Company Info (Step 2)
  company: string;
  city: string;
  website: string;
  // Personal Story (Step 3)
  personalStory: string;
  hobbies: string;
  interests: string;
}

export function SenderProfileEnhancedModal({
  open,
  onComplete,
  onSkip,
  onBack,
  onClose
}: SenderProfileEnhancedModalProps) {
  const { toast } = useToast();
  const { user } = useAuth();
  const [currentStep, setCurrentStep] = useState(1);
  const [formData, setFormData] = useState<EnhancedProfileData>({
    displayName: user?.username || '',
    email: user?.email || '',
    firstName: '',
    lastName: '',
    title: '',
    company: '',
    city: '',
    website: '',
    personalStory: '',
    hobbies: '',
    interests: ''
  });

  const createProfile = useMutation({
    mutationFn: async (data: EnhancedProfileData) => {
      const res = await apiRequest('POST', '/api/sender-profiles', {
        name: data.displayName || `${data.firstName} ${data.lastName}`.trim(),
        email: data.email,
        firstName: data.firstName,
        lastName: data.lastName,
        title: data.title,
        company: data.company,
        city: data.city,
        website: data.website,
        // Store personal info in metadata or new fields
        metadata: {
          personalStory: data.personalStory,
          hobbies: data.hobbies,
          interests: data.interests
        },
        isDefault: false
      });
      return res.json();
    },
    onSuccess: (data) => {
      toast({
        title: "Profile created!",
        description: "Your sender profile has been saved."
      });
      queryClient.invalidateQueries({ queryKey: ['/api/sender-profiles'] });
      onComplete(data.id, false);
    },
    onError: (error) => {
      toast({
        title: "Failed to create profile",
        description: error instanceof Error ? error.message : 'Please try again',
        variant: "destructive"
      });
    }
  });

  const handleNext = () => {
    if (currentStep < 3) {
      setCurrentStep(currentStep + 1);
    } else {
      handleSubmit();
    }
  };

  const handleSubmit = () => {
    if (!formData.email || !formData.displayName) {
      toast({
        title: "Missing required fields",
        description: "Please provide at least your name and email",
        variant: "destructive"
      });
      return;
    }
    createProfile.mutate(formData);
  };

  const updateField = (field: keyof EnhancedProfileData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const getStepContent = () => {
    switch (currentStep) {
      case 1:
        return (
          <div className="space-y-4">
            <div className="bg-blue-50 dark:bg-blue-950/30 p-3 rounded-lg flex items-start gap-2">
              <AlertCircle className="h-4 w-4 text-blue-600 dark:text-blue-400 mt-0.5" />
              <p className="text-sm text-blue-800 dark:text-blue-200">
                Your identity helps build trust with prospects. Real names and titles significantly improve response rates.
              </p>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="firstName">First Name</Label>
                <Input
                  id="firstName"
                  value={formData.firstName}
                  onChange={(e) => updateField('firstName', e.target.value)}
                  placeholder="John"
                  data-testid="input-first-name"
                />
              </div>
              <div>
                <Label htmlFor="lastName">Last Name</Label>
                <Input
                  id="lastName"
                  value={formData.lastName}
                  onChange={(e) => updateField('lastName', e.target.value)}
                  placeholder="Smith"
                  data-testid="input-last-name"
                />
              </div>
            </div>

            <div>
              <Label htmlFor="displayName">Display Name *</Label>
              <Input
                id="displayName"
                value={formData.displayName}
                onChange={(e) => updateField('displayName', e.target.value)}
                placeholder="John Smith"
                data-testid="input-display-name"
              />
            </div>

            <div>
              <Label htmlFor="email">Email Address *</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => updateField('email', e.target.value)}
                placeholder="john@company.com"
                data-testid="input-email"
              />
            </div>

            <div>
              <Label htmlFor="title">Job Title</Label>
              <Input
                id="title"
                value={formData.title}
                onChange={(e) => updateField('title', e.target.value)}
                placeholder="e.g., Founder, Sales Manager, CEO"
                data-testid="input-title"
              />
            </div>
          </div>
        );

      case 2:
        return (
          <div className="space-y-4">
            <div className="bg-blue-50 dark:bg-blue-950/30 p-3 rounded-lg flex items-start gap-2">
              <AlertCircle className="h-4 w-4 text-blue-600 dark:text-blue-400 mt-0.5" />
              <p className="text-sm text-blue-800 dark:text-blue-200">
                Company details add credibility. Prospects are more likely to respond to established businesses.
              </p>
            </div>

            <div>
              <Label htmlFor="company">Company Name</Label>
              <Input
                id="company"
                value={formData.company}
                onChange={(e) => updateField('company', e.target.value)}
                placeholder="Acme Corporation"
                data-testid="input-company"
              />
            </div>

            <div>
              <Label htmlFor="city">City / Location</Label>
              <Input
                id="city"
                value={formData.city}
                onChange={(e) => updateField('city', e.target.value)}
                placeholder="San Francisco, CA"
                data-testid="input-city"
              />
            </div>

            <div>
              <Label htmlFor="website">Company Website</Label>
              <Input
                id="website"
                type="url"
                value={formData.website}
                onChange={(e) => updateField('website', e.target.value)}
                placeholder="https://www.company.com"
                data-testid="input-website"
              />
            </div>
          </div>
        );

      case 3:
        return (
          <div className="space-y-4">
            <div className="bg-green-50 dark:bg-green-950/30 p-3 rounded-lg flex items-start gap-2">
              <Heart className="h-4 w-4 text-green-600 dark:text-green-400 mt-0.5" />
              <p className="text-sm text-green-800 dark:text-green-200">
                Personal touches make your outreach more human and relatable. This significantly improves engagement.
              </p>
            </div>

            <div>
              <Label htmlFor="personalStory">
                Your Story (Optional)
                <span className="text-xs text-muted-foreground ml-2">What's your background?</span>
              </Label>
              <Textarea
                id="personalStory"
                value={formData.personalStory}
                onChange={(e) => updateField('personalStory', e.target.value)}
                placeholder="e.g., I started this company after 10 years in enterprise sales, where I saw firsthand how..."
                className="min-h-[100px]"
                data-testid="textarea-personal-story"
              />
            </div>

            <div>
              <Label htmlFor="hobbies">
                Hobbies & Interests (Optional)
                <span className="text-xs text-muted-foreground ml-2">What do you enjoy outside work?</span>
              </Label>
              <Input
                id="hobbies"
                value={formData.hobbies}
                onChange={(e) => updateField('hobbies', e.target.value)}
                placeholder="e.g., Marathon running, Chess, Cooking Italian food"
                data-testid="input-hobbies"
              />
            </div>

            <div>
              <Label htmlFor="interests">
                Professional Interests (Optional)
                <span className="text-xs text-muted-foreground ml-2">What topics excite you?</span>
              </Label>
              <Input
                id="interests"
                value={formData.interests}
                onChange={(e) => updateField('interests', e.target.value)}
                placeholder="e.g., AI/ML, Sustainable business, B2B sales strategies"
                data-testid="input-interests"
              />
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  const getStepTitle = () => {
    switch (currentStep) {
      case 1: return "Your Professional Identity";
      case 2: return "Your Company";
      case 3: return "Personal Touch (Optional)";
      default: return "";
    }
  };

  const getStepIcon = () => {
    switch (currentStep) {
      case 1: return <User className="h-5 w-5 text-primary" />;
      case 2: return <Building2 className="h-5 w-5 text-primary" />;
      case 3: return <Heart className="h-5 w-5 text-primary" />;
      default: return null;
    }
  };

  return (
    <Dialog open={open} onOpenChange={() => {}}>
      <DialogContent className="sm:max-w-[550px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {getStepIcon()}
            {getStepTitle()}
          </DialogTitle>
          <DialogDescription>
            {currentStep === 3 
              ? "Add a personal touch to make your outreach more engaging (completely optional)"
              : "This information appears in your email signature and helps build trust"
            }
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* Progress Indicator */}
          <div className="flex items-center gap-2">
            <div className={`h-2 flex-1 rounded-full ${currentStep >= 1 ? 'bg-primary' : 'bg-muted'}`} />
            <div className={`h-2 flex-1 rounded-full ${currentStep >= 2 ? 'bg-primary' : 'bg-muted'}`} />
            <div className={`h-2 flex-1 rounded-full ${currentStep >= 3 ? 'bg-primary' : 'bg-muted'}`} />
          </div>

          {getStepContent()}

          {/* Skip Option Card - Always visible */}
          {currentStep === 1 && (
            <Card className="p-3 bg-muted/50">
              <button
                onClick={onSkip}
                className="flex items-center gap-2 w-full text-left hover:text-primary transition-colors"
                data-testid="button-skip-sender"
              >
                <SkipForward className="h-4 w-4" />
                <div className="flex-1">
                  <p className="text-sm font-medium">Skip for now</p>
                  <p className="text-xs text-muted-foreground">
                    You can add your sender profile later from settings
                  </p>
                </div>
              </button>
            </Card>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={currentStep === 1 ? onBack : () => setCurrentStep(currentStep - 1)}
            disabled={createProfile.isPending}
            data-testid="button-back"
          >
            Back
          </Button>
          <Button
            onClick={handleNext}
            disabled={createProfile.isPending}
            data-testid="button-next"
          >
            {createProfile.isPending ? (
              'Creating...'
            ) : currentStep === 3 ? (
              'Complete Setup'
            ) : (
              'Next'
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

