                </div>
              </div>
            </>
          ) : (
            <>
              {/* Step 2: Unique Value */}
              <div className="space-y-4">
                <div className="bg-muted/50 p-3 rounded-lg flex items-start gap-2">
                  <AlertCircle className="h-4 w-4 text-primary mt-0.5" />
                  <p className="text-sm text-muted-foreground">
                    These details help create compelling, personalized outreach messages
                  </p>
                </div>

                <div>
                  <Label htmlFor="uniqueAttributes">
                    What makes you unique? (List 2-3 key differentiators)
                  </Label>
                  <Textarea
                    id="uniqueAttributes"
                    value={formData.uniqueAttributes}
                    onChange={(e) => updateField('uniqueAttributes', e.target.value)}
                    placeholder="• 10x faster implementation than competitors&#10;• No-code solution requiring zero technical knowledge&#10;• 24/7 dedicated support team"
                    className="min-h-[100px]"
                    data-testid="textarea-unique-attributes"
                  />
                </div>

                <div>
                  <Label htmlFor="customerFeedback">
                    What do customers say about you? (Optional)
                  </Label>
                  <Textarea
                    id="customerFeedback"
                    value={formData.customerFeedback}
                    onChange={(e) => updateField('customerFeedback', e.target.value)}
                    placeholder="e.g., 'Cut our operational costs by 40%', 'Best customer service we've ever experienced'"
                    className="min-h-[80px]"
                    data-testid="textarea-customer-feedback"
                  />
                </div>

                <div>
                  <Label htmlFor="website">
                    Website (Optional)
                  </Label>
                  <Input
                    id="website"
                    type="url"
                    value={formData.website}
                    onChange={(e) => updateField('website', e.target.value)}
                    placeholder="https://www.yourcompany.com"
                    data-testid="input-website"
                  />
                </div>
              </div>
            </>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={currentStep === 1 ? onClose : () => setCurrentStep(1)}
            data-testid="button-back"
          >
            {currentStep === 1 ? 'Cancel' : 'Back'}
          </Button>
          <Button
            onClick={handleNext}
            disabled={createProduct.isPending}
            data-testid="button-next"
          >
            {createProduct.isPending ? (
              <>Creating...</>
            ) : currentStep === 1 ? (
              <>Next</>
            ) : (
              <>
                <Sparkles className="h-4 w-4 mr-2" />
                Create Product
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

