import { useState, useEffect } from "react";
import { Switch } from "@/components/ui/switch";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { 
  Calendar,
  Wand2,
  Info,
  MailCheck,
  Link,
  Settings,
  ChevronUp,
  ChevronDown,
  UserCheck,
  Mail,
  CheckCircle,
  XCircle,
  AlertCircle,
  User
} from "lucide-react";
import { cn } from "@/lib/utils";
import { ScheduleSendModal } from "@/components/schedule-send-modal";
import { AutopilotModal, type AutopilotSettings } from "@/components/autopilot-modal";
import { format } from "date-fns";
import { Send } from "lucide-react";
import { useQuery } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useAuth } from "@/hooks/use-auth";

interface GmailAuthStatus {
  authorized: boolean;
  hasValidToken: boolean;
}

interface SenderProfile {
  id: number;
  userId: number;
  displayName: string;
  email: string;
  companyName?: string;
  companyWebsite?: string;
  title?: string;
  isDefault: boolean;
}

export interface CampaignSettingsData {
  scheduleSend: boolean;
  scheduleDate?: Date;
  scheduleTime?: string;
  autopilot: boolean;
  autopilotSettings?: AutopilotSettings;
  requiresHumanReview: boolean;
  emailTemplateId?: number;
  trackEmails: boolean;
  unsubscribeLink: boolean;
  senderProfileId?: number;
}

interface CampaignSettingsProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  settings: CampaignSettingsData;
  onSettingsChange: (settings: CampaignSettingsData) => void;
  className?: string;
  totalRecipients?: number;
}

export function CampaignSettings({ 
  open, 
  onOpenChange,
  settings,
  onSettingsChange,
  className,
  totalRecipients = 100
}: CampaignSettingsProps) {
  const { user, authReady } = useAuth();
  const [localSettings, setLocalSettings] = useState<CampaignSettingsData>(settings);
  const [scheduleModalOpen, setScheduleModalOpen] = useState(false);
  const [autopilotModalOpen, setAutopilotModalOpen] = useState(false);

  // Sync local settings when parent props change (e.g., after restoring from localStorage)
  useEffect(() => {
    setLocalSettings(settings);
  }, [settings]);

  // Check Gmail connection status - wait for auth to be ready
  const { data: gmailStatus } = useQuery<GmailAuthStatus>({
    queryKey: ['/api/gmail/auth-status'],
    refetchInterval: 10000, // Refresh every 10 seconds
    enabled: authReady && !!user,
  });

  // Fetch sender profiles - wait for auth to be ready
  const { data: senderProfiles } = useQuery<SenderProfile[]>({
    queryKey: ['/api/sender-profiles'],
    enabled: authReady && !!user,
  });

  // Set default sender profile when profiles are loaded
  useEffect(() => {
    if (senderProfiles && senderProfiles.length > 0 && !localSettings.senderProfileId) {
      const defaultProfile = senderProfiles.find(p => p.isDefault) || senderProfiles[0];
      const updated = { ...localSettings, senderProfileId: defaultProfile.id };
      setLocalSettings(updated);
      onSettingsChange(updated);
    }
  }, [senderProfiles]);

  const handleToggle = (key: keyof CampaignSettingsData, value: boolean) => {
    const updated = { ...localSettings, [key]: value };
    setLocalSettings(updated);
    onSettingsChange(updated);
  };

  const handleSenderProfileChange = (profileId: string) => {
    const updated = { ...localSettings, senderProfileId: parseInt(profileId) };
    setLocalSettings(updated);
    onSettingsChange(updated);
  };

  const handleScheduleApply = (date: Date, time: string) => {
    // Combine date and time
    const [hours, minutes] = time.split(':').map(Number);
    const scheduledDate = new Date(date);
    scheduledDate.setHours(hours, minutes, 0, 0);

    const updated = { 
      ...localSettings, 
      scheduleSend: true,
      scheduleDate: scheduledDate,
      scheduleTime: time 
    };
    setLocalSettings(updated);
    onSettingsChange(updated);
  };

  const handleAutopilotApply = (autopilotSettings: AutopilotSettings) => {
    const updated = {
      ...localSettings,
      autopilot: true,
      autopilotSettings: autopilotSettings
    };
    setLocalSettings(updated);
    onSettingsChange(updated);
  };

  return (
    <>
    <div className={cn("space-y-1 pt-1 pb-4", className)}>
          {/* Sending Method Status */}
          <div className="w-full px-2 py-2 bg-muted/30 rounded-lg mb-2">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Mail className="h-4 w-4 text-muted-foreground" />
                <span className="text-sm font-medium text-muted-foreground">
                  Sending Method
                </span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-sm text-muted-foreground">
                  {gmailStatus?.authorized ? 'Gmail' : 'Manual'}
                </span>
                {gmailStatus?.authorized ? (
                  <TooltipProvider>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <CheckCircle className="h-4 w-4 text-green-500" />
                      </TooltipTrigger>
                      <TooltipContent side="top">
                        <p>Gmail connected - emails will be sent automatically</p>
                      </TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                ) : (
                  <TooltipProvider>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <AlertCircle className="h-4 w-4 text-yellow-500" />
                      </TooltipTrigger>
                      <TooltipContent side="top" className="max-w-xs">
                        <p>Gmail not connected - you'll need to send emails manually after approval</p>
                      </TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                )}
              </div>
            </div>
            {!gmailStatus?.authorized && (
              <div className="mt-2 pt-2 border-t border-border/50">
                <Button
                  variant="outline"
                  size="sm"
                  className="w-full text-xs py-1 h-7"
                  onClick={() => window.open(`/api/gmail/auth?userId=${(window as any).userId || 1}`, '_blank')}
                >
                  Connect Gmail to enable automatic sending
                </Button>
              </div>
            )}
          </div>

          {/* Sender Profile Selector */}
          {senderProfiles && senderProfiles.length > 0 && (
            <div className="w-full px-2 py-2 bg-muted/30 rounded-lg mb-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <User className="h-4 w-4 text-muted-foreground" />
                  <span className="text-sm font-medium text-muted-foreground">
                    Sender profile
                  </span>
                </div>
                <Select
                  value={localSettings.senderProfileId?.toString() || ''}
                  onValueChange={handleSenderProfileChange}
                >
                  <SelectTrigger className="w-48 h-7 text-xs">
                    <SelectValue placeholder="Select profile" />
                  </SelectTrigger>
                  <SelectContent>
                    {senderProfiles.map((profile) => (
                      <SelectItem key={profile.id} value={profile.id.toString()}>
                        <div className="flex items-center gap-1">
                          <span>{profile.displayName}</span>
                          {profile.isDefault && (
                            <span className="text-xs text-muted-foreground">(default)</span>
                          )}
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              {!senderProfiles || senderProfiles.length === 0 && (
                <div className="mt-2 pt-2 border-t border-border/50">
                  <p className="text-xs text-muted-foreground">
                    Connect Gmail to create a sender profile
                  </p>
                </div>
              )}
            </div>
          )}

          {/* Schedule Send Button */}
          <Button
            variant="ghost"
            className="w-full justify-between h-auto py-1.5 px-2 hover:bg-muted/50"
            onClick={() => setScheduleModalOpen(true)}
          >
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm font-normal text-muted-foreground">
                Schedule send
              </span>
            </div>
            <div className="text-xs text-muted-foreground">
              {localSettings.scheduleSend && localSettings.scheduleDate 
                ? format(localSettings.scheduleDate, "MMM d, h:mm a")
                : ''}
            </div>
          </Button>

          {/* Autopilot Button */}
          <Button
            variant="ghost"
            className="w-full justify-between h-auto py-1.5 px-2 hover:bg-muted/50"
            onClick={() => setAutopilotModalOpen(true)}
          >
            <div className="flex items-center gap-2">
              <Wand2 className="h-4 w-4 text-muted-foreground" />
              <div className="flex items-center gap-1.5">
                <span className="text-sm font-normal text-muted-foreground">
                  Autopilot
                </span>
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Info 
                        className="h-3 w-3 text-muted-foreground cursor-help" 
                        onClick={(e) => e.stopPropagation()}
                      />
                    </TooltipTrigger>
                    <TooltipContent side="top" className="max-w-xs">
                      <p>Automatically send emails at optimal times throughout the day</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </div>
            </div>
            <div className="text-xs text-muted-foreground">
              {localSettings.autopilot && localSettings.autopilotSettings?.maxEmailsPerDay 
                ? `${localSettings.autopilotSettings.maxEmailsPerDay} per day`
                : ''}
            </div>
          </Button>

          {/* Human Review Button */}
          <Button
            variant="ghost"
            className="w-full justify-between h-auto py-1.5 px-2 hover:bg-muted/50"
            onClick={() => handleToggle('requiresHumanReview', !localSettings.requiresHumanReview)}
          >
            <div className="flex items-center gap-2">
              <UserCheck className="h-4 w-4 text-muted-foreground" />
              <div className="flex items-center gap-1.5">
                <span className="text-sm font-normal text-muted-foreground">
                  Human review
                </span>
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Info 
                        className="h-3 w-3 text-muted-foreground cursor-help"
                        onClick={(e) => e.stopPropagation()}
                      />
                    </TooltipTrigger>
                    <TooltipContent side="top" className="max-w-xs">
                      <p>When enabled, emails require your review before sending. When disabled, template-based emails are sent automatically.</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </div>
            </div>
            <Switch
              checked={localSettings.requiresHumanReview}
              onCheckedChange={(checked) => handleToggle('requiresHumanReview', checked)}
              className="data-[state=checked]:bg-blue-600 scale-90"
              onClick={(e) => e.stopPropagation()}
            />
          </Button>

          {/* Track Emails Button */}
          <Button
            variant="ghost"
            className="w-full justify-between h-auto py-1.5 px-2 hover:bg-muted/50"
            onClick={() => handleToggle('trackEmails', !localSettings.trackEmails)}
          >
            <div className="flex items-center gap-2">
              <MailCheck className="h-4 w-4 text-muted-foreground" />
              <div className="flex items-center gap-1.5">
                <span className="text-sm font-normal text-muted-foreground">
                  Track emails
                </span>
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Info 
                        className="h-3 w-3 text-muted-foreground cursor-help"
                        onClick={(e) => e.stopPropagation()}
                      />
                    </TooltipTrigger>
                    <TooltipContent side="top" className="max-w-xs">
                      <p>Track when recipients open and click links in your emails</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </div>
            </div>
            <Switch
              checked={localSettings.trackEmails}
              onCheckedChange={(checked) => handleToggle('trackEmails', checked)}
              className="data-[state=checked]:bg-blue-600 scale-90"
              onClick={(e) => e.stopPropagation()}
            />
          </Button>

          {/* Unsubscribe Link Button */}
          <Button
            variant="ghost"
            className="w-full justify-between h-auto py-1.5 px-2 hover:bg-muted/50"
            onClick={() => handleToggle('unsubscribeLink', !localSettings.unsubscribeLink)}
          >
            <div className="flex items-center gap-2">
              <Link className="h-4 w-4 text-muted-foreground" />
              <div className="flex items-center gap-1.5">
                <span className="text-sm font-normal text-muted-foreground">
                  Unsubscribe link
                </span>
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Info 
                        className="h-3 w-3 text-muted-foreground cursor-help"
                        onClick={(e) => e.stopPropagation()}
                      />
                    </TooltipTrigger>
                    <TooltipContent side="top" className="max-w-xs">
                      <p>Add an unsubscribe link to comply with email regulations</p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </div>
            </div>
            <Switch
              checked={localSettings.unsubscribeLink}
              onCheckedChange={(checked) => handleToggle('unsubscribeLink', checked)}
              className="data-[state=checked]:bg-blue-600 scale-90"
              onClick={(e) => e.stopPropagation()}
            />
          </Button>
    </div>

    {/* Schedule Send Modal */}
    <ScheduleSendModal
      open={scheduleModalOpen}
      onOpenChange={setScheduleModalOpen}
      selectedDate={localSettings.scheduleDate}
      selectedTime={localSettings.scheduleTime || "09:00"}
      onApply={handleScheduleApply}
    />

    {/* Autopilot Modal */}
    <AutopilotModal
      open={autopilotModalOpen}
      onOpenChange={setAutopilotModalOpen}
      settings={localSettings.autopilotSettings || {
        enabled: false,
        days: {
          monday: { enabled: true, startTime: "09:00", endTime: "17:00" },
          tuesday: { enabled: true, startTime: "09:00", endTime: "17:00" },
          wednesday: { enabled: true, startTime: "09:00", endTime: "17:00" },
          thursday: { enabled: true, startTime: "09:00", endTime: "17:00" },
          friday: { enabled: true, startTime: "09:00", endTime: "17:00" },
          saturday: { enabled: false, startTime: "09:00", endTime: "17:00" },
          sunday: { enabled: false, startTime: "09:00", endTime: "17:00" }
        },
        maxEmailsPerDay: 300,
        delayBetweenEmails: 3,
        delayUnit: 'minutes'
      }}
      onApply={handleAutopilotApply}
      totalEmails={totalRecipients}
    />
    </>
  );
}

client/src/components/autopilot-modal.ts.content:
import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Globe } from "lucide-react";
import { format, addMinutes, differenceInMinutes, startOfDay } from "date-fns";

interface DaySchedule {
  enabled: boolean;
  startTime: string;
  endTime: string;
}

export interface AutopilotSettings {
  enabled: boolean;
  days: {
    monday: DaySchedule;
    tuesday: DaySchedule;
    wednesday: DaySchedule;
    thursday: DaySchedule;
    friday: DaySchedule;
    saturday: DaySchedule;
    sunday: DaySchedule;
  };
  maxEmailsPerDay: number;
  delayBetweenEmails: number; // in minutes
  delayUnit: 'minutes' | 'hours';
  startDate?: Date;
}

interface AutopilotModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  settings: AutopilotSettings;
  onApply: (settings: AutopilotSettings) => void;
  totalEmails?: number; // Total number of emails in the campaign
}

const DEFAULT_DAY_SCHEDULE: DaySchedule = {
  enabled: true,
  startTime: "09:00",
  endTime: "17:00"
};

const DAYS_OF_WEEK = [
  { key: 'monday', label: 'Monday' },
  { key: 'tuesday', label: 'Tuesday' },
  { key: 'wednesday', label: 'Wednesday' },
  { key: 'thursday', label: 'Thursday' },
  { key: 'friday', label: 'Friday' },
  { key: 'saturday', label: 'Saturday' },
  { key: 'sunday', label: 'Sunday' },
] as const;

export function AutopilotModal({
  open,
  onOpenChange,
  settings,
  onApply,
  totalEmails = 100
}: AutopilotModalProps) {
  const [localSettings, setLocalSettings] = useState<AutopilotSettings>(() => ({
    enabled: settings.enabled ?? true,
    days: settings.days ?? {
      monday: { ...DEFAULT_DAY_SCHEDULE, enabled: true },
      tuesday: { ...DEFAULT_DAY_SCHEDULE, enabled: true },
      wednesday: { ...DEFAULT_DAY_SCHEDULE, enabled: true },
      thursday: { ...DEFAULT_DAY_SCHEDULE, enabled: true },
      friday: { ...DEFAULT_DAY_SCHEDULE, enabled: true },
      saturday: { ...DEFAULT_DAY_SCHEDULE, enabled: false },
      sunday: { ...DEFAULT_DAY_SCHEDULE, enabled: false },
    },
    maxEmailsPerDay: settings.maxEmailsPerDay ?? 300,
    delayBetweenEmails: settings.delayBetweenEmails ?? 3,
    delayUnit: settings.delayUnit ?? 'minutes',
    startDate: settings.startDate
  }));

  const [estimatedTime, setEstimatedTime] = useState<string>("");

  // Calculate estimated time to send all emails
  useEffect(() => {
    const calculateEstimatedTime = () => {
      const enabledDays = Object.values(localSettings.days).filter(d => d.enabled).length;

      if (enabledDays === 0) {
        setEstimatedTime("No days selected");
        return;
      }

      const emailsPerDay = Math.min(localSettings.maxEmailsPerDay, Math.ceil(totalEmails / enabledDays));
      const daysNeeded = Math.ceil(totalEmails / emailsPerDay);

      // Calculate hours per day based on working hours
      const firstEnabledDay = Object.values(localSettings.days).find(d => d.enabled);
      if (!firstEnabledDay) return;

      const startTime = new Date(`2024-01-01 ${firstEnabledDay.startTime}`);
      const endTime = new Date(`2024-01-01 ${firstEnabledDay.endTime}`);
      const workingMinutesPerDay = differenceInMinutes(endTime, startTime);

      // Calculate delay impact
      const delayMinutes = localSettings.delayUnit === 'hours' 
        ? localSettings.delayBetweenEmails * 60 
        : localSettings.delayBetweenEmails;

      const totalDelayPerDay = (emailsPerDay - 1) * delayMinutes;
      const totalTimePerDay = totalDelayPerDay;

      if (totalTimePerDay > workingMinutesPerDay) {
        const actualEmailsPerDay = Math.floor(workingMinutesPerDay / delayMinutes);
        const actualDaysNeeded = Math.ceil(totalEmails / actualEmailsPerDay);

        if (actualDaysNeeded === 1) {
          setEstimatedTime(`about ${Math.ceil(totalTimePerDay / 60)} hours`);
        } else if (actualDaysNeeded < 7) {
          setEstimatedTime(`about ${actualDaysNeeded} days`);
        } else {
          const weeks = Math.floor(actualDaysNeeded / 7);
          const days = actualDaysNeeded % 7;
          if (days === 0) {
            setEstimatedTime(`about ${weeks} week${weeks > 1 ? 's' : ''}`);
          } else {
            setEstimatedTime(`about ${weeks} week${weeks > 1 ? 's' : ''} and ${days} day${days > 1 ? 's' : ''}`);
          }
        }
      } else {
        if (daysNeeded === 1) {
          const hours = Math.ceil(totalTimePerDay / 60);
          setEstimatedTime(`about ${hours} hour${hours > 1 ? 's' : ''}`);
        } else if (daysNeeded < 7) {
          setEstimatedTime(`about ${daysNeeded} day${daysNeeded > 1 ? 's' : ''}`);
        } else {
          const weeks = Math.floor(daysNeeded / 7);
          const days = daysNeeded % 7;
          if (days === 0) {
            setEstimatedTime(`about ${weeks} week${weeks > 1 ? 's' : ''}`);
          } else {
            setEstimatedTime(`about ${weeks} week${weeks > 1 ? 's' : ''} and ${days} day${days > 1 ? 's' : ''}`);
          }
        }
      }
    };

    calculateEstimatedTime();
  }, [localSettings, totalEmails]);

  const handleDayToggle = (day: keyof typeof localSettings.days) => {
    setLocalSettings(prev => ({
      ...prev,
      days: {
        ...prev.days,
        [day]: {
          ...prev.days[day],
          enabled: !prev.days[day].enabled
        }
      }
    }));
  };

  const handleTimeChange = (
    day: keyof typeof localSettings.days, 
    field: 'startTime' | 'endTime', 
    value: string
  ) => {
    setLocalSettings(prev => ({
      ...prev,
      days: {
        ...prev.days,
        [day]: {
          ...prev.days[day],
          [field]: value
        }
      }
    }));
  };

  const handleApply = () => {
    // Ensure the enabled field is set to true when applying settings
    const settingsToApply = {
      ...localSettings,
      enabled: true  // Always set to true when applying autopilot settings
    };
    onApply(settingsToApply);
    onOpenChange(false);
  };

  // Get the next scheduled start date
  const getNextStartDate = () => {
    const today = new Date();
    const dayOfWeek = today.getDay();
    const daysMap = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];

    // Find next enabled day
    for (let i = 0; i < 7; i++) {
      const checkDay = (dayOfWeek + i) % 7;
      const dayName = daysMap[checkDay] as keyof typeof localSettings.days;
      if (localSettings.days[dayName].enabled) {
        const nextDate = new Date(today);
        nextDate.setDate(today.getDate() + i);

        // Set time from schedule
        const [hours, minutes] = localSettings.days[dayName].startTime.split(':').map(Number);
        nextDate.setHours(hours, minutes, 0, 0);

        // If it's today but time has passed, go to next enabled day
        if (i === 0 && nextDate < new Date()) {
          continue;
        }

        return nextDate;
      }
    }
    return null;
  };

  const nextStart = getNextStartDate();

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-2xl">Autopilot</DialogTitle>
          <p className="text-sm text-muted-foreground mt-2">
            Improve your deliverability with these sending options{" "}
            <a href="#" className="text-blue-600 hover:underline">
              (why it's important)
            </a>
            .
          </p>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {/* Days Selection */}
          <div className="space-y-3">
            <Label className="text-base font-medium">Send only on</Label>
            <div className="space-y-2">
              {DAYS_OF_WEEK.map(({ key, label }) => (
                <div key={key} className="flex items-center gap-4">
                  <div className="flex items-center gap-2 w-32">
                    <Checkbox
                      id={key}
                      checked={localSettings.days[key].enabled}
                      onCheckedChange={() => handleDayToggle(key)}
                      className="data-[state=checked]:bg-blue-600 data-[state=checked]:border-blue-600"
                    />
                    <Label 
                      htmlFor={key} 
                      className="font-normal cursor-pointer"
                    >
                      {label}
                    </Label>
                  </div>

                  <div className="flex items-center gap-2">
                    <Input
                      type="time"
                      value={localSettings.days[key].startTime}
                      onChange={(e) => handleTimeChange(key, 'startTime', e.target.value)}
                      disabled={!localSettings.days[key].enabled}
                      className="w-24"
                    />
                    <span className="text-sm text-muted-foreground">to</span>
                    <Input
                      type="time"
                      value={localSettings.days[key].endTime}
                      onChange={(e) => handleTimeChange(key, 'endTime', e.target.value)}
                      disabled={!localSettings.days[key].enabled}
                      className="w-24"
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Sending Rate */}
          <div className="space-y-3">
            <Label className="text-base font-medium">Sending rate</Label>

            {/* Max emails per day */}
            <div className="flex items-center gap-3">
              <Checkbox
                checked={true}
                disabled
                className="data-[state=checked]:bg-blue-600 data-[state=checked]:border-blue-600"
              />
              <Label className="font-normal">Max emails per day:</Label>
              <Input
                type="number"
                value={localSettings.maxEmailsPerDay}
                onChange={(e) => setLocalSettings(prev => ({
                  ...prev,
                  maxEmailsPerDay: parseInt(e.target.value) || 1
                }))}
                className="w-20"
                min={1}
                max={1000}
              />
            </div>

            {/* Delay between emails */}
            <div className="flex items-center gap-3">
              <Checkbox
                checked={true}
                disabled
                className="data-[state=checked]:bg-blue-600 data-[state=checked]:border-blue-600"
              />
              <Label className="font-normal">Delay between emails:</Label>
              <Input
                type="number"
                value={localSettings.delayBetweenEmails}
                onChange={(e) => setLocalSettings(prev => ({
                  ...prev,
                  delayBetweenEmails: parseInt(e.target.value) || 1
                }))}
                className="w-16"
                min={1}
                max={60}
              />
              <Select
                value={localSettings.delayUnit}
                onValueChange={(value: 'minutes' | 'hours') => 
                  setLocalSettings(prev => ({ ...prev, delayUnit: value }))
                }
              >
                <SelectTrigger className="w-24">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="minutes">minutes</SelectItem>
                  <SelectItem value="hours">hours</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Start Date Info */}
          {nextStart && (
            <div className="space-y-2 p-4 bg-muted/50 rounded-lg">
              <p className="text-sm font-medium">Sending will start on</p>
              <p className="text-sm text-muted-foreground">
                {format(nextStart, "EEEE, MMM d, yyyy 'at' h:mm a")}
              </p>
            </div>
          )}

          {/* Summary */}
          <div className="space-y-2 p-4 bg-muted/50 rounded-lg">
            <p className="text-sm font-medium">Summary</p>
            <p className="text-sm text-muted-foreground">
              With the current settings, if you send {totalEmails} emails, it will take{" "}
              <span className="font-medium underline">{estimatedTime}</span>.
            </p>
          </div>

          {/* Timezone note */}
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <Globe className="h-3 w-3" />
            <span>Based on your timezone</span>
          </div>
        </div>

        <DialogFooter className="flex flex-col gap-2 sm:flex-row">
          <Button 
            variant="outline" 
            onClick={() => onOpenChange(false)}
            className="w-full sm:w-auto"
          >
            Cancel
          </Button>
          <Button 
            onClick={handleApply}
            className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white"
          >
            Apply
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

