  onClose,
  onConfirm,
  onEdit,
  icpData,
  searchResults
}: ICPPreviewModalProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editedICP, setEditedICP] = useState<ICPData>(icpData || {});

  const handleConfirm = () => {
