import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Send, Loader2, Rocket, FileText, ChevronDown } from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import type { RecipientSelection } from '@/components/recipient-selection-modal';

interface CampaignSendButtonProps {
  recipients?: RecipientSelection | null;
  listId?: number | null;
  currentQuery?: string | null;
  subject?: string;
  body?: string;
  onSchedule?: () => void;
  onStartNow?: () => void;
  onSaveDraft?: () => void;
  isPending?: boolean;
  isSuccess?: boolean;
  className?: string;
  disabled?: boolean;
}

export function CampaignSendButton({
  recipients,
  listId,
  currentQuery,
  subject,
  body,
  onSchedule,
  onStartNow,
  onSaveDraft,
  isPending = false,
  isSuccess = false,
  className,
  disabled = false
}: CampaignSendButtonProps) {
  const [showErrorTooltip, setShowErrorTooltip] = useState(false);
  const [validationError, setValidationError] = useState(false);

  // Check if we have valid recipients (campaign recipients, list ID, or current query)
  const hasRecipients = !!(recipients || listId || currentQuery);
  const hasContent = !!(body?.trim() && subject?.trim());

  // Only disable when explicitly disabled or pending (not just when missing content)
  // This matches EmailSendButton behavior
  const isDisabled = disabled || isPending;

  // Handle main button click (Schedule Campaign)
  const handleMainClick = () => {
    if (!hasContent) {
      // Trigger error state
      setValidationError(true);
      setShowErrorTooltip(true);

      // Reset after 2 seconds
      setTimeout(() => {
        setValidationError(false);
        setShowErrorTooltip(false);
      }, 2000);

      return;
    }

    if (onSchedule) {
      onSchedule();
    }
  };

  // Campaign buttons always render as split button (no auth variations)
  return (
    <>
      <TooltipProvider>
        <Tooltip open={showErrorTooltip}>
          <TooltipTrigger asChild>
            <div className={cn("inline-flex rounded-md shadow-sm", className)}>
              {/* Main Button - Schedule Campaign */}
              <Button
                onClick={handleMainClick}
                disabled={isDisabled}
                variant="outline"
                className={cn(
                  "h-8 px-3 text-xs border transition-all duration-300 ease-out",
                  // Green theme when there's content, subtle when empty
                  hasContent ? 
                    "bg-green-50 text-green-700 border-green-300 hover:bg-green-600 hover:text-white hover:border-green-600" :
                    "bg-white text-gray-400 border-gray-200 hover:bg-gray-100 hover:text-gray-600 hover:border-gray-300",
                  isSuccess && "bg-pink-500 hover:bg-pink-600 text-white border-pink-500",
                  "rounded-r-none border-r-0",
                  validationError && "shake-animation",
                  // Match EmailSendButton: add opacity-50 only when explicitly disabled
                  disabled && "opacity-50 cursor-not-allowed"
                )}
              >
                {isPending ? (
                  <Loader2 className="w-3 h-3 mr-1 animate-spin" />
                ) : isSuccess ? (
                  <>
                    <Send className="w-3 h-3 mr-1" />
                    Campaign Created
                  </>
                ) : (
                  <>
                    <Send className="w-3 h-3 mr-1" />
                    Schedule Campaign
                  </>
                )}
              </Button>

              {/* Dropdown Button - Shows menu with options */}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    disabled={isDisabled}
                    variant="outline"
                    className={cn(
                      "h-8 px-2 text-xs border transition-all duration-300 ease-out",
                      // Match the main button's green theme
                      hasContent ? 
                        "bg-green-50 text-green-700 border-green-300 hover:bg-green-600 hover:text-white hover:border-green-600" :
                        "bg-white text-gray-400 border-gray-200 hover:bg-gray-100 hover:text-gray-600 hover:border-gray-300",
                      isSuccess && "bg-pink-500 hover:bg-pink-600 text-white border-pink-500",
                      "rounded-l-none border-l",
                      // Match EmailSendButton: add opacity-50 only when explicitly disabled
                      disabled && "opacity-50 cursor-not-allowed"
                    )}
                    aria-label="More campaign options"
                  >
                    <ChevronDown className="w-3 h-3" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-56">
                  <DropdownMenuItem 
                    onClick={onStartNow}
                    className="cursor-pointer"
                    disabled={isPending || !hasRecipients || !hasContent}
                  >
                    <Rocket className="mr-2 h-4 w-4 text-green-600" />
                    Start Now
                  </DropdownMenuItem>
                  <DropdownMenuItem 
                    onClick={onSaveDraft}
                    className="cursor-pointer"
                    disabled={isPending || !hasRecipients || !hasContent}
                  >
                    <FileText className="mr-2 h-4 w-4 text-blue-600" />
                    Save as Draft
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </TooltipTrigger>
          <TooltipContent>
            <p>
              {!hasRecipients 
                ? "Please select campaign recipients" 
                : "Please add content to email body and subject before creating campaign"}
            </p>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    </>
  );
}

client/src/pages/admin/Templates.tsx.content:
import { useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Switch } from '@/components/ui/switch';
import { 
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { 
  FileText,
  Plus,
  Edit,
  Trash,
  ArrowLeft,
  Shield,
  Users
} from 'lucide-react';
import { useAuth } from '@/hooks/use-auth';
import { useLocation } from 'wouter';
import { format } from 'date-fns';
import { useToast } from '@/hooks/use-toast';
import { apiRequest, queryClient } from '@/lib/queryClient';

interface EmailTemplate {
  id: number;
  userId: number;
  name: string;
  subject: string;
  content: string;
  description: string | null;
  category: string | null;
  isDefault: boolean;
  createdAt: string;
  updatedAt: string;
  user?: {
    username: string;
    email: string;
  };
}

export default function AdminTemplates() {
  const { user } = useAuth();
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [editingTemplate, setEditingTemplate] = useState<EmailTemplate | null>(null);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    subject: '',
    content: '',
    description: '',
    category: 'general',
    isDefault: false
  });

  // Fetch all templates
  const { data: templates, isLoading, error } = useQuery<EmailTemplate[]>({
    queryKey: ['/api/admin/templates'],
    enabled: !!user,
  });

  // Create template mutation
  const createMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const response = await apiRequest('POST', '/api/admin/templates', data);
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: 'Template created',
        description: 'New email template has been created successfully',
      });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/templates'] });
      setIsCreateOpen(false);
      setFormData({
        name: '',
        subject: '',
        content: '',
        description: '',
        category: 'general',
        isDefault: false
      });
    },
    onError: (error: any) => {
      toast({
        title: 'Error creating template',
        description: error?.message || 'Failed to create template',
        variant: 'destructive',
      });
    },
  });

  // Update template mutation
  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: number; data: Partial<EmailTemplate> }) => {
      const response = await apiRequest('PATCH', `/api/admin/templates/${id}`, data);
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: 'Template updated',
        description: 'Email template has been updated successfully',
      });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/templates'] });
      setEditingTemplate(null);
    },
    onError: (error: any) => {
      toast({
        title: 'Error updating template',
        description: error?.message || 'Failed to update template',
        variant: 'destructive',
      });
    },
  });

  // Delete template mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      const response = await apiRequest('DELETE', `/api/admin/templates/${id}`);
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: 'Template deleted',
        description: 'Email template has been deleted successfully',
      });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/templates'] });
    },
    onError: (error: any) => {
      toast({
        title: 'Error deleting template',
        description: error?.message || 'Failed to delete template',
        variant: 'destructive',
      });
    },
  });

  // Toggle default status
  const toggleDefault = async (template: EmailTemplate) => {
    updateMutation.mutate({
      id: template.id,
      data: { isDefault: !template.isDefault }
    });
  };

  if (isLoading) {
    return (
      <div className="container mx-auto py-8 px-4">
        <div className="flex items-center justify-center min-h-[400px]">
          <div className="text-center">Loading templates...</div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mx-auto py-8 px-4">
        <Card className="max-w-2xl mx-auto">
          <CardContent className="pt-6">
            <div className="text-center space-y-4">
              <Shield className="h-12 w-12 text-muted-foreground mx-auto" />
              <h3 className="text-lg font-semibold">Access Denied</h3>
              <p className="text-muted-foreground">
                You don't have permission to access this page
              </p>
              <Button onClick={() => setLocation('/')} variant="outline">
                Go Back
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8 px-4">
      {/* Header */}
      <div className="mb-8">
        <Button 
          onClick={() => setLocation('/admin')} 
          variant="ghost" 
          size="sm"
          className="mb-4"
        >
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Admin Dashboard
        </Button>

        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Email Templates</h1>
            <p className="text-muted-foreground mt-2">
              Manage email templates for all users
            </p>
          </div>

          <Button onClick={() => setIsCreateOpen(true)}>
            <Plus className="h-4 w-4 mr-2" />
            Create Template
          </Button>
        </div>
      </div>

      {/* Templates Table */}
      <Card>
        <CardHeader>
          <CardTitle>All Templates</CardTitle>
          <CardDescription>
            {templates?.length || 0} templates total
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Name</TableHead>
                <TableHead>Category</TableHead>
                <TableHead>Type</TableHead>
                <TableHead>Owner</TableHead>
                <TableHead>Created</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {templates?.map((template) => (
                <TableRow key={template.id}>
                  <TableCell className="font-medium">
                    {template.name}
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline">
                      {template.category || 'general'}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    {template.isDefault ? (
                      <Badge className="bg-blue-100 text-blue-800 border-blue-300">
                        <Shield className="w-3 h-3 mr-1" />
                        Default
                      </Badge>
                    ) : (
                      <Badge variant="secondary">
                        <Users className="w-3 h-3 mr-1" />
                        User
                      </Badge>
                    )}
                  </TableCell>
                  <TableCell>
                    {template.user ? template.user.email : `User ${template.userId}`}
                  </TableCell>
                  <TableCell>
                    {format(new Date(template.createdAt), 'MMM d, yyyy')}
                  </TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-2">
                      <Button
                        onClick={() => setEditingTemplate(template)}
                        variant="ghost"
                        size="sm"
                      >
                        <Edit className="h-4 w-4" />
                      </Button>
                      <Button
                        onClick={() => {
                          if (confirm('Are you sure you want to delete this template?')) {
                            deleteMutation.mutate(template.id);
                          }
                        }}
                        variant="ghost"
                        size="sm"
                        className="text-destructive hover:text-destructive"
                      >
                        <Trash className="h-4 w-4" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
              {(!templates || templates.length === 0) && (
                <TableRow>
                  <TableCell colSpan={6} className="text-center py-8 text-muted-foreground">
                    No templates found
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Create Template Dialog */}
      <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Create Email Template</DialogTitle>
            <DialogDescription>
              Create a new email template that can be used by all users
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Template Name</Label>
                <Input
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="e.g., Welcome Email"
                />
              </div>
              <div>
                <Label>Category</Label>
                <Input
                  value={formData.category}
                  onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                  placeholder="e.g., outreach, follow-up"
                />
              </div>
            </div>

            <div>
              <Label>Subject Line</Label>
              <Input
                value={formData.subject}
                onChange={(e) => setFormData({ ...formData, subject: e.target.value })}
                placeholder="Email subject with {merge} fields"
              />
            </div>

            <div>
              <Label>Description</Label>
              <Input
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Brief description of this template"
              />
            </div>

            <div>
              <Label>Content</Label>
              <Textarea
                value={formData.content}
                onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                placeholder="Email content with merge fields like {firstName}, {companyName}, etc."
                className="min-h-[200px]"
              />
            </div>

            <div className="flex items-center space-x-2">
              <Switch
                checked={formData.isDefault}
                onCheckedChange={(checked) => setFormData({ ...formData, isDefault: checked })}
              />
              <Label>Make this a default template (available to all users)</Label>
            </div>

            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setIsCreateOpen(false)}>
                Cancel
              </Button>
              <Button onClick={() => createMutation.mutate(formData)}>
                Create Template
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Edit Template Dialog */}
      {editingTemplate && (
        <Dialog open={!!editingTemplate} onOpenChange={() => setEditingTemplate(null)}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>Edit Template</DialogTitle>
              <DialogDescription>
                Update the email template details
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Template Name</Label>
                  <Input
                    value={editingTemplate.name}
                    onChange={(e) => setEditingTemplate({ ...editingTemplate, name: e.target.value })}
                  />
                </div>
                <div>
                  <Label>Category</Label>
                  <Input
                    value={editingTemplate.category || ''}
                    onChange={(e) => setEditingTemplate({ ...editingTemplate, category: e.target.value })}
                  />
                </div>
              </div>

              <div>
                <Label>Subject Line</Label>
                <Input
                  value={editingTemplate.subject}
                  onChange={(e) => setEditingTemplate({ ...editingTemplate, subject: e.target.value })}
                />
              </div>

              <div>
                <Label>Description</Label>
                <Input
                  value={editingTemplate.description || ''}
                  onChange={(e) => setEditingTemplate({ ...editingTemplate, description: e.target.value })}
                />
              </div>

              <div>
                <Label>Content</Label>
                <Textarea
                  value={editingTemplate.content}
                  onChange={(e) => setEditingTemplate({ ...editingTemplate, content: e.target.value })}
                  className="min-h-[200px]"
                />
              </div>

              <div className="flex items-center space-x-2">
                <Switch
                  checked={editingTemplate.isDefault}
                  onCheckedChange={(checked) => setEditingTemplate({ ...editingTemplate, isDefault: checked })}
                />
                <Label>Default template (available to all users)</Label>
              </div>

              <div className="flex justify-end gap-2">
                <Button variant="outline" onClick={() => setEditingTemplate(null)}>
                  Cancel
                </Button>
                <Button 
                  onClick={() => updateMutation.mutate({ 
                    id: editingTemplate.id, 
                    data: editingTemplate 
                  })}
                >
                  Save Changes
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

