  /**
   * Reject a batch of emails (mark for regeneration)
   */
  async rejectBatch(campaignId: number, recipientIds: number[]): Promise<void> {
    await db
      .update(campaignRecipients)
      .set({
        status: 'queued', // Back to queue for regeneration
        emailContent: null,
