import { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { motion, AnimatePresence } from "framer-motion";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { ArrowRight, X, Sparkles } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import confetti from "canvas-confetti";

type Phase = "A" | "B" | "C";

interface OnboardingData {
  code: string;
  firstName: string;
  lastName: string;
  email: string;
}

interface StealthOnboardingOverlayProps {
  isOpen: boolean;
  onClose: () => void;
  initialCode?: string;
}

export function StealthOnboardingOverlay({ 
  isOpen, 
  onClose,
  initialCode = ""
}: StealthOnboardingOverlayProps) {
  const [phase, setPhase] = useState<Phase>("A");
  const [phaseBStep, setPhaseBStep] = useState<0 | 1>(0);
  const [isMounted, setIsMounted] = useState(false);
  const { toast } = useToast();

  const [data, setData] = useState<OnboardingData>({
    code: initialCode,
    firstName: "",
    lastName: "",
    email: "",
  });

  useEffect(() => {
    setIsMounted(true);
  }, []);

  useEffect(() => {
    if (initialCode) {
      setData(prev => ({ ...prev, code: initialCode }));
    }
  }, [initialCode]);

  useEffect(() => {
    if (phase === "A") {
      setPhaseBStep(0);
    }
  }, [phase]);

  const triggerUnlockEffect = () => {
    const duration = 2000;
    const animationEnd = Date.now() + duration;
    const defaults = { startVelocity: 30, spread: 360, ticks: 60, zIndex: 100 };

    const randomInRange = (min: number, max: number) => Math.random() * (max - min) + min;

    const interval = setInterval(() => {
      const timeLeft = animationEnd - Date.now();

      if (timeLeft <= 0) {
        clearInterval(interval);
        return;
      }

      const particleCount = 50 * (timeLeft / duration);

      confetti({
        ...defaults,
        particleCount,
        origin: { x: randomInRange(0.1, 0.3), y: Math.random() - 0.2 },
        colors: ['#facc15', '#fbbf24', '#f59e0b', '#ffffff'],
      });
      confetti({
        ...defaults,
        particleCount,
        origin: { x: randomInRange(0.7, 0.9), y: Math.random() - 0.2 },
        colors: ['#facc15', '#fbbf24', '#f59e0b', '#ffffff'],
      });
    }, 250);
  };

  const handleCodeSubmit = () => {
    if (data.code.toLowerCase() === "quack") {
      triggerUnlockEffect();

      toast({
        title: "LEVEL UNLOCKED! 🦆",
        description: "Welcome to the inner circle.",
        className: "bg-primary text-primary-foreground border-none font-heading font-bold",
      });

      setTimeout(() => {
        setPhase("B");
      }, 500);
    } else {
      toast({
        title: "WRONG CODE 🚫",
        description: "That's not the secret password!",
        variant: "destructive",
        className: "font-heading font-bold",
      });
    }
  };

  const handleClose = () => {
    setPhase("A");
    setPhaseBStep(0);
    setData({
      code: "",
      firstName: "",
      lastName: "",
      email: "",
    });
    onClose();
  };

  const handlePhaseBContinue = () => {
    if (phaseBStep === 0) {
      if (!data.email) {
        toast({
          title: "Missing Email",
          description: "Please enter your email address.",
          variant: "destructive",
        });
        return;
      }
      setPhaseBStep(1);
    } else {
      if (!data.firstName) {
        toast({
          title: "Missing Name",
          description: "Please enter your first name.",
          variant: "destructive",
        });
        return;
      }
      setPhase("C");
    }
  };

  if (!isMounted || !isOpen) return null;

  return createPortal(
    <>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40"
        transition={{ duration: 0.5 }}
      />

      <motion.button
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.5, delay: 0.3 }}
        onClick={handleClose}
        className="fixed top-6 right-6 z-50 p-2 rounded-full bg-black/60 hover:bg-black/80 transition-colors cursor-pointer"
        data-testid="button-close-overlay"
      >
        <X className="w-6 h-6 text-white/70 hover:text-white" />
      </motion.button>

      <div className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 max-w-md w-full px-4">
        <motion.div
          layout
          className="relative overflow-hidden"
          transition={{ duration: 0.5, ease: "easeInOut" }}
        >
          <div className="relative flex-1 group/input flex flex-col gap-4">
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="absolute inset-0 bg-blue-500/20 blur-xl rounded-lg z-0"
            />

            <AnimatePresence>
              {phase === "B" && (
                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.4 }}
                  className="flex items-center gap-2 justify-center relative z-10"
                >
                  <Sparkles className="w-5 h-5 text-yellow-400" />
                  <span className="text-yellow-400 font-bold uppercase tracking-widest text-sm">Access Granted</span>
                  <Sparkles className="w-5 h-5 text-yellow-400" />
                </motion.div>
              )}
            </AnimatePresence>

            <div className="relative flex items-center">
              <Input 
                type="text" 
                placeholder="ENTER_SECRET_CODE" 
                className="h-16 bg-black border-none text-xl md:text-2xl pl-8 pr-16 rounded-none focus-visible:ring-0 focus-visible:ring-offset-0 placeholder:text-white/40 font-code tracking-widest uppercase text-white w-full relative z-10 transition-all duration-500 text-center shadow-[0_0_30px_rgba(59,130,246,0.3)]"
                value={data.code}
                onChange={(e) => setData(prev => ({ ...prev, code: e.target.value }))}
                onKeyDown={(e) => e.key === "Enter" && data.code.length >= 5 && phase === "A" && handleCodeSubmit()}
                autoFocus={phase === "A"}
                disabled={phase !== "A"}
                data-testid="input-secret-code-overlay"
              />

              <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-white/60 group-focus-within/input:border-white transition-colors pointer-events-none z-10" />
              <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-white/60 group-focus-within/input:border-white transition-colors pointer-events-none z-10" />
              <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-white/60 group-focus-within/input:border-white transition-colors pointer-events-none z-10" />
              <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-white/60 group-focus-within/input:border-white transition-colors pointer-events-none z-10" />

              <AnimatePresence>
                {data.code.length >= 5 && phase === "A" && (
                  <motion.div
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.8 }}
                    transition={{ type: "spring", stiffness: 300, damping: 25 }}
                    className="absolute right-3 z-20"
                  >
                    <Button 
                      size="icon" 
                      className="h-10 w-10 rounded-md bg-gray-700 text-white hover:bg-gray-600 hover:scale-105 active:scale-95 transition-all flex items-center justify-center"
                      onClick={handleCodeSubmit}
                      data-testid="button-submit-code"
                    >
                      <ArrowRight className="w-5 h-5" />
                    </Button>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>

            <AnimatePresence mode="wait">
              {phase === "B" && phaseBStep === 0 && (
                <motion.div
                  key="step-email"
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  transition={{ duration: 0.5, ease: "easeOut" }}
                  className="overflow-hidden"
                >
                  <motion.div
                    initial={{ y: 20, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ delay: 0.2, duration: 0.4 }}
                    className="space-y-4 pt-4"
                  >
                    <motion.div
                      initial={{ y: 20, opacity: 0 }}
                      animate={{ y: 0, opacity: 1 }}
                      transition={{ delay: 0.3, duration: 0.4 }}
                    >
                      <Input
                        type="email"
                        placeholder="Email Address"
                        value={data.email}
                        onChange={(e) => setData(prev => ({ ...prev, email: e.target.value }))}
                        onKeyDown={(e) => e.key === "Enter" && data.email && handlePhaseBContinue()}
                        className="h-12 bg-black/80 border border-white/20 rounded-lg text-white placeholder:text-white/40 focus-visible:ring-1 focus-visible:ring-white/50 focus-visible:border-white/50"
                        autoFocus
                        data-testid="input-email"
                      />
                    </motion.div>

                    <motion.div
                      initial={{ y: 20, opacity: 0 }}
                      animate={{ y: 0, opacity: 1 }}
                      transition={{ delay: 0.4, duration: 0.4 }}
                      className="pt-2"
                    >
                      <Button
                        onClick={handlePhaseBContinue}
                        className="w-full h-12 bg-gray-700 hover:bg-gray-600 text-white font-bold uppercase tracking-widest transition-all hover:scale-[1.02] active:scale-[0.98]"
                        data-testid="button-continue"
                      >
                        Continue <ArrowRight className="w-4 h-4 ml-2" />
                      </Button>
                    </motion.div>
                  </motion.div>
                </motion.div>
              )}

              {phase === "B" && phaseBStep === 1 && (
                <motion.div
                  key="step-name"
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  transition={{ duration: 0.5, ease: "easeOut" }}
                  className="overflow-hidden"
                >
                  <motion.div
                    initial={{ y: 20, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ delay: 0.2, duration: 0.4 }}
                    className="space-y-4 pt-4"
                  >
                    <div className="grid grid-cols-2 gap-3">
                      <motion.div
                        initial={{ x: -20, opacity: 0 }}
                        animate={{ x: 0, opacity: 1 }}
                        transition={{ delay: 0.3, duration: 0.4 }}
                      >
                        <Input
                          type="text"
                          placeholder="First Name"
                          value={data.firstName}
                          onChange={(e) => setData(prev => ({ ...prev, firstName: e.target.value }))}
                          className="h-12 bg-black/80 border border-white/20 rounded-lg text-white placeholder:text-white/40 focus-visible:ring-1 focus-visible:ring-white/50 focus-visible:border-white/50"
                          autoFocus
                          data-testid="input-first-name"
                        />
                      </motion.div>
                      <motion.div
                        initial={{ x: 20, opacity: 0 }}
                        animate={{ x: 0, opacity: 1 }}
                        transition={{ delay: 0.4, duration: 0.4 }}
                      >
                        <Input
                          type="text"
                          placeholder="Last Name"
                          value={data.lastName}
                          onChange={(e) => setData(prev => ({ ...prev, lastName: e.target.value }))}
                          className="h-12 bg-black/80 border border-white/20 rounded-lg text-white placeholder:text-white/40 focus-visible:ring-1 focus-visible:ring-white/50 focus-visible:border-white/50"
                          data-testid="input-last-name"
                        />
                      </motion.div>
                    </div>

                    <motion.div
                      initial={{ y: 20, opacity: 0 }}
                      animate={{ y: 0, opacity: 1 }}
                      transition={{ delay: 0.5, duration: 0.4 }}
                      className="pt-2"
                    >
                      <Button
                        onClick={handlePhaseBContinue}
                        className="w-full h-12 bg-gray-700 hover:bg-gray-600 text-white font-bold uppercase tracking-widest transition-all hover:scale-[1.02] active:scale-[0.98]"
                        data-testid="button-continue"
                      >
                        Continue <ArrowRight className="w-4 h-4 ml-2" />
                      </Button>
                    </motion.div>
                  </motion.div>
                </motion.div>
              )}
            </AnimatePresence>

            {phase === "C" && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="text-center text-white/60 py-8"
              >
                <p className="text-lg">Phase C - Questionnaire coming soon...</p>
                <p className="text-sm mt-2">User: {data.firstName} {data.lastName}</p>
                <p className="text-sm">Email: {data.email}</p>
              </motion.div>
            )}
          </div>
        </motion.div>

        {phase === "A" && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="w-full text-center mt-24"
          >
            <Button 
              variant="link" 
              className="text-white/60 hover:text-white transition-colors font-code uppercase tracking-widest text-sm no-underline hover:no-underline cursor-pointer" 
              data-testid="link-apply-code"
            >
              Apply for a code <ArrowRight className="w-4 h-4 ml-2" />
            </Button>
          </motion.div>
        )}
      </div>
    </>,
    document.body
  );
}

export default StealthOnboardingOverlay;

