import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { createPortal } from "react-dom";
import { useLocation } from "wouter";
import { Trophy, Play, X, Circle, Pointer, Sparkles, ChevronLeft } from "lucide-react";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { ChallengeRecorder } from "./ChallengeRecorder";
import type { FluffyGuideProps } from "../types";

interface ExtendedFluffyGuideProps extends FluffyGuideProps {
  onCloseGuide?: () => void;
  starterMode?: boolean;
  onShowMeMode?: () => void;
  onGuideMeMode?: () => void;
  onStarterDismiss?: () => void;
}

export function FluffyGuide({ 
  onClick, 
  isActive, 
  onCloseGuide,
  starterMode = false,
  onShowMeMode,
  onGuideMeMode,
  onStarterDismiss,
}: ExtendedFluffyGuideProps) {
  console.log('[FluffyGuide] render:', { isActive, starterMode });

  const [showMenu, setShowMenu] = useState(false);
  const [shouldWiggle, setShouldWiggle] = useState(false);
  const [showRecorder, setShowRecorder] = useState(false);
  const [showGettingStarted, setShowGettingStarted] = useState(false);
  const [, navigate] = useLocation();

  useEffect(() => {
    if (starterMode) {
      setShowMenu(true);
      setShowGettingStarted(true);
    }
  }, [starterMode]);

  useEffect(() => {
    const triggerWiggle = () => {
      setShouldWiggle(true);
      setTimeout(() => setShouldWiggle(false), 1500);
    };

    const interval = setInterval(triggerWiggle, 180000);
    return () => clearInterval(interval);
  }, []);

  const handleClick = () => {
    if (isActive) {
      onClick?.();
    } else {
      setShowMenu(!showMenu);
    }
  };

  const handleViewQuests = () => {
    setShowMenu(false);
    navigate("/quests");
  };

  const handleStartQuest = () => {
    setShowMenu(false);
    onClick?.();
  };

  const handleCloseGuide = () => {
    setShowMenu(false);
    onCloseGuide?.();
  };

  const handleRecordChallenge = () => {
    setShowMenu(false);
    setShowRecorder(true);
  };

  const handleMenuClose = () => {
    if (starterMode) {
      onStarterDismiss?.();
    }
    setShowMenu(false);
    setShowGettingStarted(false);
  };

  const handleGettingStartedClick = () => {
    setShowGettingStarted(true);
  };

  const handleBackToMenu = () => {
    setShowGettingStarted(false);
  };

  const handleShowMe = () => {
    setShowMenu(false);
    setShowGettingStarted(false);
    onShowMeMode?.();
  };

  const handleGuideMe = () => {
    setShowMenu(false);
    setShowGettingStarted(false);
    onGuideMeMode?.();
  };

  const handleNotNow = () => {
    setShowMenu(false);
    setShowGettingStarted(false);
    onStarterDismiss?.();
  };

  const isMenuVisible = showMenu || starterMode;

  return createPortal(
    <div data-recorder-ui="true">
      {!isActive && (
        <>
          <AnimatePresence>
            {isMenuVisible && (
              <motion.div
