            }}
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.95 }}
          >
            <span className="text-xl">{isMenuVisible ? "😊" : "🐥"}</span>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, x: 10 }}
