import { Button } from "@/components/ui/button";
import { fireTouchConfetti, animateCreditSparkles, AutoDismissBar } from "@/features/animations";

interface ChallengeCompleteProps {
  isVisible: boolean;
  challengeName: string;
  message?: string;
  creditsAwarded?: number;
  onContinue: () => void;
  onDismiss: () => void;
}

export function ChallengeComplete({
  isVisible,
  challengeName,
  message,
  creditsAwarded,
  onContinue,
  onDismiss,
}: ChallengeCompleteProps) {
  const creditsBadgeRef = useRef<HTMLDivElement>(null);
  const [isHovered, setIsHovered] = useState(false);

  useEffect(() => {
    if (isVisible) {
      fireTouchConfetti();

      if (creditsAwarded && creditsAwarded > 0) {
        const sparkleTimer = setTimeout(() => {
          animateCreditSparkles(creditsBadgeRef.current);
        }, 800);

        return () => clearTimeout(sparkleTimer);
      }
    }
  }, [isVisible, creditsAwarded]);

  return createPortal(
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[10000] flex items-center justify-center bg-black/60 backdrop-blur-sm"
          onClick={onDismiss}
          data-recorder-ui="true"
        >
          <motion.div
            initial={{ scale: 0.5, opacity: 0, y: 50 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.5, opacity: 0, y: 50 }}
            transition={{ type: "spring", stiffness: 300, damping: 25 }}
            className="bg-gradient-to-br from-gray-900 to-gray-800 rounded-2xl p-8 max-w-md mx-4 text-center border border-yellow-500/30 shadow-2xl"
            onClick={(e) => e.stopPropagation()}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
          >
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: [0, 1.2, 1] }}
              transition={{ delay: 0.2, duration: 0.5 }}
              className="w-20 h-20 mx-auto mb-4 rounded-full bg-gradient-to-br from-yellow-400 to-amber-500 flex items-center justify-center shadow-lg"
            >
              <Trophy className="h-10 w-10 text-white" />
            </motion.div>

            <motion.h2
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3 }}
              className="text-2xl font-bold text-white mb-2"
            >
              Challenge Complete!
            </motion.h2>

            <motion.p
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.4 }}
              className="text-yellow-400 font-medium mb-3"
            >
              {challengeName}
            </motion.p>

            {message && (
              <motion.p
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.5 }}
                className="text-gray-300 text-sm mb-4"
              >
                {message}
              </motion.p>
            )}

            {creditsAwarded && creditsAwarded > 0 && (
              <motion.div
                ref={creditsBadgeRef}
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: 0.55, type: "spring", stiffness: 400, damping: 20 }}
                className="flex items-center justify-center gap-2 bg-gradient-to-r from-amber-500/20 to-yellow-500/20 border border-amber-500/30 rounded-full px-4 py-2 mb-6"
                data-testid="credits-badge"
              >
                <Coins className="h-5 w-5 text-amber-400" />
                <span className="text-amber-400 font-semibold">+{creditsAwarded} Credits Earned!</span>
              </motion.div>
            )}

            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.6 }}
              className="flex gap-3 justify-center"
            >
              <Button
                variant="ghost"
                onClick={onDismiss}
                className="text-gray-400 hover:text-white"
