            </motion.div>

            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.7 }}
              className="mt-6"
            >
              <AutoDismissBar
                duration={5000}
                onComplete={onDismiss}
                isPaused={isHovered}
                isVisible={isVisible}
                showCountdown={true}
                countdownLabel="Closing in"
              />
            </motion.div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>,
    document.body
  );
}

