      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1 }}
      >
        {slide.inputType === "textarea" ? (
          <Textarea
            value={value}
            onChange={(e) => onTextInput?.(slide.id, e.target.value)}
            placeholder={slide.placeholder}
