              </AnimatePresence>
            </div>
          </div>

          {/* Mobile: Accordion layout */}
          <div className="md:hidden space-y-4">
            {tabs.map((tab, index) => {
              const Icon = tab.icon;
              const isActive = index === activeTab;
              const Graphic = tab.graphic;

              return (
                <motion.div
                  key={tab.id}
