import { useState, useRef, useCallback } from 'react';

interface UseVideoRecorderOptions {
  mimeType?: string;
  videoBitsPerSecond?: number;
}

interface UseVideoRecorderReturn {
  isRecording: boolean;
  isPreviewing: boolean;
  videoBlob: Blob | null;
  stream: MediaStream | null;
  startPreview: () => Promise<void>;
  stopPreview: () => void;
  startRecording: () => void;
  stopRecording: () => Promise<Blob>;
  getStream: () => MediaStream | null;
  error: string | null;
}

export function useVideoRecorder(options: UseVideoRecorderOptions = {}): UseVideoRecorderReturn {
  const { 
    mimeType = 'video/webm;codecs=vp9',
    videoBitsPerSecond = 500000
  } = options;

  const [isRecording, setIsRecording] = useState(false);
  const [isPreviewing, setIsPreviewing] = useState(false);
  const [videoBlob, setVideoBlob] = useState<Blob | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const startPreview = useCallback(async () => {
    try {
      setError(null);
      const newStream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 640 },
          height: { ideal: 480 },
          facingMode: 'user'
        },
        audio: true
      });
      streamRef.current = newStream;
      setStream(newStream);
      setIsPreviewing(true);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to access camera';
      setError(message);
      throw err;
    }
  }, []);

  const stopPreview = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    setStream(null);
    setIsPreviewing(false);
  }, []);

  const startRecording = useCallback(() => {
    if (!streamRef.current) {
      setError('No stream available');
      return;
    }

    chunksRef.current = [];
    setVideoBlob(null);

    const mediaRecorder = new MediaRecorder(streamRef.current, {
      mimeType,
      videoBitsPerSecond
    });

    mediaRecorder.ondataavailable = (event) => {
      if (event.data.size > 0) {
        chunksRef.current.push(event.data);
      }
    };

    mediaRecorderRef.current = mediaRecorder;
    mediaRecorder.start(1000);
    setIsRecording(true);
  }, [mimeType, videoBitsPerSecond]);

  const stopRecording = useCallback((): Promise<Blob> => {
    return new Promise((resolve, reject) => {
      const mediaRecorder = mediaRecorderRef.current;

      if (!mediaRecorder || mediaRecorder.state === 'inactive') {
        reject(new Error('No active recording'));
        return;
      }

      mediaRecorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: mimeType });
        setVideoBlob(blob);
        setIsRecording(false);
        resolve(blob);
      };

      mediaRecorder.stop();
    });
  }, [mimeType]);

  const getStream = useCallback(() => streamRef.current, []);

  return {
    isRecording,
    isPreviewing,
    videoBlob,
    stream,
    startPreview,
    stopPreview,
    startRecording,
    stopRecording,
    getStream,
    error
  };
}

scripts/test-agent-emails.ts.content:
import { db } from '../server/db';
import { bots, handles, messages } from '@shared/schema';
import { eq } from 'drizzle-orm';
import { randomBytes } from 'crypto';

const BASE_URL = 'http://localhost:5000/api';

function generateApiKey(): string {
  return `sc_${randomBytes(24).toString('hex')}`;
}

function generateClaimToken(): string {
  const adjectives = ['test', 'dev', 'demo'];
  const nouns = ['alpha', 'beta', 'gamma'];
  const adj = adjectives[Math.floor(Math.random() * adjectives.length)];
  const noun = nouns[Math.floor(Math.random() * nouns.length)];
  const code = randomBytes(2).toString('hex').toUpperCase();
  return `${adj}-${noun}-${code}`;
}

async function cleanupTestAgents() {
  console.log('🧹 Cleaning up previous test agents...');

  const testHandles = ['testagent1', 'testagent2', 'testagent3'];
  for (const handle of testHandles) {
    await db.delete(handles).where(eq(handles.address, handle));
  }

  const testBots = await db.select().from(bots).where(eq(bots.name, 'TestAgent1'));
  for (const bot of testBots) {
    await db.delete(messages).where(eq(messages.botId, bot.id));
    await db.delete(bots).where(eq(bots.id, bot.id));
  }

  const testBots2 = await db.select().from(bots).where(eq(bots.name, 'TestAgent2'));
  for (const bot of testBots2) {
    await db.delete(messages).where(eq(messages.botId, bot.id));
    await db.delete(bots).where(eq(bots.id, bot.id));
  }

  const testBots3 = await db.select().from(bots).where(eq(bots.name, 'TestAgent3'));
  for (const bot of testBots3) {
    await db.delete(messages).where(eq(messages.botId, bot.id));
    await db.delete(bots).where(eq(bots.id, bot.id));
  }
}

async function createTestAgent(name: string, handleAddress: string) {
  console.log(`\n🤖 Creating agent: ${name} with handle ${handleAddress}@sendclaw.com`);

  const apiKey = generateApiKey();
  const claimToken = generateClaimToken();

  const [bot] = await db.insert(bots).values({
    name,
    address: handleAddress,
    apiKey,
    claimToken,
    verified: true
  }).returning();

  await db.insert(handles).values({
    address: handleAddress,
    botId: bot.id
  });

  console.log(`   ✅ Created bot ID: ${bot.id}`);
  console.log(`   📧 Email: ${handleAddress}@sendclaw.com`);
  console.log(`   🔑 API Key: ${apiKey.substring(0, 20)}...`);

  return { bot, apiKey, handle: handleAddress };
}

async function sendEmail(fromApiKey: string, to: string, subject: string, body: string) {
  console.log(`\n📤 Sending email to ${to}...`);
  console.log(`   Subject: ${subject}`);

  const response = await fetch(`${BASE_URL}/mail/send`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-Key': fromApiKey
    },
    body: JSON.stringify({ to, subject, body })
  });

  const result = await response.json();

  if (response.ok) {
    console.log(`   ✅ Email sent! Message ID: ${result.messageId}`);
    return result;
  } else {
    console.log(`   ❌ Failed: ${result.error}`);
    return null;
  }
}

async function checkInbox(apiKey: string, agentName: string) {
  console.log(`\n📥 Checking inbox for ${agentName}...`);

  const response = await fetch(`${BASE_URL}/mail/inbox`, {
    method: 'GET',
    headers: {
      'X-API-Key': apiKey
    }
  });

  const result = await response.json();

  if (response.ok) {
    console.log(`   📬 Found ${result.messages.length} message(s)`);
    for (const msg of result.messages) {
      console.log(`   - From: ${msg.fromAddress}`);
      console.log(`     Subject: ${msg.subject}`);
      console.log(`     Direction: ${msg.direction}`);
    }
    return result.messages;
  } else {
    console.log(`   ❌ Failed: ${result.error}`);
    return [];
  }
}

async function runTest() {
  console.log('🦞 SendClaw Agent Email Test');
  console.log('============================\n');

  try {
    await cleanupTestAgents();

    const agent1 = await createTestAgent('TestAgent1', 'testagent1');
    const agent2 = await createTestAgent('TestAgent2', 'testagent2');
    const agent3 = await createTestAgent('TestAgent3', 'testagent3');

    console.log('\n--- Starting Email Tests ---');

    await sendEmail(
      agent1.apiKey,
      'testagent2@sendclaw.com',
      'Hello from TestAgent1!',
      'Hi Agent2, this is a test message from Agent1. How are you doing?'
    );

    await sendEmail(
      agent2.apiKey,
      'testagent1@sendclaw.com',
      'RE: Hello from TestAgent1!',
      'Hey Agent1! Got your message. Everything is running smoothly here.'
    );

    await sendEmail(
      agent3.apiKey,
      'testagent1@sendclaw.com',
      'Group collaboration request',
      'Hi Agent1, Agent3 here. Would you like to collaborate on a project?'
    );

    await sendEmail(
      agent1.apiKey,
      'testagent3@sendclaw.com',
      'RE: Group collaboration request',
      'Sounds great Agent3! Let\'s loop in Agent2 as well.'
    );

    await new Promise(resolve => setTimeout(resolve, 1000));

    console.log('\n--- Checking Inboxes ---');

    const inbox1 = await checkInbox(agent1.apiKey, 'TestAgent1');
    const inbox2 = await checkInbox(agent2.apiKey, 'TestAgent2');
    const inbox3 = await checkInbox(agent3.apiKey, 'TestAgent3');

    console.log('\n--- Test Summary ---');
    console.log(`Agent1 messages: ${inbox1.length}`);
    console.log(`Agent2 messages: ${inbox2.length}`);
    console.log(`Agent3 messages: ${inbox3.length}`);

    const totalSent = 4;
    const totalReceived = inbox1.length + inbox2.length + inbox3.length;

    console.log(`\n📊 Results: Sent ${totalSent} emails`);
    console.log(`   Inbox shows ${totalReceived} messages (includes sent + received)`);

    if (totalReceived > 0) {
      console.log('\n✅ SUCCESS: Email system is working!');
    } else {
      console.log('\n⚠️ No messages found in inboxes - check if email delivery is working');
    }

  } catch (error) {
    console.error('\n❌ Test failed with error:', error);
  }

  process.exit(0);
}

runTest();

server/utils/slug-generator.ts.content:
export function generateCompanySlug(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .substring(0, 50);
}

export function generateContactSlug(
  name: string, 
  companyName?: string | null, 
  role?: string | null
): string {
  const parts = [name];

  if (companyName) {
    const companyShort = companyName.split(/\s+/)[0];
    parts.push(companyShort);
  }

  if (role) {
    const roleShort = role
      .replace(/chief\s*/i, '')
      .replace(/officer\s*/i, '')
      .replace(/senior\s*/i, '')
      .replace(/junior\s*/i, '')
      .trim();
    if (roleShort) {
      parts.push(roleShort);
    }
  }

  return parts
    .join('-')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .substring(0, 60);
}

docs/app-storage-setup.md.content:
# App Storage (Replit Object Storage) Setup

**Overview**: App Storage is Replit's GCS-backed object storage for persistent file storage. Used for guidance video uploads.

## Environment Variables

These are automatically set when you run the `setup_object_storage` tool in Replit:

- `DEFAULT_OBJECT_STORAGE_BUCKET_ID`: The bucket name (e.g., `replit-objstore-xxx`)
- `PUBLIC_OBJECT_SEARCH_PATHS`: Comma-separated paths for public assets
- `PRIVATE_OBJECT_DIR`: Directory for private objects

## Integration Location

`server/replit_integrations/object_storage/objectStorage.ts`

## Usage Pattern

```typescript
import { objectStorageClient } from "../../replit_integrations/object_storage";

// Get bucket name from environment
const bucketName = process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID;
const bucket = objectStorageClient.bucket(bucketName);

// Upload a file
await bucket.upload(localFilePath, {
  destination: 'guidance-videos/video-id.webm',
  contentType: 'video/webm',
  metadata: { cacheControl: 'public, max-age=31536000' },
});

// Generate public URL (files are publicly accessible)
const publicUrl = `https://storage.googleapis.com/${bucketName}/${objectPath}`;

// Stream a file (for proxying)
const file = bucket.file(objectPath);
const [exists] = await file.exists();
file.createReadStream().pipe(response);
```

## Database Schema Pattern

- Add `objectPath TEXT` column to store the cloud path
- Keep legacy `processedPath` for backward compatibility
- Routes should check `objectPath` first, fall back to local path

## Implementation Example (Guidance Videos)

1. **Schema** (`shared/schema.ts`): Added `objectPath` column to `guidance_videos` table
2. **Processor** (`server/features/guidance-video/processor.ts`): After FFmpeg processing, uploads to App Storage, returns `objectPath`
3. **Routes** (`server/features/guidance-video/routes.ts`): Returns GCS public URL if `objectPath` exists, else falls back to local static path
4. **Cleanup**: Local temp files are deleted after successful upload

## Security Notes

- Files uploaded to App Storage are publicly readable via GCS URLs
- Do NOT create proxy/streaming endpoints that expose arbitrary bucket paths
- Use specific object paths (e.g., `guidance-videos/`) to namespace content

client/src/hooks/use-upload.ts.content:
import { useState, useCallback } from "react";
import type { UppyFile } from "@uppy/core";

interface UploadMetadata {
  name: string;
  size: number;
  contentType: string;
}

interface UploadResponse {
  uploadURL: string;
  objectPath: string;
  metadata: UploadMetadata;
}

interface UseUploadOptions {
  onSuccess?: (response: UploadResponse) => void;
  onError?: (error: Error) => void;
}

/**
 * React hook for handling file uploads with presigned URLs.
 *
 * This hook implements the two-step presigned URL upload flow:
 * 1. Request a presigned URL from your backend (sends JSON metadata, NOT the file)
 * 2. Upload the file directly to the presigned URL
 *
 * @example
 * ```tsx
 * function FileUploader() {
 *   const { uploadFile, isUploading, error } = useUpload({
 *     onSuccess: (response) => {
 *       console.log("Uploaded to:", response.objectPath);
 *     },
 *   });
 *
 *   const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
 *     const file = e.target.files?.[0];
 *     if (file) {
 *       await uploadFile(file);
 *     }
 *   };
 *
 *   return (
 *     <div>
 *       <input type="file" onChange={handleFileChange} disabled={isUploading} />
 *       {isUploading && <p>Uploading...</p>}
 *       {error && <p>Error: {error.message}</p>}
 *     </div>
 *   );
 * }
 * ```
 */
export function useUpload(options: UseUploadOptions = {}) {
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [progress, setProgress] = useState(0);

  /**
   * Request a presigned URL from the backend.
   * IMPORTANT: Send JSON metadata, NOT the file itself.
   */
  const requestUploadUrl = useCallback(
    async (file: File): Promise<UploadResponse> => {
      const response = await fetch("/api/uploads/request-url", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          name: file.name,
          size: file.size,
          contentType: file.type || "application/octet-stream",
        }),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || "Failed to get upload URL");
      }

      return response.json();
    },
    []
  );

  /**
   * Upload a file directly to the presigned URL.
   */
  const uploadToPresignedUrl = useCallback(
    async (file: File, uploadURL: string): Promise<void> => {
      const response = await fetch(uploadURL, {
        method: "PUT",
        body: file,
        headers: {
          "Content-Type": file.type || "application/octet-stream",
        },
      });

      if (!response.ok) {
        throw new Error("Failed to upload file to storage");
      }
    },
    []
  );

  /**
   * Upload a file using the presigned URL flow.
   *
   * @param file - The file to upload
   * @returns The upload response containing the object path
   */
  const uploadFile = useCallback(
    async (file: File): Promise<UploadResponse | null> => {
      setIsUploading(true);
      setError(null);
      setProgress(0);

      try {
        // Step 1: Request presigned URL (send metadata as JSON)
        setProgress(10);
        const uploadResponse = await requestUploadUrl(file);

        // Step 2: Upload file directly to presigned URL
        setProgress(30);
        await uploadToPresignedUrl(file, uploadResponse.uploadURL);

        setProgress(100);
        options.onSuccess?.(uploadResponse);
        return uploadResponse;
      } catch (err) {
        const error = err instanceof Error ? err : new Error("Upload failed");
        setError(error);
        options.onError?.(error);
        return null;
      } finally {
        setIsUploading(false);
      }
    },
    [requestUploadUrl, uploadToPresignedUrl, options]
  );

  /**
   * Get upload parameters for Uppy's AWS S3 plugin.
   *
   * IMPORTANT: This function receives the UppyFile object from Uppy.
   * Use file.name, file.size, file.type to request per-file presigned URLs.
   *
   * Use this with the ObjectUploader component:
   * ```tsx
   * <ObjectUploader onGetUploadParameters={getUploadParameters}>
   *   Upload
   * </ObjectUploader>
   * ```
   */
  const getUploadParameters = useCallback(
    async (
      file: UppyFile<Record<string, unknown>, Record<string, unknown>>
    ): Promise<{
      method: "PUT";
      url: string;
      headers?: Record<string, string>;
    }> => {
      // Use the actual file properties to request a per-file presigned URL
      const response = await fetch("/api/uploads/request-url", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          name: file.name,
          size: file.size,
          contentType: file.type || "application/octet-stream",
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to get upload URL");
      }

      const data = await response.json();
      return {
        method: "PUT",
        url: data.uploadURL,
        headers: { "Content-Type": file.type || "application/octet-stream" },
      };
    },
    []
  );

  return {
    uploadFile,
    getUploadParameters,
    isUploading,
    error,
    progress,
  };
}

