                  >
                    <Pencil className="w-4 h-4 mr-1" />
                    Edit
                  </Button>
                )}
              </div>
              <CardDescription>
                {hasHandle ? "Your SendClaw email identity" : "Reserve your @sendclaw.com handle"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {hasHandle && !isEditingHandle ? (
                <div className="space-y-3">
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Email Address</p>
                    <div className="flex items-center justify-between p-3 bg-muted rounded-lg">
                      <span className="font-medium text-foreground">{userHandle.address}</span>
                      <button 
                        onClick={() => copyToClipboard(userHandle.address, 'address')}
                        className="text-muted-foreground hover:text-primary p-2"
                      >
                        {copied === 'address' ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                      </button>
                    </div>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Sender Name</p>
                    <div className="p-3 bg-muted rounded-lg">
                      <span className="font-medium text-foreground">
                        {userHandle.senderName || <span className="text-muted-foreground italic">Not set</span>}
                      </span>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="space-y-4">
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Email Address</p>
                    <div className="flex items-center gap-2 bg-muted rounded-lg px-3">
                      <Input
                        value={handle}
                        onChange={(e) => setHandle(e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, ''))}
                        placeholder="yourname"
                        className="bg-transparent border-0 focus-visible:ring-0"
                        disabled={!!userHandle}
                      />
                      <span className="text-muted-foreground whitespace-nowrap">@sendclaw.com</span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-1">
                      {userHandle 
                        ? "Email handles cannot be changed once reserved."
                        : "Letters, numbers, and underscores only. Min 3 characters."}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Sender Name</p>
                    <Input
                      value={handleSenderName}
                      onChange={(e) => setHandleSenderName(e.target.value)}
                      placeholder="e.g., John Smith"
                      className="bg-muted"
                    />
                    <p className="text-xs text-muted-foreground mt-1">
                      This is what recipients see as the "From" name.
                    </p>
                  </div>
                  <div className="flex gap-2">
                    <Button 
                      onClick={() => {
                        if (userHandle) {
                          // Existing handle - update sender name only
                          const newName = handleSenderName.trim();
                          const originalName = userHandle.senderName || "";
                          if (newName && newName !== originalName) {
                            handleSenderNameMutation.mutate({ 
                              handleId: userHandle.id, 
                              senderName: newName 
                            }, {
                              onSuccess: () => setIsEditingHandle(false)
                            });
                          } else if (!newName) {
                            toast({
                              title: "Sender name required",
                              description: "Please enter a sender name",
                              variant: "destructive",
                            });
                          } else {
                            // No changes made, just close
                            setIsEditingHandle(false);
                          }
                        } else if (handle.trim().length >= 3) {
                          // New handle - create reservation
                          reserveMutation.mutate(handle.trim());
                        }
                      }}
                      disabled={
                        userHandle 
                          ? handleSenderNameMutation.isPending
                          : (handle.length < 3 || reserveMutation.isPending)
                      }
                      className="flex-1"
                    >
                      <Save className="w-4 h-4 mr-2" />
                      {reserveMutation.isPending || handleSenderNameMutation.isPending ? "Saving..." : "Save"}
                    </Button>
                    {isEditingHandle && (
                      <Button 
                        variant="outline"
                        onClick={() => {
                          setIsEditingHandle(false);
                          setHandle("");
                          setHandleSenderName("");
                        }}
                      >
                        Cancel
                      </Button>
                    )}
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <Bot className="w-5 h-5 text-primary" />
                <CardTitle className="text-lg">Bot Connection</CardTitle>
              </div>
              <CardDescription>
                {hasBot ? "Your linked AI bot" : "Connect an AI bot to send emails"}
              </CardDescription>
            </CardHeader>
            <CardContent>
              {hasBot ? (
                <div className="space-y-3">
                  <div className="flex items-center justify-between p-3 bg-muted rounded-lg">
                    <div>
                      <p className="font-medium text-foreground">{userBot.name}</p>
                      <p className="text-sm text-muted-foreground">
                        Claimed {userBot.claimedAt ? new Date(userBot.claimedAt).toLocaleDateString() : 'recently'}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      {isLinked && (
                        <Badge variant="outline" className="bg-blue-50 text-blue-700 border-blue-200">
                          <Link2 className="w-3 h-3 mr-1" />
                          Linked
                        </Badge>
                      )}
                      {userBot.verified && (
                        <Badge variant="outline" className="bg-green-50 text-green-700 border-green-200">
                          <Shield className="w-3 h-3 mr-1" />
                          Verified
                        </Badge>
                      )}
                    </div>
                  </div>
                  {!isLinked && hasHandle && (
                    <p className="text-sm text-amber-600 bg-amber-50 p-2 rounded">
                      Bot is claimed but not linked to your handle. This may happen if you reserved the handle after claiming.
                    </p>
                  )}
                </div>
              ) : (
                <div className="space-y-3">
                  <Input
                    value={claimToken}
                    onChange={(e) => setClaimToken(e.target.value)}
                    placeholder="Enter claim token (e.g. reef-X4B2)"
                    onKeyDown={(e) => e.key === "Enter" && handleClaim()}
                  />
                  <p className="text-xs text-muted-foreground">
                    Your AI bot provides this token when it registers via the API.
                  </p>
                  <Button 
                    onClick={handleClaim}
                    disabled={!claimToken.trim() || claimMutation.isPending}
                    className="w-full"
                  >
                    {claimMutation.isPending ? "Claiming..." : "Claim Bot"}
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <Key className="w-5 h-5 text-primary" />
                <CardTitle className="text-lg">API for Agents / Bots</CardTitle>
              </div>
                <CardDescription>
                  Your bot uses this key to authenticate with the SendClaw API
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">API Key</p>
                    <div className="flex items-center justify-between p-3 bg-muted rounded-lg">
                      {userBot?.apiKey ? (
                        <>
                          <code className="text-sm font-mono text-foreground">
                            {showApiKey ? userBot.apiKey : `${userBot.apiKey.slice(0, 8)}${'•'.repeat(24)}`}
                          </code>
                          <div className="flex items-center gap-1">
                            <button
                              onClick={() => setShowApiKey(!showApiKey)}
                              className="text-muted-foreground hover:text-primary p-2"
                            >
                              {showApiKey ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                            </button>
                            <button
                              onClick={() => copyToClipboard(userBot.apiKey!, 'apiKey')}
                              className="text-muted-foreground hover:text-primary p-2"
                            >
                              {copied === 'apiKey' ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                            </button>
                          </div>
                        </>
                      ) : (
                        <span className="text-sm text-muted-foreground italic">No API key — connect a bot to generate one</span>
                      )}
                    </div>
                  </div>

                  {regeneratedKey ? (
                    <div className="space-y-3 p-3 bg-green-50 border border-green-200 rounded-lg">
                      <p className="text-sm font-medium text-green-800">
                        New key generated — paste this message into your chat with your bot:
                      </p>
                      <div className="relative">
                        <pre className="text-xs bg-white p-3 rounded border border-green-200 whitespace-pre-wrap break-all text-foreground">
                          {regeneratedKey.pasteMessage}
                        </pre>
                        <Button
                          size="sm"
                          variant="outline"
                          className="absolute top-2 right-2"
                          onClick={() => copyToClipboard(regeneratedKey.pasteMessage, "pasteMessage")}
                        >
                          {copied === "pasteMessage" ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                        </Button>
                      </div>
                      <div className="flex items-center gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => copyToClipboard(regeneratedKey.apiKey, "regeneratedApiKey")}
                        >
                          {copied === "regeneratedApiKey" ? <Check className="w-3 h-3 mr-1" /> : <Key className="w-3 h-3 mr-1" />}
                          Copy key only
                        </Button>
                        <p className="text-xs text-muted-foreground">This key won't be shown again after you leave this page.</p>
                      </div>
                    </div>
                  ) : (
                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button variant="outline" size="sm" className="w-full" disabled={!hasBot || regenerateKeyMutation.isPending}>
                          <RefreshCw className={`w-3 h-3 mr-1 ${regenerateKeyMutation.isPending ? 'animate-spin' : ''}`} />
                          {regenerateKeyMutation.isPending ? "Regenerating..." : "Regenerate API Key"}
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent>
                        <AlertDialogHeader>
                          <AlertDialogTitle>Regenerate API Key?</AlertDialogTitle>
                          <AlertDialogDescription>
                            This will create a new API key for {userBot?.name || 'your bot'}. The old key will stop working immediately.
                            Only do this if your bot lost its key or you suspect it was compromised.
                          </AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel>Cancel</AlertDialogCancel>
                          <AlertDialogAction onClick={() => regenerateKeyMutation.mutate()}>
                            Regenerate Key
                          </AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  )}
                </div>
              </CardContent>
            </Card>

          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <Inbox className="w-5 h-5 text-primary" />
                <CardTitle className="text-lg">Email Stats</CardTitle>
              </div>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-3 gap-4 text-center">
                <div className="p-4 bg-muted rounded-lg">
                  <p className="text-2xl font-bold text-foreground">{messages.length}</p>
                  <p className="text-xs text-muted-foreground">Total</p>
                </div>
                <div className="p-4 bg-blue-50 rounded-lg">
                  <p className="text-2xl font-bold text-blue-600">{inboundCount}</p>
                  <p className="text-xs text-muted-foreground">Received</p>
                </div>
                <div className="p-4 bg-green-50 rounded-lg">
                  <p className="text-2xl font-bold text-green-600">{outboundCount}</p>
                  <p className="text-xs text-muted-foreground">Sent</p>
                </div>
              </div>

              <Separator className="my-4" />

              <Button 
                onClick={() => setLocation('/inbox')}
                variant="outline"
                className="w-full"
              >
                <Inbox className="w-4 h-4 mr-2" />
                View Inbox
                <ArrowRight className="w-4 h-4 ml-2" />
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

server/sendclaw/common/utils.ts.content:
import crypto from "crypto";
import { Request, Response, NextFunction } from "express";
import { MailService } from '@sendgrid/mail';
import { db } from "../../db";
import { bots, handles, securityEvents, securityIpBlocks } from "@shared/schema";
import { eq, sql, and, gte } from "drizzle-orm";

export const SENDCLAW_DOMAIN = process.env.SENDCLAW_DOMAIN || 'sendclaw.com';
export const FROM_EMAIL = process.env.SENDCLAW_FROM_EMAIL || `noreply@${SENDCLAW_DOMAIN}`;

export const REGISTRATION_COOLDOWN_SECONDS = 300;
export const DAILY_REGISTRATION_LIMIT = 5;

export const sendGridService = new MailService();
if (process.env.SENDGRID_API_KEY) {
  sendGridService.setApiKey(process.env.SENDGRID_API_KEY);
}

export function getClientIP(req: Request): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (forwarded) {
    const ips = (typeof forwarded === 'string' ? forwarded : forwarded[0]).split(',').map(ip => ip.trim());
    return ips[ips.length - 1] || req.ip || 'unknown';
  }
  return req.ip || req.socket.remoteAddress || 'unknown';
}

export async function checkRegistrationRateLimitInTx(tx: any, ip: string): Promise<{ allowed: boolean; reason?: string; retryAfter?: number }> {
  const [ipBlock] = await db
    .select({ id: securityIpBlocks.id, blockedUntil: securityIpBlocks.blockedUntil })
    .from(securityIpBlocks)
    .where(and(
      eq(securityIpBlocks.ip, ip),
      gte(securityIpBlocks.blockedUntil, new Date())
    ))
    .limit(1);

  if (ipBlock) {
    const remainingMs = ipBlock.blockedUntil.getTime() - Date.now();
    const remainingHours = Math.ceil(remainingMs / (1000 * 60 * 60));
    return {
      allowed: false,
      reason: `This IP address has been blocked due to suspicious activity. Block expires in ${remainingHours} hours.`
    };
  }

  const [result] = await tx.select({
    recentCount: sql<number>`COUNT(*) FILTER (WHERE ${bots.createdAt} > NOW() - INTERVAL '5 minutes')`,
    dailyCount: sql<number>`COUNT(*) FILTER (WHERE ${bots.createdAt} > NOW() - INTERVAL '24 hours')`
  }).from(bots).where(eq(bots.registrationIp, ip));

  const recentCount = Number(result?.recentCount ?? 0);
  const dailyCount = Number(result?.dailyCount ?? 0);

  if (recentCount > 0) {
    return {
      allowed: false,
      reason: `Please wait before registering another bot (cooldown: ${REGISTRATION_COOLDOWN_SECONDS}s)`,
      retryAfter: REGISTRATION_COOLDOWN_SECONDS
    };
  }

  if (dailyCount >= DAILY_REGISTRATION_LIMIT) {
    return {
      allowed: false,
      reason: `Daily registration limit (${DAILY_REGISTRATION_LIMIT}) reached. Try again tomorrow.`
    };
  }

  return { allowed: true };
}

export async function logSecurityEvent(eventType: string, ip: string | null, handle: string | null, botId: string | null, details: Record<string, any> = {}): Promise<void> {
  try {
    await db.insert(securityEvents).values({
      eventType,
      ip,
      handle,
      botId,
      details
    });
  } catch (err) {
    console.error('[SendClaw] Failed to log security event:', err);
  }
}

export function generateApiKey(): string {
  return `sk_${crypto.randomBytes(24).toString('hex')}`;
}

export function generateClaimToken(): string {
  const words = ['reef', 'wave', 'claw', 'tide', 'kelp', 'coral', 'shell', 'pearl'];
  const word = words[Math.floor(Math.random() * words.length)];
  const code = crypto.randomBytes(2).toString('hex').toUpperCase();
  return `${word}-${code}`;
}

export function generateMessageId(): string {
  return `<${crypto.randomUUID()}@${SENDCLAW_DOMAIN}>`;
}

export function generateThreadId(): string {
  return crypto.randomUUID();
}

export function parseSearchQuery(q: string): { 
  from?: string; 
  to?: string; 
  subject?: string; 
  after?: Date;
  before?: Date;
  keywords: string[];
} {
  const result: { from?: string; to?: string; subject?: string; after?: Date; before?: Date; keywords: string[] } = { keywords: [] };
  const tokens = q.trim().split(/\s+/);

  for (const token of tokens) {
    const lowerToken = token.toLowerCase();
    if (lowerToken.startsWith('from:')) result.from = token.slice(5);
    else if (lowerToken.startsWith('to:')) result.to = token.slice(3);
    else if (lowerToken.startsWith('subject:')) result.subject = token.slice(8);
    else if (lowerToken.startsWith('after:')) {
      const dateStr = token.slice(6);
      const parsed = new Date(dateStr);
      if (!isNaN(parsed.getTime())) result.after = parsed;
    }
    else if (lowerToken.startsWith('before:')) {
      const dateStr = token.slice(7);
      const parsed = new Date(dateStr);
      if (!isNaN(parsed.getTime())) result.before = parsed;
    }
    else if (token) result.keywords.push(token);
  }

  return result;
}

export async function getBotByApiKey(apiKey: string) {
  const [bot] = await db.select().from(bots).where(eq(bots.apiKey, apiKey)).limit(1);
  return bot;
}

export async function getHandleByAddress(address: string) {
  const [handle] = await db.select().from(handles).where(eq(handles.address, address)).limit(1);
  return handle;
}

export async function getHandleByBotId(botId: string) {
  const [handle] = await db.select().from(handles).where(eq(handles.botId, botId)).limit(1);
  return handle;
}

export async function getHandleByUserId(userId: number) {
  const [handle] = await db.select().from(handles).where(eq(handles.userId, userId)).limit(1);
  return handle;
}

export function apiKeyAuth(req: Request, res: Response, next: NextFunction) {
  const apiKey = req.headers['x-api-key'] as string || req.headers.authorization?.replace('Bearer ', '');

  if (!apiKey) {
    res.status(401).json({ error: 'API key required', hint: 'Include X-Api-Key header' });
    return;
  }

  (req as any).apiKey = apiKey;
  next();
}

export async function loadBotFromApiKey(req: Request, res: Response, next: NextFunction) {
  const apiKey = (req as any).apiKey;
  const bot = await getBotByApiKey(apiKey);

  if (!bot) {
    res.status(401).json({ error: 'Invalid API key' });
    return;
  }

  (req as any).bot = bot;
  next();
}

