import { useState } from "react";
import type { ReactNode } from "react";
import Uppy from "@uppy/core";
import type { UppyFile, UploadResult } from "@uppy/core";
import DashboardModal from "@uppy/react/dashboard-modal";
import "@uppy/core/css/style.min.css";
import "@uppy/dashboard/css/style.min.css";
import AwsS3 from "@uppy/aws-s3";
import { Button } from "@/components/ui/button";

interface ObjectUploaderProps {
  maxNumberOfFiles?: number;
  maxFileSize?: number;
  /**
   * Function to get upload parameters for each file.
   * IMPORTANT: This receives the file object - use file.name, file.size, file.type
   * to request per-file presigned URLs from your backend.
   */
  onGetUploadParameters: (
    file: UppyFile<Record<string, unknown>, Record<string, unknown>>
  ) => Promise<{
    method: "PUT";
    url: string;
    headers?: Record<string, string>;
  }>;
  onComplete?: (
    result: UploadResult<Record<string, unknown>, Record<string, unknown>>
  ) => void;
  buttonClassName?: string;
  children: ReactNode;
}

/**
 * A file upload component that renders as a button and provides a modal interface for
 * file management.
 *
 * Features:
 * - Renders as a customizable button that opens a file upload modal
 * - Provides a modal interface for:
 *   - File selection
 *   - File preview
 *   - Upload progress tracking
 *   - Upload status display
 *
 * The component uses Uppy v5 under the hood to handle all file upload functionality.
 * All file management features are automatically handled by the Uppy dashboard modal.
 *
 * @param props - Component props
 * @param props.maxNumberOfFiles - Maximum number of files allowed to be uploaded
 *   (default: 1)
 * @param props.maxFileSize - Maximum file size in bytes (default: 10MB)
 * @param props.onGetUploadParameters - Function to get upload parameters for each file.
 *   Receives the UppyFile object with file.name, file.size, file.type properties.
 *   Use these to request per-file presigned URLs from your backend. Returns method,
 *   url, and optional headers for the upload request.
 * @param props.onComplete - Callback function called when upload is complete. Typically
 *   used to make post-upload API calls to update server state and set object ACL
 *   policies.
 * @param props.buttonClassName - Optional CSS class name for the button
 * @param props.children - Content to be rendered inside the button
 */
export function ObjectUploader({
  maxNumberOfFiles = 1,
  maxFileSize = 10485760, // 10MB default
  onGetUploadParameters,
  onComplete,
  buttonClassName,
  children,
}: ObjectUploaderProps) {
  const [showModal, setShowModal] = useState(false);
  const [uppy] = useState(() =>
    new Uppy({
      restrictions: {
        maxNumberOfFiles,
        maxFileSize,
      },
      autoProceed: false,
    })
      .use(AwsS3, {
        shouldUseMultipart: false,
        getUploadParameters: onGetUploadParameters,
      })
      .on("complete", (result) => {
        onComplete?.(result);
      })
  );

  return (
    <div>
      <Button onClick={() => setShowModal(true)} className={buttonClassName}>
        {children}
      </Button>

      <DashboardModal
        uppy={uppy}
        open={showModal}
        onRequestClose={() => setShowModal(false)}
        proudlyDisplayPoweredByUppy={false}
      />
    </div>
  );
}

client/src/features/demo-simulations/Dem.content:
import { useEffect, useRef, useState, useCallback } from "react";
import { X, RotateCcw } from "lucide-react";

interface DemoSimulationPlayerProps {
  simulation: string;
  params?: Record<string, string | number>;
  width?: number;
  height?: number;
  autoPlay?: boolean;
  loop?: boolean;
  className?: string;
  onLoad?: () => void;
  onComplete?: () => void;
  onClose?: () => void;
  showControls?: boolean;
  responsive?: boolean;
  aspectRatio?: number;
}

export function DemoSimulationPlayer({
  simulation,
  params,
  width = 520,
  height = 520,
  autoPlay = true,
  loop = true,
  className = "",
  onLoad,
  onComplete,
  onClose,
  showControls = true,
  responsive = false,
  aspectRatio = 1,
}: DemoSimulationPlayerProps) {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const initialParamsRef = useRef(params);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isHoveringControls, setIsHoveringControls] = useState(false);
  const [showReplayOverlay, setShowReplayOverlay] = useState(false);

  // Only use initial params for the src URL - subsequent changes go through postMessage
  const queryString = initialParamsRef.current 
    ? '?' + Object.entries(initialParamsRef.current).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&')
    : '';
  const src = `/static/demo-simulations/${simulation}.html${queryString}`;

  const handleReplay = useCallback(() => {
    setShowReplayOverlay(false);
    iframeRef.current?.contentWindow?.postMessage({ type: 'restartDemo' }, '*');
  }, []);

  useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe) return;

    const handleLoad = () => {
      setIsLoaded(true);
      onLoad?.();
    };

    iframe.addEventListener("load", handleLoad);
    return () => iframe.removeEventListener("load", handleLoad);
  }, [onLoad]);

  // Send postMessage when params change (for seamless content switching)
  useEffect(() => {
    if (isLoaded && iframeRef.current && params?.id) {
      iframeRef.current.contentWindow?.postMessage({ 
        type: 'changeShowcase', 
        id: params.id 
      }, '*');
    }
  }, [params?.id, isLoaded]);

  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      if (event.data?.type === 'demoComplete') {
        setShowReplayOverlay(true);
        onComplete?.();
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [onComplete]);

  const containerStyle = responsive 
    ? { aspectRatio: aspectRatio, width: '100%' }
    : { width, height };

  return (
    <div
      className={`relative overflow-hidden ${responsive ? '' : 'rounded-2xl shadow-lg'} ${className}`}
      style={containerStyle}
      data-testid="demo-simulation-player"
      onMouseEnter={() => setIsHoveringControls(true)}
      onMouseLeave={() => setIsHoveringControls(false)}
    >
      <iframe
        ref={iframeRef}
        src={src}
        className="border-0 w-full h-full"
        title="Interactive Demo"
        loading="lazy"
        style={{
          opacity: isLoaded ? 1 : 0,
          transition: "opacity 0.3s ease",
        }}
      />
      {!isLoaded && (
        <div className="absolute inset-0 bg-black" />
      )}

      {showControls && onClose && isLoaded && (
        <div 
          className={`absolute top-3 right-3 z-10 transition-opacity duration-200 ${
            isHoveringControls ? 'opacity-100' : 'opacity-0'
          }`}
        >
          <button
            onClick={(e) => {
              e.stopPropagation();
              onClose();
            }}
            className="w-8 h-8 rounded-full bg-black/40 hover:bg-black/60 backdrop-blur-sm flex items-center justify-center text-white/80 hover:text-white transition-all"
            data-testid="demo-close-button"
            aria-label="Close demo"
          >
            <X size={16} />
          </button>
        </div>
      )}

      {showReplayOverlay && (
        <div 
          className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/70 backdrop-blur-sm transition-opacity duration-300"
          data-testid="demo-replay-overlay"
        >
          <button
            onClick={handleReplay}
            className="flex items-center gap-2 px-5 py-2.5 bg-white/10 hover:bg-white/20 text-white/90 font-medium rounded-lg border border-white/20 hover:border-white/30 transition-all"
            data-testid="demo-replay-button"
          >
            <RotateCcw size={16} />
            Watch Again
          </button>
        </div>
      )}
    </div>
  );
}

