        if (userResponse.ok) {
          currentUser = await userResponse.json();
        }
      } catch (e) {
        console.warn('Could not fetch user info:', e);
      }

      // Fall back to auth context user if API call failed
      if (!currentUser && user) {
        currentUser = { username: user.username, email: user.email };
      }

