scripts/generate-slugs.ts.content:
import { db } from "../server/db";
import { companies, contacts } from "../shared/schema";
import { eq, isNull } from "drizzle-orm";
import { generateCompanySlug, generateContactSlug } from "../server/utils/slug-generator";

async function generateSlugsForExistingRecords() {
  console.log("Starting slug generation...");

  const allCompanies = await db.select().from(companies).where(isNull(companies.slug));
  console.log(`Processing ${allCompanies.length} companies without slugs...`);

  for (const company of allCompanies) {
    const slug = generateCompanySlug(company.name);
    await db
      .update(companies)
      .set({ slug })
      .where(eq(companies.id, company.id));
  }
  console.log(`Updated ${allCompanies.length} company slugs.`);

  const companyMap = new Map<number, string>();
  const allCompaniesForMap = await db.select({ id: companies.id, name: companies.name }).from(companies);
  for (const c of allCompaniesForMap) {
    companyMap.set(c.id, c.name);
  }

  const allContacts = await db.select().from(contacts).where(isNull(contacts.slug));
  console.log(`Processing ${allContacts.length} contacts without slugs...`);

  for (const contact of allContacts) {
    const companyName = contact.companyId ? companyMap.get(contact.companyId) : undefined;
    const slug = generateContactSlug(contact.name, companyName, contact.role);
    await db
      .update(contacts)
      .set({ slug })
      .where(eq(contacts.id, contact.id));
  }
  console.log(`Updated ${allContacts.length} contact slugs.`);

  console.log("Slug generation complete!");
}

generateSlugsForExistingRecords()
  .then(() => process.exit(0))
  .catch((err) => {
    console.error("Error generating slugs:", err);
    process.exit(1);
  });

server/features/bot-email-security/revie.content:
import { db } from '../../db';
import { bots, messages, emailFlags, securityReports } from '@shared/schema';
import { eq, and, gte, lte, count, sql, inArray } from 'drizzle-orm';
import { reviewEmails } from './ai-reviewer';
import { sendDailyReport } from './report-generator';
import { EmailForReview, SecurityReportData, FlaggedEmailReport, DailyStats, BotStatus } from './types';

const POLL_INTERVAL_MS = 60 * 60 * 1000; // Check every hour
const RUN_HOUR = 0; // Run at midnight UTC

class BotEmailSecurityEngine {
  private intervalId: NodeJS.Timeout | null = null;
  private isProcessing = false;

  async initialize() {
    if (!process.env.REPL_DEPLOYMENT) {
      console.log('[BotEmailSecurity] Skipping in development — security reports only run in production');
      return;
    }
    console.log('[BotEmailSecurity] Initializing security review engine...');
    this.startPolling();
    console.log('[BotEmailSecurity] Engine initialized, polling started');
  }

  private startPolling() {
    if (this.intervalId) {
      console.log('[BotEmailSecurity] Polling already running');
      return;
    }

    console.log(`[BotEmailSecurity] Starting polling every ${POLL_INTERVAL_MS / 1000}s`);

    this.intervalId = setInterval(async () => {
      await this.checkAndRun();
    }, POLL_INTERVAL_MS);

    this.checkAndRun();
  }

  private async checkAndRun() {
    if (this.isProcessing) {
      console.log('[BotEmailSecurity] Already processing, skipping');
      return;
    }

    const now = new Date();

    if (now.getUTCHours() < RUN_HOUR) {
      return;
    }

    const yesterday = new Date(now);
    yesterday.setUTCDate(yesterday.getUTCDate() - 1);
    const reportDate = yesterday.toISOString().split('T')[0];

    const [existingReport] = await db
      .select({
        sentToAdmin: securityReports.sentToAdmin,
        stats: securityReports.stats,
        flaggedEmails: securityReports.flaggedEmails
      })
      .from(securityReports)
      .where(eq(securityReports.reportDate, reportDate))
      .limit(1);

    if (existingReport?.sentToAdmin) {
      return;
    }

    this.isProcessing = true;

    try {
      if (existingReport && !existingReport.sentToAdmin) {
        console.log(`[BotEmailSecurity] Report for ${reportDate} exists but email not sent, retrying send...`);
        const reportData: SecurityReportData = {
          date: reportDate,
          stats: existingReport.stats as DailyStats,
          flaggedEmails: (existingReport.flaggedEmails as FlaggedEmailReport[]) || [],
          allSubjectLines: []
        };
        const sent = await sendDailyReport(reportData);
        if (sent) {
          await db.update(securityReports)
            .set({ sentToAdmin: true })
            .where(eq(securityReports.reportDate, reportDate));
        }
        console.log(`[BotEmailSecurity] Retry send result=${sent}`);
      } else {
        console.log(`[BotEmailSecurity] Running daily review for ${reportDate}`);
        await this.runDailyReview();
      }
    } catch (error) {
      console.error('[BotEmailSecurity] Daily review failed:', error);
    } finally {
      this.isProcessing = false;
    }
  }

  async runDailyReview(targetDate?: string) {
    console.log(`[BotEmailSecurity] STEP-0: runDailyReview started, targetDate=${targetDate || 'undefined'}`);

    let reviewStart: Date;
    let reviewEnd: Date;
    let reportDate: string;

    if (targetDate) {
      // Use provided date (format: YYYY-MM-DD) in UTC
      reviewStart = new Date(targetDate + 'T00:00:00Z');
      reviewEnd = new Date(targetDate + 'T23:59:59.999Z');
      reportDate = targetDate;
    } else {
      // Default: yesterday in UTC
      reviewStart = new Date();
      reviewStart.setUTCDate(reviewStart.getUTCDate() - 1);
      reviewStart.setUTCHours(0, 0, 0, 0);

      reviewEnd = new Date();
      reviewEnd.setUTCHours(0, 0, 0, 0);

      reportDate = reviewStart.toISOString().split('T')[0];
    }

    console.log(`[BotEmailSecurity] STEP-1: Date range: ${reviewStart.toISOString()} to ${reviewEnd.toISOString()}, reportDate=${reportDate}`);

    const outboundEmails = await db
      .select({
        id: messages.id,
        botId: messages.botId,
        toAddress: messages.toAddress,
        ccAddresses: messages.ccAddresses,
        subject: messages.subject,
        bodyText: messages.bodyText,
        createdAt: messages.createdAt
      })
      .from(messages)
      .where(and(
        eq(messages.direction, 'outbound'),
        gte(messages.createdAt, reviewStart),
        lte(messages.createdAt, reviewEnd)
      ));

    const botIds = Array.from(new Set(outboundEmails.map(e => e.botId).filter((id): id is string => id !== null)));
    const botMap = new Map<string, { name: string; address: string | null }>();

    if (botIds.length > 0) {
      const botsData = await db
        .select({ id: bots.id, name: bots.name, address: bots.address })
        .from(bots)
        .where(inArray(bots.id, botIds));

      botsData.forEach(b => botMap.set(b.id, { name: b.name, address: b.address }));
    }

    const emailsForReview: EmailForReview[] = outboundEmails
      .filter(e => e.botId)
      .map(e => ({
        id: e.id,
        botId: e.botId!,
        botName: botMap.get(e.botId!)?.name || 'Unknown',
        toAddress: e.toAddress,
        ccAddresses: e.ccAddresses,
        subject: e.subject,
        bodyText: e.bodyText,
        createdAt: e.createdAt!
      }));

    console.log(`[BotEmailSecurity] STEP-2: Found ${emailsForReview.length} outbound emails to review`);

    console.log(`[BotEmailSecurity] STEP-3: Starting AI review...`);
    const reviewResult = await reviewEmails(emailsForReview);
    console.log(`[BotEmailSecurity] STEP-3: AI review complete, flagged=${reviewResult.flagged.length}`);
    const flaggedEmails: FlaggedEmailReport[] = [];

    for (const flag of reviewResult.flagged) {
      const email = emailsForReview.find(e => e.id === flag.id);
      if (!email) continue;

      // Skip if already flagged (prevents duplicates on re-runs)
      const [existingFlag] = await db.select({ id: emailFlags.id })
        .from(emailFlags)
        .where(eq(emailFlags.messageId, email.id))
        .limit(1);
      if (existingFlag) continue;

      await db.insert(emailFlags).values({
        messageId: email.id,
        botId: email.botId,
        suggestedStatus: flag.status,
        reason: flag.reason
      });

      const bot = botMap.get(email.botId);
      flaggedEmails.push({
        messageId: email.id,
        botId: email.botId,
        botName: bot?.name || 'Unknown',
        botAddress: bot?.address || 'unknown',
        toEmail: email.toAddress,
        subject: email.subject || '(no subject)',
        bodyPreview: email.bodyText || '',
        suggestedStatus: flag.status,
        reason: flag.reason,
        createdAt: email.createdAt.toISOString()
      });
    }

    console.log(`[BotEmailSecurity] STEP-4: Gathering stats...`);
    const stats = await this.gatherStats(reviewStart, reviewEnd);
    console.log(`[BotEmailSecurity] STEP-4: Stats gathered`);

    const allSubjectLines = outboundEmails
      .map(e => {
        const botAddress = e.botId ? (botMap.get(e.botId)?.address || 'unknown') : 'unknown';
        const handle = botAddress.split('@')[0];
        return `${handle} | ${e.subject || '(no subject)'}`;
      })
      .slice(0, 100);

    const reportData: SecurityReportData = {
      date: reportDate,
      stats,
      flaggedEmails,
      allSubjectLines
    };

    console.log(`[BotEmailSecurity] STEP-5: Saving report to database...`);
    await db.insert(securityReports).values({
      reportDate,
      stats: stats as any,
      flaggedEmails: flaggedEmails as any,
      sentToAdmin: false
    }).onConflictDoUpdate({
      target: securityReports.reportDate,
      set: {
        stats: stats as any,
        flaggedEmails: flaggedEmails as any
      }
    });
    console.log(`[BotEmailSecurity] STEP-5: Report saved to database`);

    console.log(`[BotEmailSecurity] STEP-6: Sending admin report email...`);
    const sent = await sendDailyReport(reportData);
    console.log(`[BotEmailSecurity] STEP-6: Admin report sent=${sent}`);

    if (sent) {
      await db.update(securityReports)
        .set({ sentToAdmin: true })
        .where(eq(securityReports.reportDate, reportDate));
    }

    console.log(`[BotEmailSecurity] COMPLETE: Flagged=${flaggedEmails.length}, Report sent=${sent}`);
  }

  private async gatherStats(start: Date, end: Date): Promise<DailyStats> {
    const [emailStats] = await db
      .select({
        inbound: count(sql`CASE WHEN ${messages.direction} = 'inbound' THEN 1 END`),
        outbound: count(sql`CASE WHEN ${messages.direction} = 'outbound' THEN 1 END`)
      })
      .from(messages)
      .where(and(
        gte(messages.createdAt, start),
        lte(messages.createdAt, end)
      ));

    const [botStats] = await db
      .select({
        newBots: count(sql`CASE WHEN ${bots.claimedAt} IS NULL THEN 1 END`),
        claimed: count(sql`CASE WHEN ${bots.claimedAt} IS NOT NULL THEN 1 END`)
      })
      .from(bots)
      .where(and(
        gte(bots.createdAt, start),
        lte(bots.createdAt, end)
      ));

    return {
      emailsInbound: Number(emailStats?.inbound) || 0,
      emailsOutbound: Number(emailStats?.outbound) || 0,
      newBots: Number(botStats?.newBots) || 0,
      botsClaimed: Number(botStats?.claimed) || 0
    };
  }

  async forceRun(targetDate?: string) {
    console.log(`[BotEmailSecurity] Force running review${targetDate ? ` for ${targetDate}` : ''}...`);
    this.isProcessing = true;
    try {
      await this.runDailyReview(targetDate);
    } finally {
      this.isProcessing = false;
    }
  }

  stop() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
      console.log('[BotEmailSecurity] Polling stopped');
    }
  }
}

export const botEmailSecurityEngine = new BotEmailSecurityEngine();

client/src/components/magic-link-registr.content:
import { useState, useEffect, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { useAuth } from "@/hooks/use-auth";
import { useRegistrationModal } from "@/hooks/use-registration-modal";
import { ArrowLeft, X, CheckCircle } from "lucide-react";
import { loadFirebase } from "@/lib/firebase";
import { useToast } from "@/hooks/use-toast";
import { sendAttributionToServer, logConversionEvent } from "@/features/attribution";

type MagicLinkRegistrationPage = "email" | "checkEmail" | "login";

export function MagicLinkRegistrationModal() {
  const { isOpen, closeModal: onClose, initialPage } = useRegistrationModal();
  const [currentPage, setCurrentPage] = useState<MagicLinkRegistrationPage>("email");
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [emailValid, setEmailValid] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [showProgress, setShowProgress] = useState(false);

  const emailInputRef = useRef<HTMLInputElement>(null);
  const nameInputRef = useRef<HTMLInputElement>(null);
  const loginEmailRef = useRef<HTMLInputElement>(null);
  const onCloseRef = useRef(onClose);

  const { user, signInWithGoogle, signInWithEmail } = useAuth();
  const { toast } = useToast();

  // Close modal when user is authenticated
  useEffect(() => {
    if (user && isOpen) {
      onClose();
    }
  }, [user, isOpen, onClose]);

  // Set initial page based on initialPage from hook
  useEffect(() => {
    if (isOpen) {
      if (initialPage === "login") {
        setCurrentPage("login");
      } else {
        setCurrentPage("email");
      }
    }
  }, [isOpen, initialPage]);

  // Lock body scroll when modal is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
      return () => {
        document.body.style.overflow = 'unset';
      };
    }
  }, [isOpen]);

  // Focus appropriate input when page changes
  useEffect(() => {
    if (!isOpen) return;

    if (currentPage === "email") {
      setTimeout(() => emailInputRef.current?.focus(), 100);
    } else if (currentPage === "login") {
      setTimeout(() => loginEmailRef.current?.focus(), 100);
    }
  }, [currentPage, isOpen]);

  // Keep onCloseRef updated
  useEffect(() => {
    onCloseRef.current = onClose;
  }, [onClose]);

  // Timer logic for checkEmail page - 2s delay then 5s countdown
  useEffect(() => {
    if (currentPage !== "checkEmail") {
      setShowProgress(false);
      setCountdown(null);
      return;
    }

    const delayTimer = setTimeout(() => {
      setShowProgress(true);
      setCountdown(5);
    }, 2000);

    return () => clearTimeout(delayTimer);
  }, [currentPage]);

  // Countdown decrement
  useEffect(() => {
    if (countdown === null) return;

    if (countdown <= 0) {
      onCloseRef.current();
      return;
    }

    const timer = setTimeout(() => {
      setCountdown(prev => (prev !== null ? prev - 1 : null));
    }, 1000);

    return () => clearTimeout(timer);
  }, [countdown]);

  const validateEmail = (email: string) => {
    const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const isValid = regex.test(email);
    setEmailValid(isValid);
    return isValid;
  };

  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setEmail(value);
    validateEmail(value);
  };

  const handleGoogleSignIn = async () => {
    try {
      const { isNewUser } = await signInWithGoogle();

      if (isNewUser) {
        window.dataLayer?.push({ event: 'registration_complete' });
        sendAttributionToServer().catch(() => {});
        logConversionEvent('registration_complete').catch(() => {});
      }

      onClose();
    } catch (error) {
      console.error("Google sign-in failed:", error);
    }
  };

  const handleSendEmailLink = async () => {
    if (!validateEmail(email) || !name.trim()) {
      toast({
        title: "Missing Information",
        description: "Please enter your email and name",
        variant: "destructive",
      });
      return;
    }

    setIsSending(true);

    try {
      const { auth } = await loadFirebase();
      const { 
        createUserWithEmailAndPassword, 
        updateProfile, 
        sendPasswordResetEmail 
      } = await import("firebase/auth");

      // 1. Generate temporary password
      const tempPassword = crypto.randomUUID().replace(/-/g, '').slice(0, 16);

      // 2. Create user in Firebase with temp password
      const result = await createUserWithEmailAndPassword(auth, email, tempPassword);

      // 3. Set display name
      if (result.user) {
        await updateProfile(result.user, { displayName: name });
      }

      // 4. Sync with backend (creates user in PostgreSQL)
      const token = await result.user.getIdToken(true);
      await fetch('/api/google-auth', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        credentials: 'include',
        body: JSON.stringify({
          email: result.user.email,
          username: name,
          firebaseUid: result.user.uid
        })
      });

      // 5. Send password reset email so user can set their real password
      await sendPasswordResetEmail(auth, email);

      // Track registration complete
      window.dataLayer?.push({ event: 'registration_complete' });
      sendAttributionToServer().catch(() => {});
      logConversionEvent('registration_complete').catch(() => {});

      setCurrentPage("checkEmail");

    } catch (error: any) {
      console.error("Registration error:", error);

      if (error.code === 'auth/email-already-in-use') {
        // User already exists - prompt to login instead
        toast({
          title: "Account Already Exists",
          description: "This email is already registered. Please use the login option.",
          variant: "destructive",
        });
        setCurrentPage("login");
      } else if (error.code === 'auth/invalid-email') {
        toast({
          title: "Invalid Email",
          description: "Please enter a valid email address",
          variant: "destructive",
        });
      } else {
        toast({
          title: "Registration Failed",
          description: error.message || "Please try again.",
          variant: "destructive",
        });
      }
    } finally {
      setIsSending(false);
    }
  };

  const handleLoginSubmit = async () => {
    if (!validateEmail(email) || !password) {
      return;
    }

    try {
      await signInWithEmail(email, password);
      onClose();
    } catch (error: any) {
      console.error("Login error:", error);
      toast({
        title: "Login Failed",
        description: error.message || "Invalid email or password.",
        variant: "destructive",
      });
    }
  };

  const handleForgotPassword = async () => {
    if (!validateEmail(email)) {
      toast({
